begin;

-- Idempotent core case/answer-key seed. Never set DA_DUYET.
insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'thung-o-loet-da-day-ta-trang',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"thung-o-loet-da-day-ta-trang","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bụng dữ dội, bụng cứng như gỗ","setting":"capcuu","level":"Dễ","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":52,"sex":"nam","patient_label":"Ông Võ Văn Thịnh"},"presentation":{"intro":"Ông được người nhà đưa vào cấp cứu vì đau bụng đột ngột, dữ dội vùng thượng vị cách đây 4 giờ, sau đó đau lan khắp bụng. Ông có tiền sử đau dạ dày nhiều năm và hay uống thuốc giảm đau xương khớp.","place":"Khoa Cấp cứu","clock":"23:10","night":true},"vitals":{"hr":112,"sbp":100,"dbp":64,"rr":24,"temperature_c":37.9,"spo2":96},"history":[{"question":"Đau bắt đầu như thế nào, ở đâu, mức độ ra sao?","response":"Đột ngột như dao đâm ở vùng thượng vị cách đây khoảng 4 giờ, sau đó lan khắp bụng. Đau 9 trên 10, không dám cử động."},{"question":"Trước đây có đau dạ dày, đã nội soi chưa? Có dùng thuốc giảm đau, kháng viêm không?","response":"Đau thượng vị âm ỉ nhiều năm, chưa nội soi. Hay uống ibuprofen và diclofenac vì đau khớp gối."},{"question":"Có nôn, nôn ra máu hoặc đi cầu phân đen không?","response":"Buồn nôn, nôn một lần ra dịch vàng. Không nôn ra máu, phân vàng."},{"question":"Đau có lan lên vai không? Thay đổi tư thế hay thở sâu có đau thêm không?","response":"Đau lan lên vai phải. Ho hoặc hít sâu đau tăng, nằm im co gối thì đỡ hơn."},{"question":"Còn trung tiện được không? Bụng có chướng không?","response":"Còn trung tiện, bụng căng."},{"question":"Có sốt hoặc rét run không?","response":"Hơi nóng người, không rét run."},{"question":"Có uống rượu hoặc ăn no trước khi đau không?","response":"Có uống vài ly rượu và ăn tối no rồi mới đau."},{"question":"Có bệnh tim mạch, đái tháo đường, dị ứng thuốc không?","response":"Không có bệnh nền, chưa biết dị ứng thuốc."}],"examination":[{"group":"K","item":"Tư thế và vẻ mặt","finding":"Nằm im co gối, mặt tái, vẻ đau đớn, vã mồ hôi."},{"group":"K","item":"Hình dạng bụng","finding":"Bụng hơi chướng, di động theo nhịp thở kém."},{"group":"K","item":"Giọng nói và hơi thở","finding":"Nói ngắn từng câu, thở nông nhanh."},{"group":"K","item":"Mùi hơi thở","finding":"Có mùi rượu nhẹ."},{"group":"K","item":"Mạch và đầu chi","finding":"Mạch nhanh, nhỏ; đầu chi mát, ẩm."},{"group":"K","item":"Sờ nắn bụng","finding":"Bụng cứng như gỗ, co cứng thành bụng toàn bộ, đau nhiều nhất ở thượng vị, phản ứng dội dương tính."},{"group":"K","item":"Gõ bụng","finding":"Mất vùng đục trước gan."},{"group":"K","item":"Nghe nhu động ruột","finding":"Nhu động ruột giảm rõ."},{"group":"K","item":"Thăm trực tràng","finding":"Túi cùng Douglas căng đau nhẹ, không có máu trên găng."}],"investigations":[{"name":"X-quang ngực thẳng và bụng đứng không chuẩn bị","duration_minutes":10,"result":"Liềm hơi dưới vòm hoành phải."},{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu 15,8 G/L, tăng bạch cầu đa nhân trung tính; Hb 13,5 g/dL."},{"name":"Nhóm máu, đông máu, sinh hóa cơ bản","duration_minutes":15,"result":"Trong giới hạn cho phép phẫu thuật; creatinin bình thường."},{"name":"Siêu âm bụng","duration_minutes":10,"result":"Có hơi và dịch tự do ổ bụng lượng ít, không sỏi túi mật."},{"name":"Amylase máu","duration_minutes":15,"result":"Tăng nhẹ, không phù hợp viêm tụy cấp điển hình."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp nhanh xoang, không có ST chênh."},{"name":"Nội soi dạ dày tá tràng","duration_minutes":25,"result":"Không nên làm khi nghi thủng tạng rỗng: bơm hơi làm tăng thoát hơi và dịch tiêu hóa vào ổ bụng."}],"choices":{"diagnosis":{"ydx":["Viêm túi mật cấp","Nhồi máu cơ tim thành dưới","Tắc ruột cơ học","Viêm tụy cấp","Thủng ổ loét dạ dày tá tràng gây viêm phúc mạc","Viêm ruột thừa cấp"]},"actions":["Chụp CT bụng có cản quang để tìm thêm tổn thương trước khi quyết định mổ","Đặt sonde dạ dày hút liên tục và sonde tiểu theo dõi nước tiểu","Cho uống thuốc kháng acid, giảm đau và hẹn theo dõi ngoại trú","Hội chẩn ngoại khoa ngay để chuẩn bị phẫu thuật cấp cứu kiểm soát nguồn","Hồi sức dịch tinh thể tĩnh mạch và giảm đau đường tĩnh mạch theo phác đồ","Cho uống hỗn dịch bari để chụp dạ dày","Giải thích tình trạng cho gia đình và chuẩn bị hồ sơ trước mổ","Dùng kháng sinh phổ rộng đường tĩnh mạch và thuốc ức chế bơm proton đường tĩnh mạch","Cho nhịn ăn uống hoàn toàn, đặt hai đường truyền tĩnh mạch, theo dõi monitor"]}}'::jsonb,
  '4348a317443aca52fa958f34c41f898cd3213b158c2e21b9aa5aeff0fca9fc66'
)
on conflict (case_id) do update set
