  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'thung-o-loet-da-day-ta-trang',
  '{"schema_version":"1.0.0","case_id":"thung-o-loet-da-day-ta-trang","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ptu-wses-2020","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/31921329/","title":"World Society of Emergency Surgery, Perforated and Bleeding Peptic Ulcer: WSES Guidelines, 2020.","organization":null,"year_version":null,"citation":"World Society of Emergency Surgery, Perforated and Bleeding Peptic Ulcer: WSES Guidelines, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2],"examination_essential_indices":[0,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thủng ổ loét dạ dày tá tràng gây viêm phúc mạc","credit":"full"},{"text":"Viêm tụy cấp","credit":"none"},{"text":"Nhồi máu cơ tim thành dưới","credit":"none"},{"text":"Tắc ruột cơ học","credit":"none"},{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Viêm túi mật cấp","credit":"none"}]},"action_options":[{"text":"Cho nhịn ăn uống hoàn toàn, đặt hai đường truyền tĩnh mạch, theo dõi monitor","time_minutes":2,"grade":"critical","rationale":"Có dấu hiệu viêm phúc mạc, mạch nhanh, huyết áp thấp biên."},{"text":"Hồi sức dịch tinh thể tĩnh mạch và giảm đau đường tĩnh mạch theo phác đồ","time_minutes":3,"grade":"critical","rationale":"Bù thể tích mất vào ổ bụng; giảm đau đúng cách không làm che lấp chẩn đoán."},{"text":"Hội chẩn ngoại khoa ngay để chuẩn bị phẫu thuật cấp cứu kiểm soát nguồn","time_minutes":2,"grade":"critical","rationale":"Thủng tạng rỗng kèm viêm phúc mạc cần xử trí ngoại khoa sớm; kỹ thuật mổ phụ thuộc vị trí, kích thước lỗ thủng và tình trạng người bệnh."},{"text":"Dùng kháng sinh phổ rộng đường tĩnh mạch và thuốc ức chế bơm proton đường tĩnh mạch","time_minutes":2,"grade":"recommended","rationale":"Hạn chế nhiễm khuẩn ổ bụng, giảm tiết acid."},{"text":"Đặt sonde dạ dày hút liên tục và sonde tiểu theo dõi nước tiểu","time_minutes":3,"grade":"recommended","rationale":"Giảm dịch tiêu hóa tràn vào ổ bụng, đánh giá tưới máu."},{"text":"Giải thích tình trạng cho gia đình và chuẩn bị hồ sơ trước mổ","time_minutes":2,"grade":"recommended","rationale":"Hoàn thiện thủ tục đồng ý phẫu thuật."},{"text":"Chụp CT bụng có cản quang để tìm thêm tổn thương trước khi quyết định mổ","time_minutes":40,"grade":"waste","rationale":"Đã đủ chẩn đoán bằng lâm sàng và X-quang, chụp thêm làm chậm mổ."},{"text":"Cho uống hỗn dịch bari để chụp dạ dày","time_minutes":5,"grade":"harmful","rationale":"Bari thoát qua lỗ thủng gây viêm phúc mạc bari, rất khó điều trị."},{"text":"Cho uống thuốc kháng acid, giảm đau và hẹn theo dõi ngoại trú","time_minutes":3,"grade":"harmful","rationale":"Trì hoãn xử trí viêm phúc mạc, nguy cơ sốc nhiễm khuẩn."}],"teaching_explanation":"Đau bụng đột ngột kèm dấu viêm phúc mạc và khí tự do gợi ý thủng tạng rỗng. Ưu tiên hồi sức, nhịn ăn, kháng sinh và hội chẩn ngoại khoa sớm. CT là phương tiện được khuyến nghị khi nghi thủng nếu có thể thực hiện kịp thời và người bệnh phù hợp; X-quang có khí tự do kèm bệnh cảnh điển hình có thể đủ để quyết định thăm dò phẫu thuật, vì vậy không nên biến CT thành đáp án sai tuyệt đối. Không nội soi bơm hơi khi đang nghi thủng."}'::jsonb,
  '3774b767cdaeca73b5c18ef6432d6299df5be5c1f62c950f1271548e3efcc9a1'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'ngo-doc-phospho-huu-co',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"ngo-doc-phospho-huu-co","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Uống nhầm thuốc trừ sâu, vã mồ hôi, khó thở","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":47,"sex":"nam","patient_label":"Ông Lương Văn Sáu"},"presentation":{"intro":"Ông được người nhà đưa vào cấp cứu sau khi uống nhầm chai thuốc trừ sâu đựng trong chai nước ngọt cách đây khoảng 45 phút. Người nhà mang theo chai thuốc, có mùi rất hắc. Ông nôn nhiều, chảy dãi và khó thở.","place":"Khoa Cấp cứu","clock":"17:35","night":false},"vitals":{"hr":52,"sbp":100,"dbp":60,"rr":28,"temperature_c":36.8,"spo2":88},"history":[{"question":"Ông uống phải thứ gì, bao nhiêu và cách đây bao lâu?","response":"Tôi tưởng chai nước ngọt, uống nhầm khoảng nửa ly, cách đây chừng 45 phút."},{"question":"Hiện ông thấy những gì?","response":"Buồn nôn, nôn nhiều, đau quặn bụng, chảy nước dãi, đổ mồ hôi, tức ngực và khó thở."},{"question":"Người nhà có biết tên hoạt chất, nhãn chai ghi gì không?","response":"Nhãn ghi thuốc trừ sâu nhóm phospho hữu cơ, mùi rất hắc."},{"question":"Ông có ho nhiều đờm, khò khè không?","response":"Ho đờm nhiều, thở khò khè, tức ngực."},{"question":"Mắt nhìn thế nào?","response":"Nhìn mờ, tối."},{"question":"Có đại tiểu tiện không tự chủ, tiêu chảy không?","response":"Đã đi tiêu phân lỏng một lần, són tiểu."},{"question":"Có giật cơ, yếu tay chân không?","response":"Thấy giật ở mặt và đùi, chân tay yếu."},{"question":"Có bệnh nền, dị ứng thuốc, uống rượu cùng lúc không?","response":"Không bệnh nền, không dị ứng, không uống rượu hôm nay."}],"examination":[{"group":"K","item":"Đồng tử","finding":"Co nhỏ như đầu đinh ghim hai bên, phản xạ ánh sáng chậm."},{"group":"K","item":"Da và tiết dịch","finding":"Vã mồ hôi đầm đìa, chảy nhiều nước dãi, chảy nước mắt."},{"group":"K","item":"Co giật cơ","finding":"Rung giật các bó cơ ở mặt và chi."},{"group":"K","item":"Mùi hơi thở và quần áo","finding":"Mùi hắc đặc trưng của thuốc trừ sâu phospho hữu cơ."},{"group":"K","item":"Tiếng thở","finding":"Thở khò khè, ran ngáy ẩm, đờm dãi nhiều."},{"group":"K","item":"Mạch","finding":"Mạch chậm 52 lần mỗi phút, yếu."},{"group":"K","item":"Nghe phổi","finding":"Ran ẩm và ran rít lan tỏa hai phế trường do tăng tiết và co thắt phế quản."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, tăng nhu động ruột, không phản ứng thành bụng."},{"group":"K","item":"Tri giác","finding":"Li bì nhưng gọi trả lời được, Glasgow 13 điểm."}],"investigations":[{"name":"Khí máu động mạch","duration_minutes":8,"result":"Thiếu oxy máu, toan hô hấp nhẹ."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp chậm xoang, QTc kéo dài nhẹ, không block nhĩ thất."},{"name":"Hoạt tính cholinesterase huyết tương","duration_minutes":30,"result":"Giảm rõ, xác nhận ức chế cholinesterase. Không chờ kết quả mới xử trí."},{"name":"Đường huyết mao mạch","duration_minutes":3,"result":"6,4 mmol/L."},{"name":"Điện giải đồ, chức năng gan thận","duration_minutes":15,"result":"Kali giảm nhẹ, chức năng thận bình thường."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Mờ rải rác hai phế trường, không tràn khí."},{"name":"CT sọ não không cản quang","duration_minutes":25,"result":"Không có chỉ định, không chấn thương, không dấu thần kinh khu trú."}],"choices":{"diagnosis":{"ydx":["Ngộ độc cấp thuốc trừ sâu phospho hữu cơ (hội chứng cholinergic)","Cơn hen phế quản nặng","Ngộ độc rượu methanol","Nhồi máu cơ tim cấp","Ngộ độc paraquat","Sốc phản vệ"]},"actions":["Tiêm tĩnh mạch atropin, lặp lại và tăng liều đến khi đạt dấu hiệu atropin hóa (hết ran phổi, mạch lên, khô dịch tiết)","Dùng succinylcholin để đặt nội khí quản","Cho uống sữa hoặc dầu ăn để giảm hấp thu độc chất","Thiết lập đường truyền tĩnh mạch, lấy máu xét nghiệm và truyền dịch","Gây nôn bằng móc họng hoặc cho uống nước muối đậm đặc","Cởi bỏ quần áo nhiễm, rửa da bằng nước sạch và xà phòng; nhân viên mang găng và áo choàng","Bảo đảm đường thở, hút đờm dãi, thở oxy, gắn monitor, sẵn sàng đặt nội khí quản và thở máy","Chuyển hồi sức, theo dõi 24 đến 96 giờ","Chỉ cân nhắc khử độc đường tiêu hóa ở người đến rất sớm sau uống lượng độc đáng kể, sau khi đã ổn định và bảo vệ đường thở, theo tư vấn độc chất/phác đồ cơ sở","Cân nhắc pralidoxim sau khi đã atropin hóa theo phác đồ cơ sở","Cho furosemid để giảm ran ẩm"]}}'::jsonb,
  '529e1e8d101a61f326643d2643aaf725e8751bac9dab4fecaa33ae03de8a7979'
)
on conflict (case_id) do update set
  schema_version = excluded.schema_version,
  data_origin = excluded.data_origin,
  review_status = excluded.review_status,
  public_bundle = excluded.public_bundle,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.answer_keys
