values (
  'ngo-doc-phospho-huu-co',
  '{"schema_version":"1.0.0","case_id":"ngo-doc-phospho-huu-co","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-byt-3610-2015","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-3610-qd-byt-2015-ve-viec-ban-hanh-tai-lieu-chuyen-mon-huong-dan-chan-doan-va-xu-tri-ngo-doc-319645-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và xử trí ngộ độc, Quyết định 3610/QĐ-BYT, 2015.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và xử trí ngộ độc, Quyết định 3610/QĐ-BYT, 2015.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-lavage-aact-2013","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/23418938/","title":"AACT/EAPCCT, Position Paper Update: Gastric Lavage for Gastrointestinal Decontamination, 2013.","organization":null,"year_version":null,"citation":"AACT/EAPCCT, Position Paper Update: Gastric Lavage for Gastrointestinal Decontamination, 2013.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,3,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Ngộ độc cấp thuốc trừ sâu phospho hữu cơ (hội chứng cholinergic)","credit":"full"},{"text":"Ngộ độc paraquat","credit":"none"},{"text":"Cơn hen phế quản nặng","credit":"none"},{"text":"Nhồi máu cơ tim cấp","credit":"none"},{"text":"Ngộ độc rượu methanol","credit":"none"},{"text":"Sốc phản vệ","credit":"none"}]},"action_options":[{"text":"Bảo đảm đường thở, hút đờm dãi, thở oxy, gắn monitor, sẵn sàng đặt nội khí quản và thở máy","time_minutes":2,"grade":"critical","rationale":"SpO2 88% với tăng tiết phế quản nhiều, nguy cơ suy hô hấp."},{"text":"Tiêm tĩnh mạch atropin, lặp lại và tăng liều đến khi đạt dấu hiệu atropin hóa (hết ran phổi, mạch lên, khô dịch tiết)","time_minutes":3,"grade":"critical","rationale":"Atropin là thuốc giải chính đối với biểu hiện muscarinic; mục tiêu là khô dịch tiết phế quản, không phải giãn đồng tử."},{"text":"Thiết lập đường truyền tĩnh mạch, lấy máu xét nghiệm và truyền dịch","time_minutes":2,"grade":"critical","rationale":"Cần đường truyền để dùng atropin liên tục và bù dịch mất qua nôn, tiêu chảy."},{"text":"Cởi bỏ quần áo nhiễm, rửa da bằng nước sạch và xà phòng; nhân viên mang găng và áo choàng","time_minutes":2,"grade":"recommended","rationale":"Ngừng hấp thu qua da và bảo vệ nhân viên y tế."},{"text":"Chỉ cân nhắc khử độc đường tiêu hóa ở người đến rất sớm sau uống lượng độc đáng kể, sau khi đã ổn định và bảo vệ đường thở, theo tư vấn độc chất/phác đồ cơ sở","time_minutes":6,"grade":"recommended","rationale":"Lợi ích của rửa dạ dày hoặc than hoạt chưa chắc chắn; không được làm trước hồi sức, oxy và atropin, và không gây nôn cưỡng bức."},{"text":"Cân nhắc pralidoxim sau khi đã atropin hóa theo phác đồ cơ sở","time_minutes":3,"grade":"recommended","rationale":"Có thể tái hoạt hóa cholinesterase trong ngộ độc nặng; hiệu quả còn tranh luận."},{"text":"Chuyển hồi sức, theo dõi 24 đến 96 giờ","time_minutes":2,"grade":"recommended","rationale":"Nguy cơ suy hô hấp muộn do hội chứng trung gian và tái phát triệu chứng."},{"text":"Cho uống sữa hoặc dầu ăn để giảm hấp thu độc chất","time_minutes":1,"grade":"waste","rationale":"Không có bằng chứng lợi ích, dầu có thể tăng hấp thu chất tan trong mỡ."},{"text":"Cho furosemid để giảm ran ẩm","time_minutes":2,"grade":"waste","rationale":"Ran ẩm do tăng tiết phế quản chứ không do ứ dịch; cần atropin, không phải lợi tiểu."},{"text":"Gây nôn bằng móc họng hoặc cho uống nước muối đậm đặc","time_minutes":1,"grade":"harmful","rationale":"Nguy cơ hít sặc dịch chứa dung môi, bệnh nhân li bì."},{"text":"Dùng succinylcholin để đặt nội khí quản","time_minutes":2,"grade":"harmful","rationale":"Ức chế cholinesterase làm kéo dài tác dụng succinylcholin, gây liệt cơ kéo dài."}],"teaching_explanation":"Ngộ độc phospho hữu cơ gây hội chứng cholinergic: tăng tiết, co đồng tử, nhịp chậm, ran phổi và có thể yếu cơ. Ưu tiên đường thở, oxy/thông khí và atropin chuẩn độ theo dịch tiết-phổi; không chờ cholinesterase mới điều trị. Khử độc đường tiêu hóa chỉ cân nhắc chọn lọc sau ổn định, đặc biệt khi đến rất sớm, vì bằng chứng lợi ích hạn chế và có nguy cơ hít sặc. Tránh succinylcholine khi có thể do tác dụng có thể kéo dài."}'::jsonb,
  'e2c720325310ee065a9df703add9cde6fd56928a2c671b36ba3e7a95acb9a3c7'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'nhiem-toan-ceton-dai-thao-duong',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"nhiem-toan-ceton-dai-thao-duong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Nôn, đau bụng, thở sâu ở người đái tháo đường","setting":"capcuu","level":"Trung bình","track":"noi","mode":"tay","specialty":null,"demographics":{"age":24,"sex":"nữ","patient_label":"Chị Trần Thu Hà"},"presentation":{"intro":"Chị Hà được bạn đưa vào cấp cứu vì mệt lả, buồn nôn, nôn nhiều và đau bụng hai ngày nay. Chị bị đái tháo đường typ 1 từ năm 15 tuổi, ba ngày gần đây bỏ tiêm insulin vì đau họng và ăn kém.","place":"Khoa Cấp cứu","clock":"10:05","night":false},"vitals":{"hr":124,"sbp":92,"dbp":56,"rr":30,"temperature_c":37.8,"spo2":98},"history":[{"question":"Các triệu chứng bắt đầu khi nào và diễn tiến ra sao?","response":"Hai ngày nay khát nước nhiều, tiểu nhiều, mệt, buồn nôn và nôn nhiều lần."},{"question":"Chị có bệnh nền gì, đang dùng insulin thế nào?","response":"Đái tháo đường typ 1 từ năm 15 tuổi, trước đây tiêm insulin mỗi ngày."},{"question":"Gần đây chị có ngưng hoặc giảm insulin, hoặc có bệnh gì kèm theo không?","response":"Ba ngày nay bỏ tiêm vì sợ hạ đường huyết khi ăn kém. Đau họng, sốt nhẹ."},{"question":"Chị có thấy thở nhanh, sâu hoặc hơi thở có mùi lạ không?","response":"Thấy thở nhanh, sâu, miệng có mùi như trái cây chín."},{"question":"Đau bụng ở đâu, tính chất thế nào?","response":"Đau âm ỉ khắp bụng, không rõ chỗ, kèm buồn nôn."},{"question":"Có đái buốt, ho, tiêu chảy không?","response":"Đau họng, không đái buốt, không tiêu chảy."},{"question":"Có thấy lơ mơ, buồn ngủ nhiều không?","response":"Mệt nhiều, buồn ngủ nhưng vẫn tỉnh, trả lời đúng."},{"question":"Kinh nguyệt, có khả năng mang thai không?","response":"Kinh lần cuối cách đây 2 tuần, không có thai."},{"question":"Có dị ứng thuốc không?","response":"Không."}],"examination":[{"group":"K","item":"Kiểu thở","finding":"Thở nhanh, sâu, đều kiểu Kussmaul."},{"group":"K","item":"Da và niêm mạc","finding":"Da khô, niêm mạc khô, nếp véo da mất chậm, mắt trũng."},{"group":"K","item":"Tri giác","finding":"Tỉnh, hơi lơ mơ, trả lời chậm."},{"group":"K","item":"Hơi thở","finding":"Mùi aceton như trái cây chín."},{"group":"K","item":"Giọng nói","finding":"Nói chậm, ngắt quãng vì thở nhanh."},{"group":"K","item":"Mạch và đầu chi","finding":"Mạch nhanh, nhỏ; đầu chi mát."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn đau lan tỏa nhẹ, không phản ứng thành bụng."},{"group":"K","item":"Khám họng","finding":"Họng đỏ, amidan viêm nhẹ, là yếu tố khởi phát có thể."},{"group":"K","item":"Khám tim phổi","finding":"Tim nhanh đều; phổi rì rào phế nang rõ, không ran."}],"investigations":[{"name":"Đường huyết mao mạch","duration_minutes":2,"result":"28,4 mmol/L."},{"name":"Ceton máu hoặc ceton niệu","duration_minutes":5,"result":"Ceton máu tăng cao, ceton niệu dương tính mạnh."},{"name":"Khí máu động mạch","duration_minutes":8,"result":"pH 7,08; HCO3 7 mmol/L; PaCO2 20 mmHg: toan chuyển hóa tăng khoảng trống anion."},{"name":"Điện giải đồ, ure, creatinin","duration_minutes":10,"result":"Natri 131 mmol/L, kali 5,0 mmol/L, creatinin tăng nhẹ do mất nước."},{"name":"Công thức máu và CRP","duration_minutes":15,"result":"Bạch cầu 17 G/L, CRP tăng nhẹ, phù hợp stress hoặc nhiễm khuẩn hô hấp."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp nhanh xoang, sóng T cao nhẹ, không loạn nhịp nguy hiểm."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Không có đông đặc."},{"name":"CT bụng có cản quang","duration_minutes":40,"result":"Không có chỉ định; đau bụng do toan ceton thường giảm khi điều trị nền, cản quang là gánh nặng thêm cho thận đang mất nước."}],"choices":{"diagnosis":{"ydx":["Viêm ruột thừa cấp","Viêm tụy cấp","Viêm dạ dày ruột cấp mất nước","Hạ đường huyết nặng","Nhiễm toan ceton do đái tháo đường typ 1","Tăng áp lực thẩm thấu máu tăng đường huyết (không toan ceton)"]},"actions":["Theo dõi đường huyết mỗi giờ, kali và khí máu định kỳ; bổ sung kali theo kết quả","Dùng kháng sinh phổ rộng thường quy khi chưa có bằng chứng nhiễm khuẩn","Tìm và điều trị yếu tố khởi phát (viêm họng, nhiễm khuẩn)","Thêm dung dịch có glucose khi đường huyết xuống dưới ngưỡng theo phác đồ và vẫn tiếp tục insulin","Truyền insulin thường tĩnh mạch liên tục sau khi đã biết kali máu không thấp","Truyền dung dịch glucose 5% thay cho NaCl 0,9% ở giai đoạn đầu","Đánh giá ABC, gắn monitor, đặt hai đường truyền tĩnh mạch ngoại vi","Truyền insulin tĩnh mạch liều cao ngay, không chờ kết quả kali máu","Truyền natri bicarbonat thường quy","Bù dịch NaCl 0,9% tĩnh mạch nhanh trong giờ đầu rồi giảm tốc độ theo đáp ứng","Chuyển hồi sức hoặc đơn vị theo dõi sát, tư vấn không bỏ insulin nền"]}}'::jsonb,
  'c7f8d0b30cffbfaf97680ac7abec2f4f58d2a45e1bcceb6773b767bd77695ff7'
)
on conflict (case_id) do update set
