insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'nhiem-toan-ceton-dai-thao-duong',
  '{"schema_version":"1.0.0","case_id":"nhiem-toan-ceton-dai-thao-duong","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-dka-ada-2024-3ecf8c7e7f15","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/39052901/","title":"ADA/EASD/JBDS/AACE/DTS, Hyperglycemic Crises in Adults With Diabetes: A Consensus Report, 2024.","organization":null,"year_version":null,"citation":"ADA/EASD/JBDS/AACE/DTS, Hyperglycemic Crises in Adults With Diabetes: A Consensus Report, 2024.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,3,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"neutral"},{"index":7,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Nhiễm toan ceton do đái tháo đường typ 1","credit":"full"},{"text":"Tăng áp lực thẩm thấu máu tăng đường huyết (không toan ceton)","credit":"none"},{"text":"Hạ đường huyết nặng","credit":"none"},{"text":"Viêm tụy cấp","credit":"none"},{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Viêm dạ dày ruột cấp mất nước","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, gắn monitor, đặt hai đường truyền tĩnh mạch ngoại vi","time_minutes":2,"grade":"critical","rationale":"Mất nước nặng, nhịp nhanh, toan chuyển hóa nặng."},{"text":"Bù dịch NaCl 0,9% tĩnh mạch nhanh trong giờ đầu rồi giảm tốc độ theo đáp ứng","time_minutes":3,"grade":"critical","rationale":"Mất dịch lớn; bù dịch là bước đầu tiên và quan trọng nhất."},{"text":"Truyền insulin thường tĩnh mạch liên tục sau khi đã biết kali máu không thấp","time_minutes":3,"grade":"critical","rationale":"Ngăn tạo ceton và hạ đường huyết; phải biết kali trước để tránh hạ kali nặng."},{"text":"Theo dõi đường huyết mỗi giờ, kali và khí máu định kỳ; bổ sung kali theo kết quả","time_minutes":2,"grade":"recommended","rationale":"Insulin đưa kali vào tế bào nên kali máu giảm nhanh."},{"text":"Thêm dung dịch có glucose khi đường huyết xuống dưới ngưỡng theo phác đồ và vẫn tiếp tục insulin","time_minutes":2,"grade":"recommended","rationale":"Để tiếp tục khử ceton mà không gây hạ đường huyết."},{"text":"Tìm và điều trị yếu tố khởi phát (viêm họng, nhiễm khuẩn)","time_minutes":3,"grade":"recommended","rationale":"Nhiễm trùng và bỏ insulin là nguyên nhân thường gặp."},{"text":"Chuyển hồi sức hoặc đơn vị theo dõi sát, tư vấn không bỏ insulin nền","time_minutes":2,"grade":"recommended","rationale":"Nguy cơ tái phát; cần giáo dục bệnh nhân."},{"text":"Truyền natri bicarbonat thường quy","time_minutes":2,"grade":"waste","rationale":"pH 7,08 chưa ở mức toan rất nặng; đồng thuận quốc tế 2024 chỉ cân nhắc bicarbonat khi pH < 7,0 vì dùng thường quy không cải thiện kết cục và có thể gây hạ kali."},{"text":"Dùng kháng sinh phổ rộng thường quy khi chưa có bằng chứng nhiễm khuẩn","time_minutes":3,"grade":"waste","rationale":"Họng viêm nhẹ, chưa có chỉ định."},{"text":"Truyền insulin tĩnh mạch liều cao ngay, không chờ kết quả kali máu","time_minutes":1,"grade":"harmful","rationale":"Kali có thể tụt nhanh, gây loạn nhịp và ngừng tim."},{"text":"Truyền dung dịch glucose 5% thay cho NaCl 0,9% ở giai đoạn đầu","time_minutes":1,"grade":"harmful","rationale":"Đường huyết 28 mmol/L, dung dịch glucose làm tăng thêm áp lực thẩm thấu và không bù được thể tích."}],"teaching_explanation":"Nhiễm toan ceton gồm tăng đường huyết hoặc tiền sử đái tháo đường, tăng ceton và toan chuyển hóa. Trình tự ưu tiên: bù dịch, đánh giá và bù kali thích hợp, insulin, theo dõi sát rồi tìm yếu tố khởi phát. Nếu kali <3,5 mmol/L, trì hoãn insulin cho đến khi kali >3,5 mmol/L. Bicarbonat không dùng thường quy; chỉ cân nhắc khi pH <7,0."}'::jsonb,
  '7fd5c2a0db17b2d423681be1667dbdfa437f6cc4eb6bc9fd7009f29ce2f2ac94'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'vo-lach-chan-thuong-bung-kin',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"vo-lach-chan-thuong-bung-kin","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tai nạn xe máy, đau hạ sườn trái, choáng","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":24,"sex":"nam","patient_label":"Anh Nguyễn Hoàng Long"},"presentation":{"intro":"Anh Long được xe cấp cứu đưa vào sau khi đi xe máy tông vào xe tải đỗ, hạ sườn trái đập mạnh vào tay lái cách đây 90 phút. Anh còn tỉnh, kêu đau bụng trên trái, hoa mắt và khát nước.","place":"Khoa Cấp cứu","clock":"19:50","night":true},"vitals":{"hr":126,"sbp":84,"dbp":52,"rr":28,"temperature_c":36.4,"spo2":95},"history":[{"question":"Tai nạn xảy ra như thế nào, đau ở đâu?","response":"Ngã xe, tay lái đập mạnh vào hạ sườn trái. Đau bụng trên bên trái, lan lên vai trái."},{"question":"Anh có choáng, hoa mắt, khát nước, lạnh người không?","response":"Choáng váng, khát nước, lạnh, hoa mắt khi cố ngồi dậy."},{"question":"Có đội mũ bảo hiểm không? Có mất ý thức hoặc đau cổ không?","response":"Có đội mũ, tỉnh suốt, không đau cổ."},{"question":"Có bệnh nền hoặc đang dùng thuốc chống đông không?","response":"Khỏe mạnh, không dùng thuốc."},{"question":"Có nôn, tiểu máu hoặc ra máu trực tràng không?","response":"Buồn nôn, không nôn máu, nước tiểu vàng sậm, không đỏ."},{"question":"Có đau ngực hoặc khó thở không?","response":"Đau tức nhẹ khi hít sâu ở ngực dưới trái."},{"question":"Lần ăn uống cuối cùng?","response":"Ăn cơm chiều cách đây khoảng 2 giờ."},{"question":"Có dị ứng thuốc không? Đã tiêm phòng uốn ván chưa?","response":"Không dị ứng; tiêm uốn ván cách đây 3 năm."}],"examination":[{"group":"K","item":"Da và niêm mạc","finding":"Da niêm nhợt, vã mồ hôi lạnh."},{"group":"K","item":"Vùng hạ sườn trái","finding":"Vết trầy và bầm tím vùng hạ sườn trái."},{"group":"K","item":"Tri giác và kiểu thở","finding":"Tỉnh, lo lắng, thở nhanh nông."},{"group":"K","item":"Giọng nói","finding":"Nói ngắn, hơi thở nhanh nhưng rõ."},{"group":"K","item":"Mạch và đầu chi","finding":"Mạch nhanh, nhỏ, khó bắt; đầu chi lạnh, thời gian đổ đầy mao mạch trên 3 giây."},{"group":"K","item":"Sờ nắn bụng","finding":"Bụng chướng nhẹ, ấn đau và có phản ứng thành bụng vùng hạ sườn trái, lan dần ra khắp bụng; ấn đau lan lên vai trái (dấu Kehr)."},{"group":"K","item":"Khám ngực và xương sườn","finding":"Ấn đau các xương sườn thấp bên trái; phổi thông khí đều hai bên, không tràn khí dưới da."},{"group":"K","item":"Khám khung chậu và cột sống","finding":"Ép khung chậu không đau, cột sống không có điểm đau."},{"group":"K","item":"Thăm trực tràng và niệu đạo","finding":"Không có máu trên găng, không chảy máu ở lỗ niệu đạo."}],"investigations":[{"name":"Siêu âm FAST tại giường","duration_minutes":3,"result":"Dịch tự do quanh lách và túi cùng Douglas; không có dịch màng tim, màng phổi."},{"name":"Hemoglobin nhanh","duration_minutes":5,"result":"Hb 9,6 g/dL (còn sớm, chưa phản ánh hết lượng máu mất)."},{"name":"Nhóm máu và phản ứng chéo","duration_minutes":10,"result":"Nhóm O Rh dương, đã chuẩn bị hồng cầu lắng."},{"name":"Khí máu và lactate","duration_minutes":8,"result":"Lactate 4,2 mmol/L, toan chuyển hóa nhẹ."},{"name":"Xét nghiệm đông máu","duration_minutes":15,"result":"Chưa rối loạn."},{"name":"CT bụng có cản quang","duration_minutes":40,"result":"Chỉ dành cho bệnh nhân huyết động ổn định. Ca này huyết áp thấp, FAST dương tính nên không chuyển đi chụp."},{"name":"CT sọ não không cản quang","duration_minutes":30,"result":"Không có chỉ định: tỉnh, Glasgow 15, không mất ý thức, không dấu thần kinh khu trú."}],"choices":{"diagnosis":{"ydx":["Vỡ lách do chấn thương bụng kín, sốc mất máu","Tổn thương tụy do chấn thương","Chấn thương thận trái","Vỡ gan do chấn thương","Vỡ tạng rỗng (ruột, đại tràng)","Tràn máu màng phổi trái đơn thuần"]},"actions":["Chọc rửa ổ bụng chẩn đoán","Đánh giá ABCDE theo quy trình chấn thương, thở oxy lưu lượng cao, gắn monitor","Truyền nhanh lượng lớn dịch tinh thể để đưa huyết áp về bình thường","Báo động đỏ, hội chẩn ngoại khoa và gây mê hồi sức để mổ cấp cứu","Đặt sonde tiểu theo dõi nước tiểu khi không có dấu hiệu tổn thương niệu đạo","Cân nhắc tranexamic acid đường tĩnh mạch trong 3 giờ đầu theo phác đồ","Giữ ấm, nhịn ăn uống, giảm đau tĩnh mạch liều nhỏ có theo dõi","Kích hoạt truyền máu (hồng cầu lắng, theo quy trình truyền máu khối lượng lớn nếu cần)","Chườm nóng vùng hạ sườn trái để giảm đau","Đặt hai đường truyền tĩnh mạch lớn, lấy máu, hồi sức dịch tinh thể ấm lượng vừa phải","Đưa bệnh nhân đi chụp CT bụng khi huyết áp còn thấp, không có bác sĩ đi kèm","Xoa bóp mạnh vùng hạ sườn trái để giảm đau"]}}'::jsonb,
  'adae74ca54d4ff3b8a0728c5aee39ff2fce1b988b1e00fb9432522be8dccea70'
)
