insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'vo-lach-chan-thuong-bung-kin',
  '{"schema_version":"1.0.0","case_id":"vo-lach-chan-thuong-bung-kin","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-spleen-wses-2017","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/28828034/","title":"World Society of Emergency Surgery, Splenic Trauma: WSES Classification and Guidelines for Adult and Pediatric Patients, 2017.","organization":null,"year_version":null,"citation":"World Society of Emergency Surgery, Splenic Trauma: WSES Classification and Guidelines for Adult and Pediatric Patients, 2017.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-trauma-bleeding-eu-2023","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/36859355/","title":"European Guideline on Management of Major Bleeding and Coagulopathy Following Trauma, Sixth Edition, 2023.","organization":null,"year_version":null,"citation":"European Guideline on Management of Major Bleeding and Coagulopathy Following Trauma, Sixth Edition, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3],"examination_essential_indices":[0,1,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Vỡ lách do chấn thương bụng kín, sốc mất máu","credit":"full"},{"text":"Vỡ gan do chấn thương","credit":"none"},{"text":"Vỡ tạng rỗng (ruột, đại tràng)","credit":"none"},{"text":"Chấn thương thận trái","credit":"none"},{"text":"Tràn máu màng phổi trái đơn thuần","credit":"none"},{"text":"Tổn thương tụy do chấn thương","credit":"none"}]},"action_options":[{"text":"Đánh giá ABCDE theo quy trình chấn thương, thở oxy lưu lượng cao, gắn monitor","time_minutes":2,"grade":"critical","rationale":"Sốc mất máu với SpO2 95% và thở nhanh."},{"text":"Đặt hai đường truyền tĩnh mạch lớn, lấy máu, hồi sức dịch tinh thể ấm lượng vừa phải","time_minutes":3,"grade":"critical","rationale":"Cần duy trì tưới máu tối thiểu, không đẩy huyết áp lên cao khi chưa cầm máu."},{"text":"Báo động đỏ, hội chẩn ngoại khoa và gây mê hồi sức để mổ cấp cứu","time_minutes":2,"grade":"critical","rationale":"Huyết động không ổn định kèm FAST dương tính là chỉ định mổ cấp cứu, không chờ chụp CT."},{"text":"Kích hoạt truyền máu (hồng cầu lắng, theo quy trình truyền máu khối lượng lớn nếu cần)","time_minutes":3,"grade":"critical","rationale":"Mất máu phải thay bằng máu."},{"text":"Cân nhắc tranexamic acid đường tĩnh mạch trong 3 giờ đầu theo phác đồ","time_minutes":2,"grade":"recommended","rationale":"Giảm tử vong do chảy máu nếu dùng sớm."},{"text":"Giữ ấm, nhịn ăn uống, giảm đau tĩnh mạch liều nhỏ có theo dõi","time_minutes":2,"grade":"recommended","rationale":"Hạ thân nhiệt làm rối loạn đông máu; nhịn ăn để chuẩn bị gây mê."},{"text":"Đặt sonde tiểu theo dõi nước tiểu khi không có dấu hiệu tổn thương niệu đạo","time_minutes":2,"grade":"recommended","rationale":"Theo dõi tưới máu thận, lượng nước tiểu."},{"text":"Chọc rửa ổ bụng chẩn đoán","time_minutes":10,"grade":"waste","rationale":"Đã có FAST dương tính, không cần thêm, làm chậm mổ."},{"text":"Chườm nóng vùng hạ sườn trái để giảm đau","time_minutes":3,"grade":"waste","rationale":"Chưa kiểm soát chảy máu, trì hoãn hồi sức."},{"text":"Xoa bóp mạnh vùng hạ sườn trái để giảm đau","time_minutes":3,"grade":"harmful","rationale":"Có thể làm tăng chảy máu từ lách vỡ và trì hoãn mổ."},{"text":"Đưa bệnh nhân đi chụp CT bụng khi huyết áp còn thấp, không có bác sĩ đi kèm","time_minutes":5,"grade":"harmful","rationale":"Huyết động không ổn định, nguy cơ ngừng tim ngoài khoa cấp cứu và trì hoãn mổ."},{"text":"Truyền nhanh lượng lớn dịch tinh thể để đưa huyết áp về bình thường","time_minutes":3,"grade":"harmful","rationale":"Pha loãng máu, hạ thân nhiệt, tăng chảy máu."}],"teaching_explanation":"Chấn thương hạ sườn trái, đau lan vai trái (dấu Kehr), mạch nhanh, huyết áp thấp và FAST dương tính nghĩ ngay vỡ lách chảy máu. Bệnh nhân huyết động không ổn định không đi chụp CT mà chuyển mổ. Hồi sức bằng máu, hạn chế dịch tinh thể, giữ ấm, cầm máu sớm."}'::jsonb,
  'a8153a586e8c36dd50857aa7a6cd38d3555a43abbf7c92cfc52d7ab1c357e237'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'thai-ngoai-tu-cung-vo',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"thai-ngoai-tu-cung-vo","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Chậm kinh, đau bụng dưới, ngất","setting":"capcuu","level":"Khó","track":"ngoai","mode":"tay","specialty":null,"demographics":{"age":29,"sex":"nữ","patient_label":"Chị Lê Thị Mỹ Duyên"},"presentation":{"intro":"Chị Duyên được chồng đưa vào cấp cứu vì đau bụng dưới dữ dội đột ngột kèm choáng, ngất thoáng qua ở nhà vệ sinh. Chị chậm kinh khoảng 7 tuần và ra ít máu âm đạo ba ngày nay.","place":"Khoa Cấp cứu","clock":"14:20","night":false},"vitals":{"hr":128,"sbp":78,"dbp":48,"rr":28,"temperature_c":36.7,"spo2":96},"history":[{"question":"Kỳ kinh cuối cách đây bao lâu? Chị đã thử thai chưa?","response":"Chậm kinh khoảng 7 tuần. Que thử thai hai vạch cách đây một tuần, chưa đi khám thai."},{"question":"Đau bụng bắt đầu thế nào, ở vị trí nào?","response":"Đau dữ dội đột ngột ở bụng dưới bên phải, lan lên thượng vị và vai phải, rồi đau khắp bụng."},{"question":"Ra huyết âm đạo như thế nào?","response":"Ra ít máu đỏ sẫm từ ba ngày nay."},{"question":"Chị có choáng, ngất, hoa mắt không?","response":"Ngất thoáng qua ở nhà vệ sinh, hiện chóng mặt và khát nước."},{"question":"Có tiền sử viêm vùng chậu, thai ngoài tử cung, mổ vùng chậu hoặc đặt vòng tránh thai không?","response":"Hai năm trước từng bị viêm vùng chậu phải nằm viện. Không đặt vòng."},{"question":"Chị mang thai và sinh con mấy lần?","response":"Đây là lần mang thai đầu tiên, chưa sinh con."},{"question":"Có sốt, nôn hoặc tiêu chảy không?","response":"Không sốt, buồn nôn nhẹ, mót rặn muốn đi cầu."},{"question":"Chị có dị ứng thuốc không? Nhóm máu của chị là gì?","response":"Không dị ứng. Chị không nhớ nhóm máu."}],"examination":[{"group":"K","item":"Sắc mặt","finding":"Da niêm nhợt, vã mồ hôi lạnh, vẻ mặt đau và lo lắng."},{"group":"K","item":"Tư thế","finding":"Nằm co người, không dám cử động."},{"group":"K","item":"Giọng nói và hơi thở","finding":"Nói nhỏ, thở nhanh nông."},{"group":"K","item":"Mùi","finding":"Không có mùi hôi âm đạo."},{"group":"K","item":"Mạch và đầu chi","finding":"Mạch nhanh, nhỏ; đầu chi lạnh, mao mạch hồi phục chậm."},{"group":"K","item":"Khám bụng","finding":"Bụng chướng nhẹ, ấn đau khắp bụng nhiều nhất ở hố chậu phải, có phản ứng thành bụng."},{"group":"K","item":"Khám mỏ vịt và khám âm đạo","finding":"Ra ít máu đỏ sẫm; cổ tử cung đóng, di động cổ tử cung đau, túi cùng sau căng đầy đau, mơ hồ khối cạnh tử cung phải."},{"group":"K","item":"Khám tim phổi","finding":"Tim nhanh đều, phổi rì rào phế nang rõ."}],"investigations":[{"name":"Thử thai nhanh hCG nước tiểu","duration_minutes":3,"result":"Dương tính."},{"name":"Siêu âm bụng và đầu dò âm đạo tại giường","duration_minutes":6,"result":"Không thấy túi thai trong buồng tử cung; dịch tự do nhiều ở túi cùng Douglas và quanh gan; khối hỗn hợp âm cạnh phần phụ phải."},{"name":"Hemoglobin nhanh","duration_minutes":5,"result":"Hb 7,9 g/dL."},{"name":"Nhóm máu, Rh và phản ứng chéo","duration_minutes":10,"result":"Nhóm A Rh dương; đã chuẩn bị hồng cầu lắng."},{"name":"Định lượng beta-hCG máu","duration_minutes":30,"result":"Tăng, xác nhận thai nhưng không cần chờ khi đã có dịch ổ bụng, siêu âm gợi ý và huyết động không ổn định."},{"name":"Xét nghiệm đông máu cơ bản","duration_minutes":15,"result":"Trong giới hạn bình thường."},{"name":"Chụp X-quang tử cung vòi trứng","duration_minutes":30,"result":"Chống chỉ định ở người nghi có thai, không có giá trị trong cấp cứu."}],"choices":{"diagnosis":{"ydx":["Vỡ nang hoàng thể xuất huyết","Sẩy thai đang tiến triển","Viêm ruột thừa cấp","Xoắn u nang buồng trứng","Viêm phần phụ cấp","Thai ngoài tử cung vỡ, chảy máu ổ bụng, sốc mất máu"]},"actions":["Đánh giá ABC, thở oxy, gắn monitor, đặt hai đường truyền tĩnh mạch lớn","Đặt sonde tiểu theo dõi lượng nước tiểu","Hồi sức dịch tinh thể ấm, chuẩn bị và truyền máu sớm theo mức độ sốc","Xác định Rh; nếu Rh âm thì tiêm globulin miễn dịch kháng D theo phác đồ","Điều trị nội khoa bằng methotrexate","Hội chẩn sản khoa và gây mê hồi sức, chuyển mổ cấp cứu cầm máu","Giữ ấm, nhịn ăn uống hoàn toàn, giảm đau tĩnh mạch có theo dõi","Cho về theo dõi tại nhà, hẹn siêu âm lại sau 48 giờ","Giải thích tình trạng và thực hiện đồng thuận phẫu thuật theo năng lực quyết định và quy định cấp cứu của cơ sở","Chọc dò túi cùng sau Douglas để chẩn đoán","Truyền oxytocin hoặc dùng thuốc co hồi tử cung"]}}'::jsonb,
  'dbd47b5fd60fc1ac914a1f90e05d1b052b9b7fd8f729b6003116d1ac4d589c3a'
)
