values (
  'thai-ngoai-tu-cung-vo',
  '{"schema_version":"1.0.0","case_id":"thai-ngoai-tu-cung-vo","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-ectopic-acog-193","resource_type":"article","source":"https://pubmed.ncbi.nlm.nih.gov/29470343/","title":"American College of Obstetricians and Gynecologists, Practice Bulletin No. 193: Tubal Ectopic Pregnancy, 2018.","organization":null,"year_version":null,"citation":"American College of Obstetricians and Gynecologists, Practice Bulletin No. 193: Tubal Ectopic Pregnancy, 2018.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-thai-ngoai-tu-cung-vo-2","resource_type":"other","source":"European Society of Human Reproduction and Embryology, Guideline on the Management of Ectopic Pregnancy, 2022.","title":"European Society of Human Reproduction and Embryology, Guideline on the Management of Ectopic Pregnancy, 2022.","organization":null,"year_version":null,"citation":"European Society of Human Reproduction and Embryology, Guideline on the Management of Ectopic Pregnancy, 2022.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4],"examination_essential_indices":[0,4,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"neutral"},{"index":6,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thai ngoài tử cung vỡ, chảy máu ổ bụng, sốc mất máu","credit":"full"},{"text":"Vỡ nang hoàng thể xuất huyết","credit":"none"},{"text":"Viêm ruột thừa cấp","credit":"none"},{"text":"Xoắn u nang buồng trứng","credit":"none"},{"text":"Sẩy thai đang tiến triển","credit":"none"},{"text":"Viêm phần phụ cấp","credit":"none"}]},"action_options":[{"text":"Đánh giá ABC, thở oxy, gắn monitor, đặt hai đường truyền tĩnh mạch lớn","time_minutes":2,"grade":"critical","rationale":"Sốc mất máu với huyết áp 78/48 và mạch 128."},{"text":"Hồi sức dịch tinh thể ấm, chuẩn bị và truyền máu sớm theo mức độ sốc","time_minutes":3,"grade":"critical","rationale":"Cần thay thể tích tuần hoàn, ưu tiên máu khi mất máu nhiều."},{"text":"Hội chẩn sản khoa và gây mê hồi sức, chuyển mổ cấp cứu cầm máu","time_minutes":2,"grade":"critical","rationale":"Chảy máu đang tiếp diễn; phẫu thuật cầm máu là điều trị quyết định, không chờ huyết áp lên hẳn."},{"text":"Giữ ấm, nhịn ăn uống hoàn toàn, giảm đau tĩnh mạch có theo dõi","time_minutes":2,"grade":"recommended","rationale":"Chuẩn bị gây mê, tránh hạ thân nhiệt."},{"text":"Đặt sonde tiểu theo dõi lượng nước tiểu","time_minutes":2,"grade":"recommended","rationale":"Đánh giá tưới máu cơ quan."},{"text":"Xác định Rh; nếu Rh âm thì tiêm globulin miễn dịch kháng D theo phác đồ","time_minutes":2,"grade":"recommended","rationale":"Phòng đồng miễn dịch Rh ở lần mang thai sau."},{"text":"Giải thích tình trạng và thực hiện đồng thuận phẫu thuật theo năng lực quyết định và quy định cấp cứu của cơ sở","time_minutes":2,"grade":"recommended","rationale":"Ưu tiên trao đổi trực tiếp với người bệnh khi có khả năng quyết định; nếu tình trạng đe dọa tính mạng, không để thủ tục hành chính làm trì hoãn cầm máu cấp cứu."},{"text":"Chọc dò túi cùng sau Douglas để chẩn đoán","time_minutes":5,"grade":"waste","rationale":"Siêu âm đã thấy dịch tự do; làm thêm trì hoãn xử trí."},{"text":"Truyền oxytocin hoặc dùng thuốc co hồi tử cung","time_minutes":2,"grade":"waste","rationale":"Không có vai trò trong thai ngoài tử cung vỡ."},{"text":"Điều trị nội khoa bằng methotrexate","time_minutes":3,"grade":"harmful","rationale":"Chống chỉ định khi huyết động không ổn định và đã vỡ khối thai."},{"text":"Cho về theo dõi tại nhà, hẹn siêu âm lại sau 48 giờ","time_minutes":2,"grade":"harmful","rationale":"Nguy cơ tử vong do mất máu ở người đã có dấu hiệu sốc."}],"teaching_explanation":"Chậm kinh, đau bụng dưới, ra huyết âm đạo và sốc là thai ngoài tử cung vỡ cho đến khi chứng minh ngược lại. Thử thai dương tính, siêu âm không thấy túi thai trong tử cung kèm dịch tự do ổ bụng và huyết động không ổn định là chỉ định mổ cấp cứu, không chờ định lượng beta-hCG. Methotrexate chỉ dành cho người ổn định, chưa vỡ."}'::jsonb,
  'a4c1ce9b3a023bd2af150db755aca10e34ec1c8a39c9f9ba0062534f63a8684a'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-tyc-viem-mui-di-ung',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-tyc-viem-mui-di-ung","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Hắt hơi, sổ mũi mỗi sáng sớm","setting":"phongkham","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":27,"sex":"nữ","patient_label":"Chị Nguyễn Thị Mai Anh"},"presentation":{"intro":"Phòng khám Nội YHCT. Chị là nhân viên văn phòng, đến khám vì hắt hơi, sổ mũi, ngạt mũi tái diễn khoảng 2 năm, nặng nhất vào sáng sớm và khi thời tiết chuyển lạnh.","place":"Phòng khám Nội YHCT","clock":"08:20","night":false},"vitals":{"hr":76,"sbp":108,"dbp":68,"rr":16,"temperature_c":36.6,"spo2":99},"history":[{"question":"Triệu chứng chính là gì, xuất hiện lúc nào trong ngày?","response":"Hắt hơi từng tràng 5 đến 10 cái liền, chảy nước mũi trong như nước, ngạt mũi, nhất là sáng sớm vừa ngủ dậy và khi ra chỗ máy lạnh. Ngứa mũi, hay dụi mũi."},{"question":"Có ngứa mắt, chảy nước mắt, ngứa họng không?","response":"Ngứa mắt nhẹ, chảy nước mắt khi lên cơn. Ngứa vòm họng thỉnh thoảng."},{"question":"Có yếu tố khởi phát nào rõ không (bụi, phấn hoa, lông thú, mùi lạ, thay đổi thời tiết)?","response":"Nặng hơn khi quét dọn bụi, khi gió lạnh hoặc trời chuyển mùa. Nhà nuôi một con mèo."},{"question":"Nước mũi màu gì? Có đau vùng mặt, sốt hoặc chảy mũi mủ không?","response":"Nước mũi luôn trong, loãng. Không sốt, không đau nhức vùng má hay trán, không có mủ."},{"question":"Có chảy máu mũi, ngạt chỉ một bên, giảm khứu giác kéo dài không?","response":"Ngạt hai bên luân phiên, ngửi mùi hơi kém khi nghẹt nặng. Không chảy máu mũi."},{"question":"Có khò khè, khó thở, ho về đêm hay tiền sử hen, chàm không?","response":"Không khò khè, không khó thở. Hồi nhỏ có chàm nhẹ ở khuỷu tay. Mẹ bị viêm mũi dị ứng."},{"question":"Cơ thể hay sợ lạnh, ra mồ hôi, dễ cảm không?","response":"Người sợ gió, sợ lạnh, tự ra mồ hôi nhẹ, mỗi lần đổi thời tiết là hay cảm cúm. Hay mệt, ít nói."},{"question":"Ăn uống, đại tiểu tiện thế nào?","response":"Ăn bình thường, hơi đầy bụng nếu ăn đồ lạnh. Đại tiện nhão, tiểu trong."},{"question":"Đã dùng thuốc gì cho mũi? Có hay nhỏ thuốc co mạch không?","response":"Thỉnh thoảng uống thuốc kháng histamin thì đỡ vài giờ. Mua thuốc nhỏ mũi ngoài tiệm thuốc dùng khi nghẹt, khoảng 3 tuần nay mỗi ngày."},{"question":"Giấc ngủ, đặc điểm công việc?","response":"Ngủ được nhưng nghẹt mũi làm thức giấc. Làm việc phòng máy lạnh nhiều giờ."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Sắc mặt trắng nhợt, tinh thần hơi mệt, không sốt."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng, hơi ướt."},{"group":"V","item":"Mũi (nhìn ngoài)","finding":"Có nếp ngang sống mũi do hay dụi, quầng thâm nhẹ dưới mắt. Không biến dạng, không sưng đỏ vùng xoang."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói có âm mũi, nhỏ. Hơi thở không hôi."},{"group":"M","item":"Hắt hơi, ho","finding":"Hắt hơi từng tràng ngắn lúc khám. Không ho, không khò khè."},{"group":"T","item":"Mạch","finding":"Mạch phù, hoãn, nhược."},{"group":"T","item":"Sờ tay chân, da","finding":"Bàn tay hơi lạnh, da ẩm nhẹ."},{"group":"K","item":"Khám mũi (đèn soi)","finding":"Niêm mạc cuốn mũi dưới phù nề, nhợt màu hơi tím, dịch trong. Vách ngăn không lệch, không polyp, không mủ ở khe giữa."},{"group":"K","item":"Khám họng, tai, phổi","finding":"Họng không đỏ, có vài hạt lympho ở thành sau. Phổi thông khí rõ, không ran rít."}],"investigations":[{"name":"Công thức máu (bạch cầu ái toan)","duration_minutes":10,"result":"Bạch cầu bình thường, ái toan 6 phần trăm (hơi tăng)."},{"name":"Test lẩy da hoặc IgE đặc hiệu dị nguyên hô hấp","duration_minutes":30,"result":"Dương tính với mạt bụi nhà và lông mèo."},{"name":"Nội soi mũi","duration_minutes":10,"result":"Cuốn mũi dưới phù nề nhợt, dịch trong, không polyp, khe giữa sạch, vách ngăn thẳng."},{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Không bất thường. Không có chỉ định ở ca này."},{"name":"CT xoang không cản quang","duration_minutes":30,"result":"Dày niêm mạc nhẹ ở cuốn mũi, các xoang thông thoáng. Không có chỉ định ở ca này, chi phí và liều tia không cần thiết."}],"choices":{"diagnosis":{"ydx":["Viêm xoang mạn tính","Viêm mũi dị ứng quanh năm, mức độ nhẹ đến vừa","Polyp mũi","Viêm mũi xoang cấp do vi khuẩn","Lệch vách ngăn mũi"],"bd":["Tỵ nục","Tỵ cừu","Cảm mạo","Tỵ uyên","Khái thấu"],"bc":["Biểu – Thực – Hàn","Lý – Thực – Hàn","Biểu – Hư – Nhiệt","Lý – Thực – Nhiệt","Lý – Hư – Hàn"],"the":["Phế khí hư hàn","Phế kinh uất nhiệt","Phong nhiệt phạm phế","Thận dương hư","Tỳ khí hư nhược"],"phap":["Ôn bổ thận dương","Thanh tiết phế nhiệt, thông khiếu","Kiện tỳ ích khí, thăng dương","Sơ phong thanh nhiệt","Ôn phế, ích khí, cố biểu, thông khiếu"],"phuong":["Bổ trung ích khí thang","Ngọc bình phong tán gia Tân di, Thương nhĩ tử","Ôn phế chỉ lưu đan","Tân di thanh phế thang","Ngân kiều tán"],"huyet":["Ấn đường","Dương lăng tuyền","Hợp cốc","Thiên khu","Chi câu","Phế du","Túc tam lý","Thái xung","Nghênh hương"]},"actions":["Hướng dẫn giữ ấm cổ, gáy, tránh gió lạnh trực tiếp từ máy lạnh","Chụp CT xoang thường quy","Dùng thuốc nhỏ mũi co mạch hằng ngày kéo dài","Rửa mũi nước muối sinh lý hằng ngày","Cho thuốc thanh nhiệt hàn lương mạnh (Hoàng liên, Thạch cao)","Hướng dẫn hạn chế dị nguyên (bụi, thú nuôi, giặt chăn ga nước nóng)","Dùng thuốc xịt mũi corticoid tại chỗ hoặc kháng histamin theo phác đồ YHHĐ","Cứu hoặc châm Phế du, Túc tam lý, Nghênh hương","Hẹn tái khám, chuyển khám Tai Mũi Họng nếu ngạt một bên, chảy máu mũi, mủ, đau mặt hoặc khò khè"]}}'::jsonb,
  '2838b7eaa84d920c0eea7afbc2caebcc74e6bb8180e6a7e6e8e67309ad4245d2'
)
on conflict (case_id) do update set
