insert into can_lam_sang_private.answer_keys
  (case_id, answer_key, content_sha256)
values (
  'kham-tyc-viem-mui-di-ung',
  '{"schema_version":"1.0.0","case_id":"kham-tyc-viem-mui-di-ung","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-kham-tyc-viem-mui-di-ung-1","resource_type":"other","source":"American Academy of Otolaryngology–Head and Neck Surgery Foundation, Clinical Practice Guideline: Allergic Rhinitis, 2015.","title":"American Academy of Otolaryngology–Head and Neck Surgery Foundation, Clinical Practice Guideline: Allergic Rhinitis, 2015.","organization":null,"year_version":null,"citation":"American Academy of Otolaryngology–Head and Neck Surgery Foundation, Clinical Practice Guideline: Allergic Rhinitis, 2015.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,2,3,4,5,6,8],"examination_essential_indices":[1,5,7,8],"investigation_roles":[{"index":0,"role":"neutral"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"waste"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Viêm mũi dị ứng quanh năm, mức độ nhẹ đến vừa","credit":"full"},{"text":"Viêm mũi xoang cấp do vi khuẩn","credit":"none"},{"text":"Polyp mũi","credit":"none"},{"text":"Viêm xoang mạn tính","credit":"none"},{"text":"Lệch vách ngăn mũi","credit":"none"}],"bd":[{"text":"Tỵ cừu","credit":"full"},{"text":"Tỵ uyên","credit":"none"},{"text":"Cảm mạo","credit":"none"},{"text":"Khái thấu","credit":"none"},{"text":"Tỵ nục","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"}],"the":[{"text":"Phế khí hư hàn","credit":"full"},{"text":"Phế kinh uất nhiệt","credit":"none"},{"text":"Tỳ khí hư nhược","credit":"none"},{"text":"Thận dương hư","credit":"none"},{"text":"Phong nhiệt phạm phế","credit":"none"}],"phap":[{"text":"Ôn phế, ích khí, cố biểu, thông khiếu","credit":"full"},{"text":"Thanh tiết phế nhiệt, thông khiếu","credit":"none"},{"text":"Sơ phong thanh nhiệt","credit":"none"},{"text":"Kiện tỳ ích khí, thăng dương","credit":"none"},{"text":"Ôn bổ thận dương","credit":"none"}],"phuong":[{"text":"Ngọc bình phong tán gia Tân di, Thương nhĩ tử","credit":"full"},{"text":"Ôn phế chỉ lưu đan","credit":"full"},{"text":"Tân di thanh phế thang","credit":"none"},{"text":"Ngân kiều tán","credit":"none"},{"text":"Bổ trung ích khí thang","credit":"none"}],"huyet":[{"text":"Nghênh hương","credit":"full"},{"text":"Hợp cốc","credit":"full"},{"text":"Phế du","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Ấn đường","credit":"full"},{"text":"Thái xung","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"},{"text":"Chi câu","credit":"none"},{"text":"Thiên khu","credit":"none"}]},"action_options":[{"text":"Hướng dẫn hạn chế dị nguyên (bụi, thú nuôi, giặt chăn ga nước nóng)","time_minutes":3,"grade":"recommended","rationale":"Giảm tiếp xúc dị nguyên là nền tảng điều trị."},{"text":"Rửa mũi nước muối sinh lý hằng ngày","time_minutes":2,"grade":"recommended","rationale":"Làm sạch dị nguyên, giảm phù nề niêm mạc."},{"text":"Dùng thuốc xịt mũi corticoid tại chỗ hoặc kháng histamin theo phác đồ YHHĐ","time_minutes":2,"grade":"recommended","rationale":"Điều trị đầu tay theo hướng dẫn viêm mũi dị ứng."},{"text":"Cứu hoặc châm Phế du, Túc tam lý, Nghênh hương","time_minutes":15,"grade":"recommended","rationale":"Ôn phế, ích khí, cố biểu thông khiếu."},{"text":"Hướng dẫn giữ ấm cổ, gáy, tránh gió lạnh trực tiếp từ máy lạnh","time_minutes":2,"grade":"recommended","rationale":"Phòng tái phát ở thể phế khí hư hàn."},{"text":"Hẹn tái khám, chuyển khám Tai Mũi Họng nếu ngạt một bên, chảy máu mũi, mủ, đau mặt hoặc khò khè","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu cảnh báo."},{"text":"Chụp CT xoang thường quy","time_minutes":40,"grade":"waste","rationale":"Không có dấu hiệu viêm xoang, không cần thiết."},{"text":"Dùng thuốc nhỏ mũi co mạch hằng ngày kéo dài","time_minutes":1,"grade":"harmful","rationale":"Gây viêm mũi do thuốc, ngạt mũi dội ngược; cần ngừng thuốc nhỏ mũi co mạch đang dùng."},{"text":"Cho thuốc thanh nhiệt hàn lương mạnh (Hoàng liên, Thạch cao)","time_minutes":2,"grade":"harmful","rationale":"Thể phế khí hư hàn, thuốc hàn lương làm tổn thương thêm dương khí."}],"teaching_explanation":"Hắt hơi từng tràng, nước mũi trong, ngạt mũi sáng sớm, niêm mạc cuốn mũi nhợt phù cùng tiền sử dị ứng gia đình hướng tới viêm mũi dị ứng; thể Phế khí hư hàn với sợ gió, tự ra mồ hôi, lưỡi nhạt, mạch phù hoãn nhược. Dấu hiệu cảnh báo cần chuyển Tai Mũi Họng: ngạt một bên, chảy máu mũi, mủ, đau mặt, mất khứu giác kéo dài. Lưu ý nhóm thuốc co mạch nhỏ mũi gây ngạt dội ngược."}'::jsonb,
  '5a5696ee47af18868f36a2d85dd05972fe432759536352979970e095e8dd046a'
)
