  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-nhi-bieng-an-ty-hu',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-nhi-bieng-an-ty-hu","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Bé 4 tuổi chậm ăn, hay ốm vặt","setting":"phongkham","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":4,"sex":"nam","patient_label":"Bé Trần Gia Huy"},"presentation":{"intro":"Phòng khám Nhi YHCT. Mẹ đưa bé trai 4 tuổi đến khám vì chậm ăn, bỏ bữa, hay ốm vặt khoảng 5 tháng nay.","place":"Phòng khám Nhi YHCT","clock":"15:10","night":false},"vitals":{"hr":98,"sbp":90,"dbp":56,"rr":22,"temperature_c":36.7,"spo2":99},"history":[{"question":"Bé biếng ăn từ khi nào, ăn được bao nhiêu so với trước?","response":"Khoảng 5 tháng nay. Mỗi bữa chỉ ăn được nửa chén cơm, nhai lâu rồi ngậm, phải dỗ hoặc cho xem điện thoại mới ăn."},{"question":"Bé có sụt cân, chậm tăng cân hay chậm cao so với bạn cùng tuổi?","response":"Cân nặng từ lúc 3 tuổi đến nay tăng rất ít. Hiện cân 14 kg, cao 98 cm. Mẹ thấy bé nhỏ con hơn các bạn."},{"question":"Có nôn, đau bụng, tiêu chảy kéo dài hay phân có máu, phân mỡ không?","response":"Không nôn, không đau bụng dữ dội. Phân lúc nhão lúc thành khuôn, không máu, không thấy mỡ."},{"question":"Có sốt kéo dài, ho kéo dài, ra mồ hôi trộm hay nổi hạch không?","response":"Không sốt kéo dài. Hay cảm ho nhẹ 1 đến 2 tháng một lần, khỏi sau vài ngày. Không ra mồ hôi trộm, không nổi hạch."},{"question":"Bé có nuốt khó, ngậm thức ăn, đau miệng, sâu răng không?","response":"Không nuốt sặc. Có 2 răng sâu nhẹ, không loét miệng."},{"question":"Chế độ ăn: uống sữa, nước ngọt, ăn vặt trước bữa chính thế nào?","response":"Uống sữa hộp 3 lần mỗi ngày, hay ăn bánh kẹo, uống nước ngọt trước bữa cơm. Ít rau, ít thịt đỏ."},{"question":"Đại tiện, tiểu tiện, giấc ngủ, mồ hôi?","response":"Đại tiện nhão, 1 đến 2 lần mỗi ngày. Ngủ không sâu, hay ra mồ hôi đầu khi ngủ. Tiểu trong."},{"question":"Bé có tính tình ra sao, thích uống nước lạnh hay ấm? Hay mệt, ít chạy nhảy?","response":"Hiền, ít nghịch, hay mệt, không thích chạy nhiều. Thích uống nước ấm, không khát nhiều."},{"question":"Đã tẩy giun chưa, đã dùng thuốc kích thích ăn ngon chưa?","response":"Tẩy giun cách đây 1 năm. Mẹ tự mua siro bổ cho ăn ngon uống 1 tháng, không đỡ nhiều."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Bé tỉnh, nhanh nhẹn vừa phải, gầy, da hơi xanh, tóc thưa. Không phù, không vàng da."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng. Không bợt rêu dày."},{"group":"V","item":"Móng, niêm mạc mắt","finding":"Niêm mạc mắt nhợt nhẹ, móng tay hơi nhợt."},{"group":"M","item":"Giọng khóc, hơi thở","finding":"Giọng nói nhỏ, hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch hoãn, nhược, khó bắt rõ vì bé quấy."},{"group":"T","item":"Sờ bụng, tay chân","finding":"Tay chân hơi mát, bụng mềm, không chướng."},{"group":"K","item":"Cân đo","finding":"Cân nặng 14 kg, cao 98 cm, dưới trung vị rõ rệt trên biểu đồ tăng trưởng WHO, trong khoảng âm một đến âm hai độ lệch chuẩn. Không phù."},{"group":"K","item":"Khám bụng, gan lách, hạch","finding":"Bụng mềm, không khối, gan lách không to, không sờ thấy hạch bất thường."},{"group":"K","item":"Khám tim phổi","finding":"Tim đều không âm thổi. Phổi rõ, không ran."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 10,6 g/dL, MCV 72 fL, bạch cầu bình thường."},{"name":"Ferritin huyết thanh","duration_minutes":20,"result":"Giảm (thiếu sắt)."},{"name":"Soi phân tìm trứng và ký sinh trùng đường ruột","duration_minutes":15,"result":"Không thấy trứng giun, không thấy ký sinh trùng."},{"name":"Tổng phân tích nước tiểu","duration_minutes":10,"result":"Bình thường."},{"name":"CT ngực bụng có cản quang","duration_minutes":40,"result":"Không bất thường. Không có chỉ định ở ca này, trẻ nhỏ, liều tia không cần thiết."},{"name":"Nội soi dạ dày","duration_minutes":45,"result":"Không có chỉ định ở trẻ biếng ăn không dấu hiệu báo động."}],"choices":{"diagnosis":{"ydx":["Nhiễm giun sán","Biếng ăn chức năng (do chế độ ăn, hành vi) kèm thiếu máu thiếu sắt nhẹ","Bệnh celiac","Suy dinh dưỡng cấp nặng","Lao sơ nhiễm"],"bd":["Cam tích","Ế cách","Nhi hãn chứng","Tiết tả","Yếm thực"],"bc":["Lý – Thực – Nhiệt","Lý – Hư – Hàn","Lý – Hư – Nhiệt","Biểu – Hư – Nhiệt","Biểu – Thực – Hàn"],"the":["Vị âm bất túc","Can vượng khắc tỳ","Nhũ thực tích trệ","Tỳ vị khí hư","Tỳ thận dương hư"],"phap":["Ôn bổ thận dương","Tiêu thực đạo trệ, thông phủ","Dưỡng âm sinh tân, ích vị","Kiện tỳ ích khí, khai vị tiêu thực","Sơ can lý khí"],"phuong":["Dị công tán","Tiêu dao tán","Sâm linh bạch truật tán","Bảo hòa hoàn","Ích vị thang"],"huyet":["Nội quan","Trung quản","Đại chùy","Tỳ du","Thái xung","Phong long","Tứ phùng","Vị du","Túc tam lý"]},"actions":["Ép ăn, dọa nạt, cho ăn rong chạy theo bé","Cho thuốc tẩy hạ mạnh (Đại hoàng, Mang tiêu) vì nghĩ là tích","Xoa bóp bấm huyệt vùng bụng, bấm Túc tam lý, Tỳ du","Dặn chuyển khám Nhi nếu sụt cân, sốt kéo dài, nôn, tiêu chảy kéo dài, phân mỡ hoặc chậm lớn rõ","Bổ sung sắt theo phác đồ nhi khoa và theo dõi Hb","Tư vấn nếp ăn: giờ ăn cố định, không xem điện thoại, hạn chế sữa hộp, bánh kẹo, nước ngọt trước bữa","Chụp CT ngực bụng","Theo dõi cân nặng, chiều cao hằng tháng, hẹn tái khám","Cứu ôn hòa hoặc xoa bóp nhẹ vùng bụng, không dùng châm sâu"]}}'::jsonb,
  'c865b392069d58ee7fd0af2eac2725a2603c31168af9fd330ddd3f4d644ef5cd'
)
