 cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,5],"examination_essential_indices":[0,1,4,6,7],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Biếng ăn chức năng (do chế độ ăn, hành vi) kèm thiếu máu thiếu sắt nhẹ","credit":"full"},{"text":"Suy dinh dưỡng cấp nặng","credit":"none"},{"text":"Bệnh celiac","credit":"none"},{"text":"Nhiễm giun sán","credit":"none"},{"text":"Lao sơ nhiễm","credit":"none"}],"bd":[{"text":"Yếm thực","credit":"full"},{"text":"Cam tích","credit":"none"},{"text":"Tiết tả","credit":"none"},{"text":"Nhi hãn chứng","credit":"none"},{"text":"Ế cách","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Tỳ vị khí hư","credit":"full"},{"text":"Nhũ thực tích trệ","credit":"none"},{"text":"Vị âm bất túc","credit":"none"},{"text":"Can vượng khắc tỳ","credit":"none"},{"text":"Tỳ thận dương hư","credit":"none"}],"phap":[{"text":"Kiện tỳ ích khí, khai vị tiêu thực","credit":"full"},{"text":"Tiêu thực đạo trệ, thông phủ","credit":"none"},{"text":"Dưỡng âm sinh tân, ích vị","credit":"none"},{"text":"Sơ can lý khí","credit":"none"},{"text":"Ôn bổ thận dương","credit":"none"}],"phuong":[{"text":"Dị công tán","credit":"full"},{"text":"Sâm linh bạch truật tán","credit":"full"},{"text":"Bảo hòa hoàn","credit":"none"},{"text":"Ích vị thang","credit":"none"},{"text":"Tiêu dao tán","credit":"none"}],"huyet":[{"text":"Túc tam lý","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Vị du","credit":"full"},{"text":"Trung quản","credit":"full"},{"text":"Tứ phùng","credit":"full"},{"text":"Phong long","credit":"none"},{"text":"Thái xung","credit":"none"},{"text":"Đại chùy","credit":"none"},{"text":"Nội quan","credit":"none"}]},"action_options":[{"text":"Tư vấn nếp ăn: giờ ăn cố định, không xem điện thoại, hạn chế sữa hộp, bánh kẹo, nước ngọt trước bữa","time_minutes":4,"grade":"recommended","rationale":"Biếng ăn chức năng chủ yếu do chế độ ăn và thói quen."},{"text":"Bổ sung sắt theo phác đồ nhi khoa và theo dõi Hb","time_minutes":2,"grade":"recommended","rationale":"Có thiếu máu thiếu sắt nhẹ kèm ferritin thấp."},{"text":"Xoa bóp bấm huyệt vùng bụng, bấm Túc tam lý, Tỳ du","time_minutes":10,"grade":"recommended","rationale":"Kiện tỳ, khai vị, an toàn ở trẻ nhỏ."},{"text":"Cứu ôn hòa hoặc xoa bóp nhẹ vùng bụng, không dùng châm sâu","time_minutes":5,"grade":"recommended","rationale":"Trẻ 4 tuổi ưu tiên kỹ thuật nhẹ nhàng, ít xâm lấn."},{"text":"Theo dõi cân nặng, chiều cao hằng tháng, hẹn tái khám","time_minutes":2,"grade":"recommended","rationale":"Đánh giá đáp ứng điều trị."},{"text":"Dặn chuyển khám Nhi nếu sụt cân, sốt kéo dài, nôn, tiêu chảy kéo dài, phân mỡ hoặc chậm lớn rõ","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu cảnh báo bệnh lý thực thể."},{"text":"Chụp CT ngực bụng","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định ở trẻ nhỏ."},{"text":"Ép ăn, dọa nạt, cho ăn rong chạy theo bé","time_minutes":1,"grade":"harmful","rationale":"Củng cố hành vi ăn uống xấu, làm trẻ chán ăn thêm."},{"text":"Cho thuốc tẩy hạ mạnh (Đại hoàng, Mang tiêu) vì nghĩ là tích","time_minutes":2,"grade":"harmful","rationale":"Thể Tỳ vị khí hư, thuốc công phạt làm tỳ vị tổn thương thêm, nguy cơ mất nước."}],"teaching_explanation":"Trẻ biếng ăn kéo dài cần đánh giá tăng trưởng trước, loại trừ bệnh thực thể và thiếu vi chất (thiếu sắt thường gặp). Thể Tỳ vị khí hư: ăn ít, người gầy, sắc mặt nhợt, lưỡi nhạt, mạch hoãn nhược. Ở trẻ nhỏ ưu tiên điều chỉnh chế độ ăn, xoa bóp bấm huyệt, thuốc kiện tỳ; tránh công phạt mạnh. Dấu hiệu cảnh báo cần chuyển tuyến: sụt cân, sốt kéo dài, nôn, tiêu chảy mạn, thiếu máu nặng."}'::jsonb,
