insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-ho-man-viem-phe-quan-dam-thap',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-ho-man-viem-phe-quan-dam-thap","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Ho khạc đờm kéo dài ở người hút thuốc","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":58,"sex":"nam","patient_label":"Ông Trần Văn Hậu"},"presentation":{"intro":"Phòng khám Nội YHCT. Ông là tài xế, hút thuốc lá nhiều năm, đến khám vì ho khạc đờm kéo dài mỗi sáng, 4 tháng nay, nhiều đợt ho kéo dài mỗi năm.","place":"Phòng khám Nội YHCT","clock":"09:40","night":false},"vitals":{"hr":82,"sbp":130,"dbp":80,"rr":19,"temperature_c":36.8,"spo2":96},"history":[{"question":"Ho từ bao lâu, ho vào lúc nào, đờm màu gì?","response":"Ho khạc đờm hằng ngày, chủ yếu buổi sáng, đã gần 4 tháng; những năm trước cũng ho vài tháng mỗi năm. Đờm trắng, dính, dễ khạc, lượng nhiều."},{"question":"Có ho ra máu, đau ngực, khàn tiếng kéo dài không?","response":"Không ho ra máu, không đau ngực. Giọng bình thường."},{"question":"Có sụt cân, sốt về chiều, ra mồ hôi trộm không?","response":"Không sụt cân đáng kể, không sốt, không ra mồ hôi trộm."},{"question":"Có khó thở khi gắng sức, khò khè không?","response":"Leo 2 tầng lầu thấy hơi hụt hơi, nghỉ vài phút hết. Thỉnh thoảng khò khè lúc sáng. Không khó thở khi nghỉ."},{"question":"Hút thuốc bao nhiêu, bao lâu? Môi trường làm việc, tiếp xúc bụi?","response":"Hút 1 bao mỗi ngày gần 30 năm. Lái xe, hay hít khói bụi đường."},{"question":"Cảm giác ngực, ăn uống, đại tiện thế nào?","response":"Ngực đầy tức, nặng nề, ăn kém, bụng đầy. Người hay buồn ngủ, thân thể nặng. Đại tiện nhão."},{"question":"Có sợ lạnh hay khát nước, thích uống nóng hay lạnh?","response":"Sợ lạnh nhẹ, ít khát, thích uống nước ấm."},{"question":"Có ợ chua, trào ngược, ho nhiều về đêm không? Tiền sử hen, lao, bệnh tim?","response":"Thỉnh thoảng ợ chua. Chưa từng mắc lao, hen hay bệnh tim. Cũng chưa đo chức năng hô hấp bao giờ."},{"question":"Đã dùng thuốc gì? Đã tiêm vắc xin cúm, phế cầu chưa?","response":"Uống kháng sinh 2 đợt không rõ loại, đỡ ít. Chưa tiêm vắc xin nào."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Thể trạng béo nhẹ, sắc mặt xám, tinh thần tỉnh táo. Không xanh tím, không phù."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt bệu, rêu trắng dày nhớt."},{"group":"V","item":"Lồng ngực, ngón tay","finding":"Lồng ngực bình thường, không co kéo cơ hô hấp phụ. Ngón tay không dùi trống."},{"group":"M","item":"Tiếng ho, đờm","finding":"Ho khạc nặng tiếng, đờm trắng dính trong ống. Hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch hoạt, hoãn."},{"group":"T","item":"Sờ tay chân, bụng","finding":"Tay chân ấm, bụng đầy nhẹ, mềm."},{"group":"K","item":"Nghe phổi","finding":"Rì rào phế nang giảm nhẹ hai đáy, ran ngáy rải rác, vài ran rít cuối thì thở ra. Không ran nổ cố định."},{"group":"K","item":"Khám tim, bụng, hạch","finding":"Tim đều, không âm thổi. Gan lách không to. Không phù chi dưới, hạch cổ không to."},{"group":"K","item":"Đo SpO2, nhịp thở","finding":"SpO2 96 phần trăm khí phòng, nhịp thở 19 lần mỗi phút, nói được câu dài."}],"investigations":[{"name":"X-quang ngực thẳng","duration_minutes":10,"result":"Tăng đậm rốn phổi hai bên, không thấy khối, không đông đặc, không tràn dịch màng phổi."},{"name":"Đo hô hấp ký (chức năng thông khí) sau test giãn phế quản","duration_minutes":25,"result":"FEV1/FVC sau test 0,74, FEV1 90 phần trăm trị số dự đoán. Chưa thấy tắc nghẽn luồng khí cố định."},{"name":"Công thức máu","duration_minutes":10,"result":"Bạch cầu 8,2 G/L, trung tính bình thường. Hb 15 g/dL."},{"name":"Soi đờm tìm AFB hoặc Xpert MTB/RIF","duration_minutes":60,"result":"Âm tính."},{"name":"CT ngực có cản quang","duration_minutes":40,"result":"Không có chỉ định ở lần khám đầu khi X-quang không bất thường và không có dấu hiệu báo động."},{"name":"Nội soi phế quản","duration_minutes":60,"result":"Không có chỉ định ở ca này."}],"choices":{"diagnosis":{"ydx":["Viêm phế quản mạn, cần đo hô hấp ký để loại trừ COPD","Lao phổi","Hen phế quản","Giãn phế quản","Ung thư phế quản"],"bd":["Hung tý","Phế ung","Khái thấu","Háo suyễn","Phế nuy"],"bc":["Biểu – Hư – Hàn","Lý – Thực – Nhiệt","Lý – Thực – Hàn","Biểu – Thực – Hàn","Lý – Hư – Nhiệt"],"the":["Phong hàn phạm phế","Đàm thấp trở phế (Tỳ hư sinh đàm)","Phế âm hư","Đàm nhiệt úng phế","Can hỏa phạm phế"],"phap":["Tư âm nhuận phế","Sơ phong tán hàn, tuyên phế","Thanh nhiệt hóa đàm","Bình can giáng nghịch","Kiện tỳ táo thấp, hóa đàm chỉ khái"],"phuong":["Bách hợp cố kim thang","Thanh khí hóa đàm hoàn","Nhị trần thang","Tam tử dưỡng thân thang","Tang cúc ẩm"],"huyet":["Thái xung","Phế du","Dương lăng tuyền","Hành gian","Phong long","Liệt khuyết","Thiên đột","Túc tam lý","Giải khê"]},"actions":["Tiêm phòng cúm hằng năm và phế cầu theo khuyến cáo","Chỉ định CT ngực ngay lần đầu","Dặn tái khám khẩn khi ho ra máu, sụt cân, khó thở tăng, sốt kéo dài, khàn tiếng trên 3 tuần","Dùng kháng sinh phổ rộng kéo dài khi đờm trắng, không sốt","Cho thuốc ức chế ho trung ương mạnh (codein) khi đờm nhiều","Châm hoặc cứu Phế du, Phong long, Túc tam lý","Hẹn tái khám, đánh giá lại hô hấp ký, theo dõi SpO2","Tư vấn bỏ thuốc lá, hướng dẫn hỗ trợ cai thuốc","Hướng dẫn tập thở, tránh khói bụi, đeo khẩu trang"]}}'::jsonb,
  'c0fbd5149169e16b57afbd4ededc81707e78afcf013d66cf38f573c9787bee81'
)
