one"},{"text":"Giãn phế quản","credit":"none"}],"bd":[{"text":"Khái thấu","credit":"full"},{"text":"Háo suyễn","credit":"none"},{"text":"Phế ung","credit":"none"},{"text":"Hung tý","credit":"none"},{"text":"Phế nuy","credit":"none"}],"bc":[{"text":"Lý – Thực – Hàn","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Hàn","credit":"none"}],"the":[{"text":"Đàm thấp trở phế (Tỳ hư sinh đàm)","credit":"full"},{"text":"Phong hàn phạm phế","credit":"none"},{"text":"Đàm nhiệt úng phế","credit":"none"},{"text":"Phế âm hư","credit":"none"},{"text":"Can hỏa phạm phế","credit":"none"}],"phap":[{"text":"Kiện tỳ táo thấp, hóa đàm chỉ khái","credit":"full"},{"text":"Sơ phong tán hàn, tuyên phế","credit":"none"},{"text":"Thanh nhiệt hóa đàm","credit":"none"},{"text":"Tư âm nhuận phế","credit":"none"},{"text":"Bình can giáng nghịch","credit":"none"}],"phuong":[{"text":"Nhị trần thang","credit":"full"},{"text":"Tam tử dưỡng thân thang","credit":"partial"},{"text":"Tang cúc ẩm","credit":"none"},{"text":"Thanh khí hóa đàm hoàn","credit":"none"},{"text":"Bách hợp cố kim thang","credit":"none"}],"huyet":[{"text":"Phế du","credit":"full"},{"text":"Phong long","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Thiên đột","credit":"full"},{"text":"Liệt khuyết","credit":"full"},{"text":"Thái xung","credit":"none"},{"text":"Hành gian","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"},{"text":"Giải khê","credit":"none"}]},"action_options":[{"text":"Tư vấn bỏ thuốc lá, hướng dẫn hỗ trợ cai thuốc","time_minutes":5,"grade":"recommended","rationale":"Bỏ thuốc là biện pháp quan trọng nhất làm chậm tiến triển bệnh phổi mạn."},{"text":"Tiêm phòng cúm hằng năm và phế cầu theo khuyến cáo","time_minutes":2,"grade":"recommended","rationale":"Giảm đợt cấp, biến chứng nhiễm trùng hô hấp."},{"text":"Hướng dẫn tập thở, tránh khói bụi, đeo khẩu trang","time_minutes":3,"grade":"recommended","rationale":"Hỗ trợ thông khí, giảm kích thích đường thở."},{"text":"Châm hoặc cứu Phế du, Phong long, Túc tam lý","time_minutes":20,"grade":"recommended","rationale":"Kiện tỳ hóa đàm, hỗ trợ giảm ho đờm."},{"text":"Hẹn tái khám, đánh giá lại hô hấp ký, theo dõi SpO2","time_minutes":2,"grade":"recommended","rationale":"Theo dõi diễn tiến, phát hiện COPD."},{"text":"Dặn tái khám khẩn khi ho ra máu, sụt cân, khó thở tăng, sốt kéo dài, khàn tiếng trên 3 tuần","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu báo động ung thư phổi, lao."},{"text":"Chỉ định CT ngực ngay lần đầu","time_minutes":40,"grade":"waste","rationale":"Chưa có chỉ định khi X-quang bình thường và không có dấu hiệu báo động."},{"text":"Cho thuốc ức chế ho trung ương mạnh (codein) khi đờm nhiều","time_minutes":1,"grade":"harmful","rationale":"Ứ đờm, nguy cơ bội nhiễm, không phù hợp ho nhiều đờm."},{"text":"Dùng kháng sinh phổ rộng kéo dài khi đờm trắng, không sốt","time_minutes":3,"grade":"harmful","rationale":"Không có bằng chứng nhiễm khuẩn, tăng nguy cơ kháng thuốc."}],"teaching_explanation":"Ho khạc đờm hơn 3 tháng mỗi năm ở người hút thuốc là viêm phế quản mạn; hô hấp ký sau giãn phế quản quyết định có COPD hay không. Thể Đàm thấp trở phế: đờm trắng dính nhiều, ngực đầy, rêu trắng dày nhớt, mạch hoạt. Phải sàng lọc ho ra máu, sụt cân, sốt chiều, khàn tiếng để loại trừ lao và ung thư phổi, kèm khuyên bỏ thuốc lá."}'::jsonb,
