insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-dau-nua-dau-can-duong',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-dau-nua-dau-can-duong","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau nửa đầu từng cơn, buồn nôn sợ ánh sáng","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Chị Đỗ Thị Thu Hà"},"presentation":{"intro":"Phòng khám Nội YHCT. Chị là kế toán, đến khám vì đau nửa đầu bên phải từng cơn khoảng 2 năm, những tháng gần đây dày hơn khi áp lực công việc.","place":"Phòng khám Nội YHCT","clock":"14:00","night":false},"vitals":{"hr":78,"sbp":112,"dbp":70,"rr":16,"temperature_c":36.7,"spo2":99},"history":[{"question":"Đau ở đâu, tính chất đau thế nào, mỗi cơn kéo dài bao lâu?","response":"Đau nửa đầu bên phải, thường từ thái dương lan ra sau mắt, đau theo nhịp mạch đập. Mỗi cơn 6 đến 24 giờ, 2 đến 3 cơn mỗi tháng."},{"question":"Có buồn nôn, nôn, sợ ánh sáng, sợ tiếng ồn khi đau không?","response":"Buồn nôn nhiều, từng nôn một lần. Phải nằm phòng tối, yên tĩnh. Vận động làm đau tăng."},{"question":"Có thấy ánh sáng nhấp nháy, tê, yếu liệt hay rối loạn nói trước hoặc trong cơn không?","response":"Không có ánh sáng nhấp nháy, không tê, không yếu liệt, không nói khó."},{"question":"Cơn đau đầu này có khác trước, đau đột ngột dữ dội như sét đánh, sốt, cứng gáy không?","response":"Cơn đau vẫn giống những năm trước, không đột ngột dữ dội, không sốt, không cứng gáy."},{"question":"Có yếu tố khởi phát: căng thẳng, thiếu ngủ, bỏ bữa, rượu, mùi mạnh, kỳ kinh?","response":"Dễ lên cơn khi nóng giận, căng thẳng kéo dài, thiếu ngủ, hay trước kỳ kinh 1 đến 2 ngày."},{"question":"Cảm giác nóng giận, miệng đắng, ngủ, đại tiểu tiện?","response":"Dễ cáu gắt, miệng đắng, họng khô, mắt hay đỏ. Ngủ hay mộng mị, đại tiện táo, nước tiểu vàng."},{"question":"Đã dùng thuốc giảm đau gì, bao nhiêu ngày mỗi tháng? Có dùng thuốc tránh thai không?","response":"Uống paracetamol khoảng 4 ngày mỗi tháng thì đỡ ít. Không dùng thuốc tránh thai."},{"question":"Có tiền sử gia đình đau nửa đầu, bệnh lý mạch máu não, chấn thương đầu gần đây không?","response":"Mẹ bị đau nửa đầu. Không chấn thương đầu, không bệnh mạch máu não."},{"question":"Thị lực, chóng mặt, ù tai?","response":"Thị lực bình thường. Thỉnh thoảng hơi choáng khi đau. Không ù tai."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Sắc mặt hơi đỏ, mắt đỏ nhẹ, vẻ mặt căng thẳng, dễ kích động."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, rêu vàng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói to, nhanh, hơi thở hơi nóng, không hôi."},{"group":"T","item":"Mạch","finding":"Mạch huyền, sác."},{"group":"T","item":"Ấn huyệt vùng đầu cổ","finding":"Ấn đau vùng thái dương phải và cơ thang hai bên. Không cứng gáy."},{"group":"K","item":"Khám thần kinh","finding":"Tỉnh táo, đồng tử đều, vận động và cảm giác bình thường, phản xạ gân xương bình thường, dấu Babinski âm tính, không dấu màng não."},{"group":"K","item":"Soi đáy mắt","finding":"Gai thị bờ rõ, không phù gai thị."},{"group":"K","item":"Đo huyết áp hai tay, khám tim phổi","finding":"Huyết áp 112 trên 70 mmHg hai tay đều. Tim phổi bình thường."},{"group":"K","item":"Khám vùng mặt, xoang, hàm","finding":"Không đau vùng xoang, khớp thái dương hàm không đau."}],"investigations":[{"name":"Công thức máu, tốc độ máu lắng","duration_minutes":15,"result":"Bình thường."},{"name":"Đường huyết mao mạch","duration_minutes":5,"result":"5,2 mmol/L."},{"name":"Nhật ký đau đầu và thang điểm tàn tật MIDAS","duration_minutes":15,"result":"Điểm MIDAS cho thấy ảnh hưởng mức vừa."},{"name":"MRI sọ não","duration_minutes":45,"result":"Không bất thường. Không có chỉ định ở đau nửa đầu điển hình, khám thần kinh bình thường."},{"name":"CT sọ não","duration_minutes":20,"result":"Không bất thường. Không có chỉ định ở ca này."},{"name":"Điện não đồ","duration_minutes":30,"result":"Không đặc hiệu. Không có chỉ định để chẩn đoán đau nửa đầu."}],"choices":{"diagnosis":{"ydx":["Đau đầu căng thẳng","Viêm xoang cấp","Xuất huyết dưới nhện","Đau đầu cụm","Đau nửa đầu không có aura (migraine)"],"bd":["Tỵ uyên","Huyễn vựng","Thiên đầu thống","Đầu thống do ngoại cảm","Trúng phong"],"bc":["Lý – Hư – Nhiệt","Lý – Thực – Nhiệt","Biểu – Thực – Nhiệt","Lý – Hư – Hàn","Biểu – Thực – Hàn"],"the":["Huyết ứ trở lạc","Khí huyết lưỡng hư","Đàm trọc thượng nhiễu","Phong hàn thượng phạm","Can dương thượng cang"],"phap":["Bình can tiềm dương, tức phong chỉ thống","Bổ ích khí huyết","Hóa đàm giáng nghịch","Hoạt huyết hóa ứ thông lạc","Sơ phong tán hàn chỉ thống"],"phuong":["Thiên ma câu đằng ẩm","Bán hạ bạch truật thiên ma thang","Xuyên khung trà điều tán","Quy tỳ thang","Long đởm tả can thang"],"huyet":["Phong trì","Thận du","Hợp cốc","Thái xung","Tỳ du","Quan nguyên","Túc tam lý","Thái dương","Suất cốc"]},"actions":["Cho thuốc ôn nhiệt cay nóng (Phụ tử, Can khương, Quế chi liều cao)","Vệ sinh giấc ngủ, ăn đúng bữa, giảm căng thẳng, vận động đều","Châm Phong trì, Thái dương, Suất cốc, Thái xung, Hợp cốc","Chụp MRI sọ não thường quy","Hướng dẫn ghi nhật ký đau đầu, nhận diện và tránh yếu tố khởi phát","Kê thuốc opioid (codein, tramadol) hoặc thuốc giảm đau dùng hằng ngày","Hướng dẫn dùng thuốc cắt cơn sớm theo phác đồ YHHĐ (NSAID, triptan nếu không chống chỉ định)","Dặn tái khám khẩn khi đau đột ngột dữ dội, sốt, cứng gáy, yếu liệt, rối loạn nói, ngất, đau đầu kiểu mới thay đổi","Hẹn tái khám, giới hạn thuốc giảm đau không quá 10 ngày mỗi tháng"]}}'::jsonb,
  '1a6948e880ef2bad5a9494499bf1510e99af2193ab1018bba05cd9e866971836'
)
