ệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[1,3,5,6],"investigation_roles":[{"index":0,"role":"neutral"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"waste"},{"index":4,"role":"waste"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đau nửa đầu không có aura (migraine)","credit":"full"},{"text":"Đau đầu căng thẳng","credit":"none"},{"text":"Đau đầu cụm","credit":"none"},{"text":"Xuất huyết dưới nhện","credit":"none"},{"text":"Viêm xoang cấp","credit":"none"}],"bd":[{"text":"Thiên đầu thống","credit":"full"},{"text":"Huyễn vựng","credit":"none"},{"text":"Trúng phong","credit":"none"},{"text":"Đầu thống do ngoại cảm","credit":"none"},{"text":"Tỵ uyên","credit":"none"}],"bc":[{"text":"Lý – Thực – Nhiệt","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Can dương thượng cang","credit":"full"},{"text":"Phong hàn thượng phạm","credit":"none"},{"text":"Đàm trọc thượng nhiễu","credit":"none"},{"text":"Huyết ứ trở lạc","credit":"none"},{"text":"Khí huyết lưỡng hư","credit":"none"}],"phap":[{"text":"Bình can tiềm dương, tức phong chỉ thống","credit":"full"},{"text":"Sơ phong tán hàn chỉ thống","credit":"none"},{"text":"Hóa đàm giáng nghịch","credit":"none"},{"text":"Hoạt huyết hóa ứ thông lạc","credit":"none"},{"text":"Bổ ích khí huyết","credit":"none"}],"phuong":[{"text":"Thiên ma câu đằng ẩm","credit":"full"},{"text":"Long đởm tả can thang","credit":"partial"},{"text":"Xuyên khung trà điều tán","credit":"none"},{"text":"Bán hạ bạch truật thiên ma thang","credit":"none"},{"text":"Quy tỳ thang","credit":"none"}],"huyet":[{"text":"Phong trì","credit":"full"},{"text":"Thái dương","credit":"full"},{"text":"Suất cốc","credit":"full"},{"text":"Thái xung","credit":"full"},{"text":"Hợp cốc","credit":"full"},{"text":"Quan nguyên","credit":"none"},{"text":"Tỳ du","credit":"none"},{"text":"Thận du","credit":"none"},{"text":"Túc tam lý","credit":"none"}]},"action_options":[{"text":"Hướng dẫn ghi nhật ký đau đầu, nhận diện và tránh yếu tố khởi phát","time_minutes":5,"grade":"recommended","rationale":"Nền tảng điều trị dự phòng đau nửa đầu."},{"text":"Vệ sinh giấc ngủ, ăn đúng bữa, giảm căng thẳng, vận động đều","time_minutes":3,"grade":"recommended","rationale":"Giảm tần suất cơn."},{"text":"Châm Phong trì, Thái dương, Suất cốc, Thái xung, Hợp cốc","time_minutes":20,"grade":"recommended","rationale":"Bình can tiềm dương, giảm đau."},{"text":"Hướng dẫn dùng thuốc cắt cơn sớm theo phác đồ YHHĐ (NSAID, triptan nếu không chống chỉ định)","time_minutes":3,"grade":"recommended","rationale":"Thuốc cắt cơn hiệu quả khi dùng sớm."},{"text":"Dặn tái khám khẩn khi đau đột ngột dữ dội, sốt, cứng gáy, yếu liệt, rối loạn nói, ngất, đau đầu kiểu mới thay đổi","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu cảnh báo đau đầu thứ phát."},{"text":"Hẹn tái khám, giới hạn thuốc giảm đau không quá 10 ngày mỗi tháng","time_minutes":2,"grade":"recommended","rationale":"Tránh đau đầu do lạm dụng thuốc."},{"text":"Chụp MRI sọ não thường quy","time_minutes":45,"grade":"waste","rationale":"Đau nửa đầu điển hình, khám thần kinh bình thường, không có dấu hiệu báo động."},{"text":"Kê thuốc opioid (codein, tramadol) hoặc thuốc giảm đau dùng hằng ngày","time_minutes":1,"grade":"harmful","rationale":"Không khuyến cáo, nguy cơ phụ thuộc và đau đầu do lạm dụng thuốc."},{"text":"Cho thuốc ôn nhiệt cay nóng (Phụ tử, Can khương, Quế chi liều cao)","time_minutes":2,"grade":"harmful","rationale":"Thể Can dương thượng cang, thuốc ôn nhiệt làm dương cang nặng thêm."}],"teaching_explanation":"Đau nửa đầu một bên, đập theo mạch, 6 đến 24 giờ, buồn nôn, sợ ánh sáng và tiếng ồn, khám thần kinh bình thường là đủ chẩn đoán lâm sàng; không cần chẩn đoán hình ảnh thường quy. Thể Can dương thượng cang: cáu gắt, miệng đắng, lưỡi đỏ rêu vàng mỏng, mạch huyền sác. Phải loại trừ dấu hiệu cảnh báo: đau sét đánh, sốt cứng gáy, triệu chứng thần kinh khu trú, khởi phát sau 50 tuổi, phù gai thị."}'::jsonb,
