insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-thong-ta-ruot-kich-thich',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-thong-ta-ruot-kich-thich","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau quặn bụng rồi đi ngoài phân nát","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":38,"sex":"nam","patient_label":"Anh Võ Minh Quân"},"presentation":{"intro":"Phòng khám Nội YHCT. Anh là nhân viên ngân hàng, đến khám vì đau quặn bụng, đi ngoài phân nát nhiều lần mỗi ngày kéo dài khoảng 8 tháng, tăng khi căng thẳng.","place":"Phòng khám Nội YHCT","clock":"10:30","night":false},"vitals":{"hr":80,"sbp":118,"dbp":76,"rr":17,"temperature_c":36.7,"spo2":99},"history":[{"question":"Đau bụng ở đâu, tính chất thế nào, liên quan đến đi ngoài ra sao?","response":"Đau quặn quanh bụng dưới và hố chậu trái, đau muốn đi ngoài, đi xong thì đỡ. Đau từng cơn, vài lần mỗi tuần, khoảng 8 tháng nay."},{"question":"Đại tiện mấy lần mỗi ngày, phân thế nào, có máu hay nhầy, đi ngoài ban đêm không?","response":"Đi 3 đến 4 lần mỗi ngày, phân nát hoặc sệt, có ít nhầy trắng. Không thấy máu, không đen. Không phải dậy đêm đi ngoài."},{"question":"Có sụt cân, sốt, thiếu máu, mệt nhiều không?","response":"Cân nặng ổn định 65 kg. Không sốt. Chỉ hơi mệt, không chóng mặt."},{"question":"Có tiền sử gia đình ung thư đại trực tràng, bệnh viêm ruột, bệnh celiac không?","response":"Không ai trong gia đình mắc các bệnh này."},{"question":"Triệu chứng nặng lên khi nào?","response":"Nặng hơn khi căng thẳng, áp lực công việc, sau bữa ăn nhiều dầu mỡ, sữa. Cuối tuần nghỉ ngơi thì đỡ."},{"question":"Có đầy hơi, ợ hơi, sôi bụng, cảm giác đi chưa hết phân không?","response":"Hay đầy hơi, sôi bụng, sau đi vẫn thấy chưa hết phân."},{"question":"Tính tình, ngủ, ăn uống?","response":"Dễ cáu gắt, hay lo lắng, ngủ nông. Ăn kém, sợ ăn nhiều vì sợ đau bụng. Người mệt, ít sức."},{"question":"Có sợ lạnh, tay chân lạnh, đi ngoài lúc rạng sáng không?","response":"Không đi ngoài lúc rạng sáng, không đặc biệt sợ lạnh."},{"question":"Đã dùng thuốc gì, có dùng kháng sinh gần đây không? Có đi du lịch hay ăn thực phẩm lạ?","response":"Uống men vi sinh và thuốc cầm tiêu chảy đôi lần, đỡ tạm thời. Không dùng kháng sinh, không đi xa gần đây."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Thể trạng trung bình, sắc mặt hơi vàng nhạt, vẻ lo lắng. Không xanh xao rõ."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt hơi bệu, bên có vết hằn răng, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở, bụng","finding":"Hay thở dài. Hơi thở không hôi. Nghe bụng nhu động ruột tăng nhẹ."},{"group":"T","item":"Mạch","finding":"Mạch huyền, hoãn (huyền ở bộ quan trái, hoãn nhược ở bộ quan phải)."},{"group":"T","item":"Sờ tay chân","finding":"Tay chân không lạnh, hơi ẩm."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn đau nhẹ hố chậu trái, không phản ứng thành bụng, không khối, gan lách không to."},{"group":"K","item":"Thăm trực tràng","finding":"Trương lực cơ thắt bình thường, không khối, găng không dính máu."},{"group":"K","item":"Khám da, niêm mạc, tuyến giáp","finding":"Niêm mạc mắt hồng, không loét miệng, tuyến giáp không to."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 14,2 g/dL, bạch cầu bình thường."},{"name":"CRP","duration_minutes":15,"result":"Bình thường."},{"name":"Calprotectin phân","duration_minutes":60,"result":"Dưới 50 microgam mỗi gam (bình thường)."},{"name":"Soi phân, cấy phân, tìm ký sinh trùng","duration_minutes":30,"result":"Không bạch cầu, hồng cầu, không có ký sinh trùng."},{"name":"Kháng thể kháng transglutaminase mô IgA","duration_minutes":60,"result":"Âm tính."},{"name":"CT bụng có cản quang","duration_minutes":40,"result":"Không bất thường. Không có chỉ định ở ca này."}],"choices":{"diagnosis":{"ydx":["Ung thư đại tràng","Hội chứng ruột kích thích thể tiêu chảy (theo tiêu chuẩn Rome IV)","Bệnh Crohn","Viêm loét đại trực tràng chảy máu","Bệnh celiac"],"bd":["Phúc thống","Táo bón","Tiện huyết","Lỵ","Thống tả"],"bc":["Biểu – Thực – Hàn","Lý – Hư – Nhiệt","Lý – Hư thực thác tạp – Hàn","Biểu – Hư – Hàn","Lý – Thực – Nhiệt"],"the":["Thấp nhiệt đại trường","Thực tích đình trệ","Tỳ thận dương hư","Hàn thấp khốn tỳ","Can uất tỳ hư (Can khí phạm Tỳ)"],"phap":["Sơ can kiện tỳ, ức can phù tỳ, chỉ tả","Tiêu thực đạo trệ","Ôn trung tán hàn, hóa thấp","Thanh nhiệt lợi thấp, chỉ tả","Ôn bổ tỳ thận, cố sáp chỉ tả"],"phuong":["Thống tả yếu phương","Tứ thần hoàn","Sâm linh bạch truật tán","Bảo hòa hoàn","Cát căn cầm liên thang"],"huyet":["Đại chùy","Túc tam lý","Âm lăng tuyền","Tỳ du","Thiên khu","Thái xung","Dũng tuyền","Thái dương","Phế du"]},"actions":["Dùng thuốc YHHĐ triệu chứng khi cần (chống co thắt, men vi sinh) theo chỉ định","Dùng kháng sinh phổ rộng kéo dài","Chụp CT bụng có cản quang","Giải thích bản chất hội chứng ruột kích thích, trấn an, khuyên giảm căng thẳng","Cho thuốc tả hạ công trục (Đại hoàng, Mang tiêu) vì nghĩ là thực tích","Hẹn tái khám 4 đến 6 tuần, nội soi đại tràng nếu xuất hiện dấu hiệu báo động (đi ngoài ra máu, sụt cân, thiếu máu, tiêu chảy đêm, khối bụng)","Hướng dẫn tập thể dục đều, ngủ đủ, kỹ thuật thư giãn","Châm cứu Thiên khu, Túc tam lý, Tỳ du, Thái xung","Ghi nhật ký ăn uống, hạn chế thực phẩm gây khởi phát (dầu mỡ, sữa, rượu, caffeine, thực phẩm nhiều FODMAP)"]}}'::jsonb,
  'bec78bca4d30c28085cf34080538fcbd2c865a2fa0d222523c42422a73eedf09'
)
