  '{"schema_version":"1.0.0","case_id":"kham-thong-ta-ruot-kich-thich","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-kham-thong-ta-ruot-kich-thich-1","resource_type":"other","source":"American College of Gastroenterology, ACG Clinical Guideline: Management of Irritable Bowel Syndrome, 2021.","title":"American College of Gastroenterology, ACG Clinical Guideline: Management of Irritable Bowel Syndrome, 2021.","organization":null,"year_version":null,"citation":"American College of Gastroenterology, ACG Clinical Guideline: Management of Irritable Bowel Syndrome, 2021.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-kham-thong-ta-ruot-kich-thich-2","resource_type":"other","source":"Rome Foundation, Rome IV Functional Gastrointestinal Disorders, 2016.","title":"Rome Foundation, Rome IV Functional Gastrointestinal Disorders, 2016.","organization":null,"year_version":null,"citation":"Rome Foundation, Rome IV Functional Gastrointestinal Disorders, 2016.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,6],"examination_essential_indices":[1,3,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"neutral"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hội chứng ruột kích thích thể tiêu chảy (theo tiêu chuẩn Rome IV)","credit":"full"},{"text":"Viêm loét đại trực tràng chảy máu","credit":"none"},{"text":"Bệnh Crohn","credit":"none"},{"text":"Ung thư đại tràng","credit":"none"},{"text":"Bệnh celiac","credit":"none"}],"bd":[{"text":"Thống tả","credit":"full"},{"text":"Lỵ","credit":"none"},{"text":"Phúc thống","credit":"none"},{"text":"Táo bón","credit":"none"},{"text":"Tiện huyết","credit":"none"}],"bc":[{"text":"Lý – Hư thực thác tạp – Hàn","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Hàn","credit":"none"}],"the":[{"text":"Can uất tỳ hư (Can khí phạm Tỳ)","credit":"full"},{"text":"Thấp nhiệt đại trường","credit":"none"},{"text":"Tỳ thận dương hư","credit":"none"},{"text":"Thực tích đình trệ","credit":"none"},{"text":"Hàn thấp khốn tỳ","credit":"none"}],"phap":[{"text":"Sơ can kiện tỳ, ức can phù tỳ, chỉ tả","credit":"full"},{"text":"Thanh nhiệt lợi thấp, chỉ tả","credit":"none"},{"text":"Ôn bổ tỳ thận, cố sáp chỉ tả","credit":"none"},{"text":"Tiêu thực đạo trệ","credit":"none"},{"text":"Ôn trung tán hàn, hóa thấp","credit":"none"}],"phuong":[{"text":"Thống tả yếu phương","credit":"full"},{"text":"Sâm linh bạch truật tán","credit":"partial"},{"text":"Cát căn cầm liên thang","credit":"none"},{"text":"Tứ thần hoàn","credit":"none"},{"text":"Bảo hòa hoàn","credit":"none"}],"huyet":[{"text":"Thiên khu","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Tỳ du","credit":"full"},{"text":"Thái xung","credit":"full"},{"text":"Âm lăng tuyền","credit":"full"},{"text":"Đại chùy","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Phế du","credit":"none"},{"text":"Dũng tuyền","credit":"none"}]},"action_options":[{"text":"Giải thích bản chất hội chứng ruột kích thích, trấn an, khuyên giảm căng thẳng","time_minutes":5,"grade":"recommended","rationale":"Ca chức năng, liệu pháp giáo dục, tâm lý có lợi."},{"text":"Ghi nhật ký ăn uống, hạn chế thực phẩm gây khởi phát (dầu mỡ, sữa, rượu, caffeine, thực phẩm nhiều FODMAP)","time_minutes":4,"grade":"recommended","rationale":"Thay đổi chế độ ăn giúp giảm triệu chứng."},{"text":"Châm cứu Thiên khu, Túc tam lý, Tỳ du, Thái xung","time_minutes":20,"grade":"recommended","rationale":"Sơ can kiện tỳ, điều hòa vận hóa."},{"text":"Hướng dẫn tập thể dục đều, ngủ đủ, kỹ thuật thư giãn","time_minutes":3,"grade":"recommended","rationale":"Điều hòa trục ruột não."},{"text":"Hẹn tái khám 4 đến 6 tuần, nội soi đại tràng nếu xuất hiện dấu hiệu báo động (đi ngoài ra máu, sụt cân, thiếu máu, tiêu chảy đêm, khối bụng)","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu cảnh báo bệnh thực thể."},{"text":"Dùng thuốc YHHĐ triệu chứng khi cần (chống co thắt, men vi sinh) theo chỉ định","time_minutes":2,"grade":"recommended","rationale":"Hỗ trợ giảm đau bụng, tiêu chảy."},{"text":"Chụp CT bụng có cản quang","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định ở ca không dấu hiệu báo động."},{"text":"Cho thuốc tả hạ công trục (Đại hoàng, Mang tiêu) vì nghĩ là thực tích","time_minutes":2,"grade":"harmful","rationale":"Thể Can uất tỳ hư, thuốc tả hạ làm tỳ vị tổn thương, tiêu chảy nặng thêm."},{"text":"Dùng kháng sinh phổ rộng kéo dài","time_minutes":3,"grade":"harmful","rationale":"Không có bằng chứng nhiễm khuẩn, gây rối loạn hệ vi sinh đường ruột."}],"teaching_explanation":"Đau bụng liên quan đại tiện, thay đổi tính chất phân, không sụt cân, không máu, xét nghiệm viêm và calprotectin bình thường gợi ý hội chứng ruột kích thích thể tiêu chảy. Thể Can uất Tỳ hư: đau muốn đi ngoài, đi xong thì đỡ, tăng khi căng thẳng, lưỡi nhạt bệu hằn răng, mạch huyền hoãn. Bắt buộc sàng lọc dấu hiệu báo động (máu trong phân, sụt cân, thiếu máu, tiêu chảy đêm, khởi phát sau 50 tuổi, tiền sử gia đình) để chỉ định nội soi và loại trừ bệnh viêm ruột, ung thư."}'::jsonb,
  '7de2847bb3bca43280a7e5dde74e58c1b90822b924a8bfad560f90ca04255736'
)
