insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-thong-kinh-khi-tre-huyet-u',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-thong-kinh-khi-tre-huyet-u","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau bụng dưới dữ dội mỗi kỳ kinh","setting":"phongkham","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":21,"sex":"nữ","patient_label":"Cô Lê Thu Trang"},"presentation":{"intro":"Phòng khám Sản phụ khoa YHCT. Cô là sinh viên, đến khám vì đau bụng dưới dữ dội mỗi kỳ kinh khoảng 6 năm, mấy tháng nay phải nghỉ học vào ngày đầu.","place":"Phòng khám Sản phụ khoa YHCT","clock":"16:20","night":false},"vitals":{"hr":82,"sbp":106,"dbp":66,"rr":16,"temperature_c":36.6,"spo2":99},"history":[{"question":"Đau bụng kinh bắt đầu từ khi nào, đau ở đâu, kéo dài bao lâu?","response":"Có kinh năm 13 tuổi, đau từ khoảng 15 tuổi. Đau quặn bụng dưới, lan ra thắt lưng, bắt đầu trước kỳ kinh 1 đến 2 ngày và nặng nhất ngày đầu, kéo dài 2 đến 3 ngày."},{"question":"Tính chất kinh nguyệt: chu kỳ, lượng, màu máu, máu cục?","response":"Chu kỳ 28 đến 30 ngày đều. Lượng vừa, màu tối, nhiều máu cục. Ra máu cục xong thì đỡ đau."},{"question":"Đau có đỡ khi chườm ấm hay xoa bóp không? Đau trướng hay đau quặn?","response":"Đau trướng, quặn, ấn vào thì đau hơn. Chườm ấm đỡ một phần. Vú căng tức trước kỳ kinh."},{"question":"Có ra khí hư bất thường, sốt, đau bụng ngoài kỳ kinh, đau khi quan hệ không?","response":"Không ra khí hư hôi, không sốt. Không đau bụng ngoài kỳ kinh. Chưa có quan hệ tình dục."},{"question":"Có đau tăng dần theo thời gian, đau không đáp ứng thuốc giảm đau, rong huyết ngoài kỳ không?","response":"Đau ổn định, uống ibuprofen đầu kỳ thì giảm khá. Không ra huyết ngoài kỳ kinh."},{"question":"Có buồn nôn, tiêu chảy, mệt lả, ngất khi đau không?","response":"Buồn nôn nhẹ, không ngất, không tiêu chảy."},{"question":"Tính tình, giấc ngủ, ăn uống?","response":"Hay cáu gắt trước kỳ kinh, tức ngực, ngủ ngon. Ăn bình thường."},{"question":"Có sợ lạnh, tay chân lạnh, đau tăng khi trời lạnh?","response":"Không đặc biệt sợ lạnh."},{"question":"Tiền sử gia đình (mẹ, chị) có đau bụng kinh nặng, lạc nội mạc tử cung, u xơ?","response":"Mẹ cũng từng đau bụng kinh khi trẻ, đã đỡ sau sinh. Không ai mắc lạc nội mạc tử cung."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Sắc mặt hơi sạm, vẻ mặt khó chịu nhưng tỉnh táo, không xanh xao."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi tím tối, có điểm ứ huyết hai bên rìa, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Hay thở dài, giọng nói bình thường."},{"group":"T","item":"Mạch","finding":"Mạch huyền, sáp."},{"group":"T","item":"Ấn bụng dưới, sờ tay chân","finding":"Bụng dưới ấn đau, cự án. Tay chân không lạnh."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, ấn đau nhẹ trên xương mu, không phản ứng thành bụng, không khối vùng chậu, không dấu hiệu viêm phúc mạc."},{"group":"K","item":"Khám tổng quát","finding":"Không sốt, niêm mạc hồng, tuyến giáp không to. Chỉ số khối cơ thể 20,5."},{"group":"K","item":"Khám vú và hạch","finding":"Vú không khối, hơi căng tức. Không hạch."}],"investigations":[{"name":"Thử thai nhanh hoặc beta hCG","duration_minutes":10,"result":"Âm tính."},{"name":"Siêu âm bụng, tử cung và phần phụ","duration_minutes":20,"result":"Tử cung kích thước bình thường, không u xơ, không u nang buồng trứng, không dịch túi cùng."},{"name":"Công thức máu","duration_minutes":10,"result":"Hb 12,8 g/dL, bình thường."},{"name":"Xét nghiệm dịch âm đạo, tìm tác nhân viêm nhiễm","duration_minutes":20,"result":"Không có tác nhân bệnh. Không có chỉ định thường quy ở ca chưa quan hệ tình dục."},{"name":"CA-125","duration_minutes":60,"result":"Bình thường. Không có chỉ định ở ca không nghi ung thư buồng trứng hay lạc nội mạc tử cung nặng."},{"name":"MRI vùng chậu","duration_minutes":50,"result":"Không bất thường. Không có chỉ định ở lần khám đầu khi siêu âm bình thường."}],"choices":{"diagnosis":{"ydx":["Lạc nội mạc tử cung","U nang buồng trứng","Đau bụng kinh nguyên phát","Bệnh viêm vùng chậu mạn","Thai ngoài tử cung"],"bd":["Phúc thống","Thống kinh","Kinh nguyệt không đều","Băng lậu","Bế kinh"],"bc":["Lý – Hư – Nhiệt","Lý – Thực (huyết ứ, khí trệ)","Biểu – Thực – Hàn","Biểu – Hư – Nhiệt","Lý – Hư – Hàn"],"the":["Thấp nhiệt uẩn kết","Can thận hư tổn","Khí huyết hư nhược","Hàn thấp ngưng trệ","Khí trệ huyết ứ"],"phap":["Bổ ích khí huyết","Hành khí hoạt huyết, hóa ứ chỉ thống","Thanh nhiệt lợi thấp","Ôn kinh tán hàn, trừ thấp","Tư dưỡng can thận"],"phuong":["Ôn kinh thang","Thiếu phúc trục ứ thang","Thanh nhiệt điều huyết thang","Cách hạ trục ứ thang","Bát trân thang"],"huyet":["Phong trì","Huyết hải","Thái dương","Khí hải","Thái xung","Phế du","Tam âm giao","Quan nguyên","Dũng tuyền"]},"actions":["Hướng dẫn vận động nhẹ, ngủ đủ, hạn chế đồ lạnh, giảm căng thẳng trước kỳ kinh","Dùng thuốc hoạt huyết phá ứ mạnh (Tam lăng, Nga truật, Đào nhân liều cao) khi chưa loại trừ có thai","Theo dõi lịch kinh, hẹn tái khám 2 đến 3 chu kỳ, chuyển khám Sản phụ khoa nếu đau tăng dần, không đáp ứng NSAID, ra huyết bất thường hoặc khối vùng chậu","Thử thai trước khi dùng thuốc hoạt huyết hoặc châm vùng bụng","Châm hoặc cứu Tam âm giao, Quan nguyên, Khí hải, Huyết hải, Thái xung","Ấn mạnh, xoa bóp sâu vùng bụng dưới khi chưa loại trừ thai ngoài tử cung, khối vùng chậu","Giải thích đây là đau bụng kinh nguyên phát, trấn an, hướng dẫn chườm ấm bụng dưới","Dùng thuốc giảm đau kháng viêm không steroid (NSAID) từ trước hoặc đầu kỳ kinh theo chỉ định nếu không chống chỉ định","Chỉ định MRI vùng chậu ngay lần đầu"]}}'::jsonb,
  '31b900c3e58598b2659c7a33d002700ca7e870d68674bed993c62e1d6479ca8f'
)
