t":"Bệnh viêm vùng chậu mạn","credit":"none"},{"text":"Thai ngoài tử cung","credit":"none"},{"text":"U nang buồng trứng","credit":"none"}],"bd":[{"text":"Thống kinh","credit":"full"},{"text":"Kinh nguyệt không đều","credit":"none"},{"text":"Băng lậu","credit":"none"},{"text":"Phúc thống","credit":"none"},{"text":"Bế kinh","credit":"none"}],"bc":[{"text":"Lý – Thực (huyết ứ, khí trệ)","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Khí trệ huyết ứ","credit":"full"},{"text":"Hàn thấp ngưng trệ","credit":"none"},{"text":"Khí huyết hư nhược","credit":"none"},{"text":"Can thận hư tổn","credit":"none"},{"text":"Thấp nhiệt uẩn kết","credit":"none"}],"phap":[{"text":"Hành khí hoạt huyết, hóa ứ chỉ thống","credit":"full"},{"text":"Ôn kinh tán hàn, trừ thấp","credit":"none"},{"text":"Bổ ích khí huyết","credit":"none"},{"text":"Tư dưỡng can thận","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"}],"phuong":[{"text":"Cách hạ trục ứ thang","credit":"full"},{"text":"Thiếu phúc trục ứ thang","credit":"partial"},{"text":"Ôn kinh thang","credit":"none"},{"text":"Bát trân thang","credit":"none"},{"text":"Thanh nhiệt điều huyết thang","credit":"none"}],"huyet":[{"text":"Tam âm giao","credit":"full"},{"text":"Thái xung","credit":"full"},{"text":"Huyết hải","credit":"full"},{"text":"Khí hải","credit":"full"},{"text":"Quan nguyên","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Phế du","credit":"none"},{"text":"Dũng tuyền","credit":"none"}]},"action_options":[{"text":"Giải thích đây là đau bụng kinh nguyên phát, trấn an, hướng dẫn chườm ấm bụng dưới","time_minutes":3,"grade":"recommended","rationale":"Cải thiện triệu chứng, giảm lo lắng."},{"text":"Dùng thuốc giảm đau kháng viêm không steroid (NSAID) từ trước hoặc đầu kỳ kinh theo chỉ định nếu không chống chỉ định","time_minutes":2,"grade":"recommended","rationale":"Điều trị đầu tay theo YHHĐ."},{"text":"Châm hoặc cứu Tam âm giao, Quan nguyên, Khí hải, Huyết hải, Thái xung","time_minutes":20,"grade":"recommended","rationale":"Hành khí hoạt huyết, thông kinh chỉ thống."},{"text":"Hướng dẫn vận động nhẹ, ngủ đủ, hạn chế đồ lạnh, giảm căng thẳng trước kỳ kinh","time_minutes":3,"grade":"recommended","rationale":"Giảm tần suất, mức độ đau."},{"text":"Theo dõi lịch kinh, hẹn tái khám 2 đến 3 chu kỳ, chuyển khám Sản phụ khoa nếu đau tăng dần, không đáp ứng NSAID, ra huyết bất thường hoặc khối vùng chậu","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc đau bụng kinh thứ phát (lạc nội mạc tử cung)."},{"text":"Thử thai trước khi dùng thuốc hoạt huyết hoặc châm vùng bụng","time_minutes":1,"grade":"recommended","rationale":"Loại trừ có thai."},{"text":"Chỉ định MRI vùng chậu ngay lần đầu","time_minutes":50,"grade":"waste","rationale":"Siêu âm bình thường, không có dấu hiệu thứ phát."},{"text":"Dùng thuốc hoạt huyết phá ứ mạnh (Tam lăng, Nga truật, Đào nhân liều cao) khi chưa loại trừ có thai","time_minutes":2,"grade":"harmful","rationale":"Có nguy cơ sảy thai nếu có thai."},{"text":"Ấn mạnh, xoa bóp sâu vùng bụng dưới khi chưa loại trừ thai ngoài tử cung, khối vùng chậu","time_minutes":1,"grade":"harmful","rationale":"Có nguy cơ vỡ khối, nguy hiểm tính mạng."}],"teaching_explanation":"Đau bụng kinh xuất hiện sau vài năm có kinh, ngay trước hoặc đầu kỳ kinh, đáp ứng NSAID, khám và siêu âm bình thường gợi ý thể nguyên phát. Thể Khí trệ huyết ứ: đau trướng, cự án, máu tối có cục, ra cục thì đỡ, lưỡi tím tối, mạch huyền sáp. Ở phụ nữ trong tuổi sinh sản luôn loại trừ có thai trước khi dùng thuốc hoạt huyết; cảnh báo cần chuyển tuyến: đau tăng dần, đau ngoài kỳ kinh, không đáp ứng thuốc, sốt, khí hư mủ, khối vùng chậu."}'::jsonb,
  '4728c47f24baee338d66fc58b50e71e1a28a86ade9b5566ab24302f604f6c234'
)
