values (
  'kham-tieu-khat-dai-thao-duong-tip-2',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-tieu-khat-dai-thao-duong-tip-2","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Khát nước, tiểu nhiều, mệt, mới phát hiện đường huyết cao","setting":"phongkham","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":49,"sex":"nam","patient_label":"Ông Phạm Quốc Bảo"},"presentation":{"intro":"Phòng khám Nội YHCT. Ông là chủ cửa hàng, thừa cân, đến khám vì khát nước, tiểu nhiều, mệt mỏi khoảng 2 tháng. Kết quả khám sức khỏe gần đây báo đường huyết đói cao.","place":"Phòng khám Nội YHCT","clock":"08:50","night":false},"vitals":{"hr":84,"sbp":132,"dbp":84,"rr":17,"temperature_c":36.7,"spo2":98},"history":[{"question":"Có khát nước nhiều, uống nhiều, tiểu nhiều không? Từ khi nào?","response":"Khát, hay uống nước, tiểu 6 đến 7 lần mỗi ngày, đêm dậy tiểu 2 lần, khoảng 2 tháng nay."},{"question":"Có sụt cân nhanh, buồn nôn, nôn, đau bụng, thở nhanh sâu không?","response":"Sụt khoảng 2 kg trong 2 tháng. Không nôn, không đau bụng, không thở nhanh."},{"question":"Có mờ mắt, tê bì chân, loét hoặc vết thương lâu lành, nhiễm trùng da không?","response":"Hơi mờ mắt thoáng qua. Tê nhẹ đầu ngón chân. Không có vết loét ở bàn chân."},{"question":"Có đau ngực, khó thở khi gắng sức, đau cách hồi chân không?","response":"Không đau ngực, không đau cách hồi."},{"question":"Tiền sử gia đình đái tháo đường, tăng huyết áp, rối loạn mỡ máu? Cân nặng, vòng bụng?","response":"Cha bị đái tháo đường. Cân nặng 78 kg, cao 1,68 m. Bụng to, ít vận động."},{"question":"Cảm giác mệt, ăn uống, miệng khô, ra mồ hôi?","response":"Mệt, ít sức, miệng họng khô, ăn bình thường, hay ra mồ hôi tay. Lòng bàn tay chân hơi nóng."},{"question":"Giấc ngủ, đại tiện?","response":"Ngủ không sâu, đại tiện hơi táo."},{"question":"Có dùng thuốc, thực phẩm chức năng hoặc thuốc nam nào không?","response":"Chưa dùng thuốc điều trị đái tháo đường. Có uống thuốc nam bạn tặng, không rõ thành phần."},{"question":"Có hút thuốc, uống rượu không?","response":"Hút khoảng nửa bao mỗi ngày, uống bia cuối tuần."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Thể trạng thừa cân (chỉ số khối cơ thể 27,6), tinh thần hơi mệt, da khô."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ nhạt, ít tân dịch, rêu trắng mỏng khô."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói nhỏ, hơi thở không có mùi trái cây (aceton)."},{"group":"T","item":"Mạch","finding":"Mạch tế, nhược, hơi sác."},{"group":"T","item":"Sờ lòng bàn tay chân","finding":"Lòng bàn tay, bàn chân ấm nóng nhẹ, da khô."},{"group":"K","item":"Khám bàn chân (monofilament, mạch mu chân)","finding":"Giảm cảm giác nhẹ đầu ngón chân khi thử monofilament, mạch mu chân bắt được, không loét, da không nứt nẻ."},{"group":"K","item":"Khám tim, phổi, bụng","finding":"Tim đều, phổi rõ, bụng mềm, gan không to."},{"group":"K","item":"Đo huyết áp, chu vi vòng bụng","finding":"Huyết áp 132 trên 84 mmHg, vòng bụng 96 cm."}],"investigations":[{"name":"Đường huyết tĩnh mạch lúc đói","duration_minutes":10,"result":"8,4 mmol/L (lần 2 cũng trên 7)."},{"name":"HbA1c","duration_minutes":30,"result":"7,6 phần trăm."},{"name":"Tổng phân tích nước tiểu, ceton niệu","duration_minutes":15,"result":"Glucose niệu dương tính, ceton âm tính."},{"name":"Creatinin máu và eGFR, tỷ lệ albumin trên creatinin niệu","duration_minutes":30,"result":"Creatinin bình thường, eGFR 98, albumin niệu bình thường."},{"name":"Lipid máu, men gan","duration_minutes":30,"result":"Triglycerid 2,8 mmol/L, LDL-C 3,5 mmol/L, men gan bình thường."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp xoang, không bất thường."},{"name":"Kháng thể kháng GAD","duration_minutes":90,"result":"Không cần thiết ở bệnh nhân người lớn thừa cân, không ceton, nghi típ 2 điển hình."},{"name":"MRI tụy","duration_minutes":60,"result":"Không có chỉ định ở ca này."}],"choices":{"diagnosis":{"ydx":["Đái tháo nhạt","Tiền đái tháo đường","Cường giáp","Đái tháo đường típ 1","Đái tháo đường típ 2 mới phát hiện, chưa biến chứng cấp"],"bd":["Hư lao","Lâm chứng","Huyễn vựng","Tiêu khát","Tỳ đản"],"bc":["Lý – Hư – Nhiệt","Lý – Thực – Nhiệt","Lý – Hư – Hàn","Biểu – Hư – Nhiệt","Biểu – Thực – Hàn"],"the":["Phế vị táo nhiệt","Thấp nhiệt trung tiêu","Âm dương lưỡng hư","Khí âm lưỡng hư","Can thận âm hư"],"phap":["Thanh nhiệt lợi thấp","Ích khí dưỡng âm, sinh tân chỉ khát","Ôn bổ thận dương","Bổ thận tư âm","Thanh nhiệt tả hỏa, sinh tân"],"phuong":["Ngọc tuyền hoàn","Sinh mạch tán gia vị","Long đởm tả can thang","Bạch hổ gia nhân sâm thang","Kim quỹ thận khí hoàn"],"huyet":["Phong trì","Thận du","Đại chùy","Tam âm giao","Túc tam lý","Thái dương","Thái khê","Dương lăng tuyền","Tỳ du"]},"actions":["Dặn đến cấp cứu khi buồn nôn nôn, đau bụng, thở nhanh sâu, lơ mơ, khát dữ dội hoặc đường huyết rất cao","Hướng dẫn tự theo dõi đường huyết, nhận biết hạ đường huyết và triệu chứng tăng đường huyết nặng","Sàng lọc biến chứng: khám mắt, đáy mắt, nước tiểu albumin, bàn chân, tim mạch","Khởi đầu điều trị đái tháo đường theo phác đồ YHHĐ (thường metformin nếu eGFR cho phép và không chống chỉ định)","Hướng dẫn bỏ thuốc lá, hạn chế bia rượu, hẹn kiểm tra HbA1c sau 3 tháng","Cho thuốc ôn nhiệt bổ dương (Phụ tử, Nhục quế liều cao)","Tư vấn thay đổi lối sống: chế độ ăn kiểm soát carbohydrate, tăng vận động ít nhất 150 phút mỗi tuần, giảm cân","Chụp MRI tụy","Ngừng thuốc YHHĐ, chỉ dùng thuốc nam hoặc thực phẩm chức năng để hạ đường huyết","Châm cứu hoặc thuốc YHCT hỗ trợ (Tỳ du, Thận du, Túc tam lý, Tam âm giao, Thái khê)"]}}'::jsonb,
  'ea28d666ad442f9229f84577414f05796c1e8f3ecafcacdc0f44a8400a5ec88e'
)
