tháo nhạt","credit":"none"},{"text":"Cường giáp","credit":"none"}],"bd":[{"text":"Tiêu khát","credit":"full"},{"text":"Lâm chứng","credit":"none"},{"text":"Hư lao","credit":"none"},{"text":"Huyễn vựng","credit":"none"},{"text":"Tỳ đản","credit":"none"}],"bc":[{"text":"Lý – Hư – Nhiệt","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Khí âm lưỡng hư","credit":"full"},{"text":"Phế vị táo nhiệt","credit":"none"},{"text":"Can thận âm hư","credit":"none"},{"text":"Âm dương lưỡng hư","credit":"none"},{"text":"Thấp nhiệt trung tiêu","credit":"none"}],"phap":[{"text":"Ích khí dưỡng âm, sinh tân chỉ khát","credit":"full"},{"text":"Thanh nhiệt tả hỏa, sinh tân","credit":"none"},{"text":"Bổ thận tư âm","credit":"none"},{"text":"Ôn bổ thận dương","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"}],"phuong":[{"text":"Sinh mạch tán gia vị","credit":"full"},{"text":"Ngọc tuyền hoàn","credit":"full"},{"text":"Bạch hổ gia nhân sâm thang","credit":"none"},{"text":"Kim quỹ thận khí hoàn","credit":"none"},{"text":"Long đởm tả can thang","credit":"none"}],"huyet":[{"text":"Tỳ du","credit":"full"},{"text":"Thận du","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Thái khê","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Đại chùy","credit":"none"},{"text":"Dương lăng tuyền","credit":"none"}]},"action_options":[{"text":"Tư vấn thay đổi lối sống: chế độ ăn kiểm soát carbohydrate, tăng vận động ít nhất 150 phút mỗi tuần, giảm cân","time_minutes":8,"grade":"recommended","rationale":"Nền tảng kiểm soát đái tháo đường típ 2."},{"text":"Khởi đầu điều trị đái tháo đường theo phác đồ YHHĐ (thường metformin nếu eGFR cho phép và không chống chỉ định)","time_minutes":3,"grade":"recommended","rationale":"Cần điều trị nền YHHĐ để kiểm soát đường huyết."},{"text":"Hướng dẫn tự theo dõi đường huyết, nhận biết hạ đường huyết và triệu chứng tăng đường huyết nặng","time_minutes":5,"grade":"recommended","rationale":"Tự quản lý bệnh."},{"text":"Sàng lọc biến chứng: khám mắt, đáy mắt, nước tiểu albumin, bàn chân, tim mạch","time_minutes":5,"grade":"recommended","rationale":"Chẩn đoán đã có tê chân nhẹ, cần đánh giá sớm."},{"text":"Châm cứu hoặc thuốc YHCT hỗ trợ (Tỳ du, Thận du, Túc tam lý, Tam âm giao, Thái khê)","time_minutes":20,"grade":"recommended","rationale":"Ích khí dưỡng âm hỗ trợ kiểm soát đường huyết, triệu chứng."},{"text":"Hướng dẫn bỏ thuốc lá, hạn chế bia rượu, hẹn kiểm tra HbA1c sau 3 tháng","time_minutes":3,"grade":"recommended","rationale":"Giảm nguy cơ tim mạch, theo dõi đáp ứng."},{"text":"Dặn đến cấp cứu khi buồn nôn nôn, đau bụng, thở nhanh sâu, lơ mơ, khát dữ dội hoặc đường huyết rất cao","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu nhiễm toan ceton, tăng áp lực thẩm thấu."},{"text":"Chụp MRI tụy","time_minutes":60,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Ngừng thuốc YHHĐ, chỉ dùng thuốc nam hoặc thực phẩm chức năng để hạ đường huyết","time_minutes":1,"grade":"harmful","rationale":"Nguy cơ tăng đường huyết, biến chứng, thuốc nam không rõ thành phần có thể chứa corticoid hoặc sulfonylurea."},{"text":"Cho thuốc ôn nhiệt bổ dương (Phụ tử, Nhục quế liều cao)","time_minutes":2,"grade":"harmful","rationale":"Thể khí âm lưỡng hư, thuốc ôn nhiệt làm hao thương âm dịch thêm."}],"teaching_explanation":"Triệu chứng khát, tiểu nhiều, sụt cân với đường huyết đói 7 mmol/L trở lên hai lần hoặc HbA1c từ 6,5 phần trăm cho phép chẩn đoán đái tháo đường; cần xác nhận típ, ceton niệu và sàng lọc biến chứng ngay từ đầu. Thể Khí âm lưỡng hư: mệt, miệng khô, lưỡi đỏ nhạt ít tân, mạch tế nhược. YHCT hỗ trợ, không thay thế thuốc YHHĐ; cảnh báo khẩn cấp: buồn nôn, đau bụng, thở sâu, lơ mơ, vết loét bàn chân."}'::jsonb,
