insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'kham-tao-bon-man-cao-tuoi-da-benh',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"kham-tao-bon-man-cao-tuoi-da-benh","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Cụ bà 72 tuổi đại tiện khó, nhiều ngày một lần","setting":"phongkham","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":72,"sex":"nữ","patient_label":"Bà Lê Thị Bích"},"presentation":{"intro":"Phòng khám Nội YHCT. Bà đã nghỉ hưu, bị tăng huyết áp, đái tháo đường típ 2 và thoái hóa khớp gối, đến khám vì đại tiện khó, 4 đến 5 ngày mới đi một lần, phân khô cứng khoảng 7 tháng.","place":"Phòng khám Nội YHCT","clock":"09:05","night":false},"vitals":{"hr":74,"sbp":138,"dbp":78,"rr":17,"temperature_c":36.5,"spo2":97},"history":[{"question":"Đại tiện thế nào: số lần, hình dạng phân, có rặn nhiều, có cảm giác đi chưa hết không?","response":"Khoảng 4 đến 5 ngày mới đi một lần, phân khô, viên cứng như phân dê, rặn nhiều, đi xong vẫn thấy chưa hết. Khoảng 7 tháng nay."},{"question":"Phân có máu, có đổi màu đen, có sụt cân, mệt nhiều, thiếu máu không?","response":"Không thấy máu, phân không đen. Cân nặng ổn định 52 kg, không sụt cân đáng kể."},{"question":"Có đau bụng, đầy chướng, buồn nôn, nôn không? Có bí trung tiện không?","response":"Đầy bụng nhẹ khi nhiều ngày chưa đi, không nôn, vẫn trung tiện được."},{"question":"Có tiền sử gia đình ung thư đại trực tràng, đã nội soi đại tràng lần nào chưa?","response":"Chưa ai trong gia đình mắc. Đã nội soi đại tràng cách đây 4 năm, được bảo là bình thường."},{"question":"Có đang dùng thuốc: canxi, thuốc huyết áp, thuốc đái tháo đường, giảm đau, sắt?","response":"Uống amlodipine, metformin, canxi carbonat mỗi ngày. Thỉnh thoảng uống thuốc giảm đau khớp."},{"question":"Uống nước, ăn rau, vận động thế nào?","response":"Uống ít nước vì sợ tiểu đêm, ăn ít rau, ngồi nhiều vì đau khớp gối."},{"question":"Cảm giác chóng mặt, hồi hộp, da khô, môi khô, ngủ?","response":"Hay chóng mặt nhẹ khi đứng dậy, hồi hộp, da khô, môi khô, ngủ kém."},{"question":"Có hay dùng thuốc nhuận tràng, thuốc xổ không?","response":"Mua thuốc nhuận tràng kích thích ngoài hiệu thuốc, dùng 2 đến 3 lần mỗi tuần, đỡ rồi lại táo."},{"question":"Có sợ lạnh, chậm chạp, tăng cân, da khô (nghi suy giáp)?","response":"Không sợ lạnh đặc biệt, cân nặng ổn định."}],"examination":[{"group":"V","item":"Thần sắc, thể trạng","finding":"Cụ gầy, sắc mặt nhợt nhạt, da khô, tinh thần mệt mỏi."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, ít tân dịch, rêu trắng mỏng khô."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Giọng nói nhỏ, ngắt quãng. Hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch tế, sáp."},{"group":"T","item":"Sờ tay chân, da","finding":"Tay chân hơi mát, da khô, bụng không đau."},{"group":"K","item":"Khám bụng","finding":"Bụng mềm, hố chậu trái sờ thấy cục phân, không đau, không khối, không dấu tắc ruột, nhu động ruột giảm nhẹ."},{"group":"K","item":"Thăm trực tràng","finding":"Phân cứng trong bóng trực tràng, không khối u, không trĩ chảy máu, trương lực cơ thắt bình thường."},{"group":"K","item":"Khám tuyến giáp, thần kinh, đo huyết áp tư thế","finding":"Tuyến giáp không to, phản xạ bình thường. Huyết áp nằm 138 trên 78, đứng 128 trên 74 mmHg."}],"investigations":[{"name":"Công thức máu","duration_minutes":10,"result":"Hb 12,4 g/dL, MCV bình thường."},{"name":"Xét nghiệm máu ẩn trong phân (FIT)","duration_minutes":20,"result":"Âm tính."},{"name":"TSH","duration_minutes":30,"result":"Bình thường."},{"name":"Đường huyết, HbA1c, canxi máu, creatinin, điện giải đồ","duration_minutes":40,"result":"Đường huyết đói 7,2 mmol/L, HbA1c 7,0 phần trăm, canxi máu hơi cao bình thường, creatinin bình thường, K bình thường."},{"name":"X-quang bụng không chuẩn bị","duration_minutes":15,"result":"Phân ứ đọng đại tràng sigma, không có mức nước hơi, không giãn quai ruột."},{"name":"CT bụng có cản quang","duration_minutes":40,"result":"Không bất thường lớn. Không có chỉ định ở ca không dấu hiệu báo động, tăng nguy cơ ở người cao tuổi dùng metformin."}],"choices":{"diagnosis":{"ydx":["Táo bón mạn thứ phát do thuốc, ít uống nước và ít vận động (không dấu hiệu báo động)","Hội chứng ruột kích thích thể táo bón","Tắc ruột bán cấp","Suy giáp","Ung thư đại trực tràng"],"bd":["Tiện bí","Tiết tả","Phúc thống","Hư lao","Lỵ"],"bc":["Lý – Thực – Hàn","Biểu – Hư – Hàn","Biểu – Thực – Hàn","Lý – Hư – Nhiệt (tân dịch khuy tổn)","Lý – Thực – Nhiệt"],"the":["Khí bí (Can khí uất)","Nhiệt bí (Vị tràng thực nhiệt)","Huyết hư tân khuy (Âm huyết bất túc)","Hàn bí (Dương hư)","Tỳ ước"],"phap":["Sơ can giải uất","Ôn dương thông tiện","Thuận khí đạo trệ, thông tiện","Dưỡng huyết tư âm, nhuận tràng thông tiện","Tả nhiệt thông tiện (công hạ mạnh)"],"phuong":["Nhuận tràng hoàn","Tăng dịch thang","Đại thừa khí thang","Lục ma thang","Tế xuyên tiễn"],"huyet":["Liệt khuyết","Phong trì","Thái dương","Túc tam lý","Tam âm giao","Thiên khu","Chi câu","Đại chùy","Đại trường du"]},"actions":["Chụp CT bụng có cản quang","Dặn tái khám sớm và nội soi đại tràng khi thấy máu trong phân, phân đen, sụt cân, thiếu máu, đau bụng tăng, bí trung tiện, nôn","Tăng uống nước theo khả năng, ăn thêm rau, chất xơ, thói quen đi đại tiện đúng giờ","Xem xét lại thuốc: đổi dạng canxi hoặc điều chỉnh liều, hội chẩn bác sĩ kê đơn về nhóm thuốc có thể gây táo bón","Dùng thuốc nhuận tràng kích thích mỗi ngày kéo dài","Dùng thuốc tả hạ mạnh có Đại hoàng, Mang tiêu kéo dài","Hướng dẫn vận động nhẹ, xoa bụng theo chiều kim đồng hồ","Dùng thuốc nhuận tràng thẩm thấu hoặc thuốc tạo khối phân theo chỉ định thay vì thuốc kích thích kéo dài","Châm hoặc xoa bóp bấm huyệt Thiên khu, Đại trường du, Chi câu, Tam âm giao, Túc tam lý"]}}'::jsonb,
  '07b532f0af2af9eb94453a0b72077ee641919c00113a9428de704d74dd9cb8d5'
)
