  '{"schema_version":"1.0.0","case_id":"kham-tao-bon-man-cao-tuoi-da-benh","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-kham-tao-bon-man-cao-tuoi-da-benh-1","resource_type":"other","source":"American Gastroenterological Association and American College of Gastroenterology, Clinical Practice Guideline: Pharmacological Management of Chronic Idiopathic Constipation, 2023.","title":"American Gastroenterological Association and American College of Gastroenterology, Clinical Practice Guideline: Pharmacological Management of Chronic Idiopathic Constipation, 2023.","organization":null,"year_version":null,"citation":"American Gastroenterological Association and American College of Gastroenterology, Clinical Practice Guideline: Pharmacological Management of Chronic Idiopathic Constipation, 2023.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[1,3,5,6],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"essential"},{"index":3,"role":"essential"},{"index":4,"role":"neutral"},{"index":5,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Táo bón mạn thứ phát do thuốc, ít uống nước và ít vận động (không dấu hiệu báo động)","credit":"full"},{"text":"Ung thư đại trực tràng","credit":"none"},{"text":"Suy giáp","credit":"none"},{"text":"Tắc ruột bán cấp","credit":"none"},{"text":"Hội chứng ruột kích thích thể táo bón","credit":"none"}],"bd":[{"text":"Tiện bí","credit":"full"},{"text":"Phúc thống","credit":"none"},{"text":"Tiết tả","credit":"none"},{"text":"Lỵ","credit":"none"},{"text":"Hư lao","credit":"none"}],"bc":[{"text":"Lý – Hư – Nhiệt (tân dịch khuy tổn)","credit":"full"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Hàn","credit":"none"},{"text":"Biểu – Hư – Hàn","credit":"none"}],"the":[{"text":"Huyết hư tân khuy (Âm huyết bất túc)","credit":"full"},{"text":"Nhiệt bí (Vị tràng thực nhiệt)","credit":"none"},{"text":"Khí bí (Can khí uất)","credit":"none"},{"text":"Hàn bí (Dương hư)","credit":"none"},{"text":"Tỳ ước","credit":"none"}],"phap":[{"text":"Dưỡng huyết tư âm, nhuận tràng thông tiện","credit":"full"},{"text":"Tả nhiệt thông tiện (công hạ mạnh)","credit":"none"},{"text":"Thuận khí đạo trệ, thông tiện","credit":"none"},{"text":"Ôn dương thông tiện","credit":"none"},{"text":"Sơ can giải uất","credit":"none"}],"phuong":[{"text":"Nhuận tràng hoàn","credit":"full"},{"text":"Tăng dịch thang","credit":"partial"},{"text":"Đại thừa khí thang","credit":"none"},{"text":"Lục ma thang","credit":"none"},{"text":"Tế xuyên tiễn","credit":"none"}],"huyet":[{"text":"Thiên khu","credit":"full"},{"text":"Đại trường du","credit":"full"},{"text":"Chi câu","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Túc tam lý","credit":"full"},{"text":"Phong trì","credit":"none"},{"text":"Thái dương","credit":"none"},{"text":"Liệt khuyết","credit":"none"},{"text":"Đại chùy","credit":"none"}]},"action_options":[{"text":"Tăng uống nước theo khả năng, ăn thêm rau, chất xơ, thói quen đi đại tiện đúng giờ","time_minutes":4,"grade":"recommended","rationale":"Điều chỉnh yếu tố cơ bản gây táo bón."},{"text":"Xem xét lại thuốc: đổi dạng canxi hoặc điều chỉnh liều, hội chẩn bác sĩ kê đơn về nhóm thuốc có thể gây táo bón","time_minutes":3,"grade":"recommended","rationale":"Canxi, thuốc chẹn kênh canxi có thể góp phần."},{"text":"Dùng thuốc nhuận tràng thẩm thấu hoặc thuốc tạo khối phân theo chỉ định thay vì thuốc kích thích kéo dài","time_minutes":2,"grade":"recommended","rationale":"An toàn và phù hợp cho táo bón mạn ở người già."},{"text":"Châm hoặc xoa bóp bấm huyệt Thiên khu, Đại trường du, Chi câu, Tam âm giao, Túc tam lý","time_minutes":20,"grade":"recommended","rationale":"Dưỡng huyết nhuận tràng, điều hòa vận hóa đại trường."},{"text":"Hướng dẫn vận động nhẹ, xoa bụng theo chiều kim đồng hồ","time_minutes":5,"grade":"recommended","rationale":"Tăng nhu động ruột, phù hợp bệnh nhân đau khớp gối."},{"text":"Dặn tái khám sớm và nội soi đại tràng khi thấy máu trong phân, phân đen, sụt cân, thiếu máu, đau bụng tăng, bí trung tiện, nôn","time_minutes":2,"grade":"recommended","rationale":"Sàng lọc dấu hiệu báo động ung thư, tắc ruột."},{"text":"Chụp CT bụng có cản quang","time_minutes":40,"grade":"waste","rationale":"Không có chỉ định, nguy cơ ở người cao tuổi dùng metformin."},{"text":"Dùng thuốc tả hạ mạnh có Đại hoàng, Mang tiêu kéo dài","time_minutes":2,"grade":"harmful","rationale":"Thể huyết hư tân khuy ở người già, công hạ mạnh gây mất nước, rối loạn điện giải, hao thương chính khí."},{"text":"Dùng thuốc nhuận tràng kích thích mỗi ngày kéo dài","time_minutes":1,"grade":"harmful","rationale":"Gây phụ thuộc, mất kali, tổn thương chức năng đại tràng."}],"teaching_explanation":"Ở người cao tuổi đa bệnh, táo bón mạn thường do thuốc (canxi, thuốc chẹn kênh canxi), ít nước, ít vận động; cần loại trừ suy giáp, tăng canxi, đái tháo đường. Thể Huyết hư tân khuy: phân khô như phân dê, da khô, chóng mặt, lưỡi nhạt ít tân, mạch tế sáp, dùng dưỡng huyết nhuận tràng, tránh công hạ mạnh. Dấu hiệu báo động cần nội soi và chuyển tuyến: máu trong phân, sụt cân, thiếu máu, táo bón mới xuất hiện sau 50 tuổi, bí trung tiện."}'::jsonb,
  '38dd409a7f6bb0c1b9d782c3bf33c568ef6a505759bfbaef0a207d5742209060'
)
