insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'canh-vai-tay-thoai-hoa-csc',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"canh-vai-tay-thoai-hoa-csc","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau cổ vai lan xuống tay, tê ngón cái và ngón trỏ","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":56,"sex":"nam","patient_label":"Ông Trần Văn Khải"},"presentation":{"intro":"Ông làm kế toán, ngồi máy tính nhiều giờ mỗi ngày. Ông đến vì đau cổ vai gáy 2 tháng, mấy tuần nay đau lan xuống cánh tay phải kèm tê ngón cái và ngón trỏ.","place":"Phòng châm cứu","clock":"08:40","night":false},"vitals":{"hr":76,"sbp":130,"dbp":80,"rr":18,"temperature_c":36.6,"spo2":98},"history":[{"question":"Đau từ khi nào, đau ở đâu, lan đi đâu?","response":"Đau cổ vai gáy bên phải khoảng 2 tháng, 3 tuần nay đau lan dọc mặt ngoài cánh tay xuống cẳng tay, tới ngón cái và ngón trỏ."},{"question":"Có tê, kim châm hoặc yếu tay không?","response":"Tê như kiến bò ở ngón cái, ngón trỏ tay phải. Cầm bút, cầm ly còn được, chưa rơi đồ."},{"question":"Đau tăng khi nào, đỡ khi nào?","response":"Đau tăng khi ngửa cổ, quay cổ sang phải, khi ngồi máy lạnh lâu và buổi sáng sớm. Chườm ấm, xoa bóp nhẹ thì dễ chịu."},{"question":"Có sợ gió, sợ lạnh, người nặng nề không?","response":"Sợ gió lạnh, cổ gáy cứng như bị chèn, hay quấn khăn. Người hơi nặng nề, trời ẩm đau nhiều hơn."},{"question":"Có yếu hai chân, đi loạng choạng, vụng về khi cài khuy áo không?","response":"Không yếu chân, đi đứng bình thường, cài khuy áo bình thường."},{"question":"Có rối loạn đại tiểu tiện không?","response":"Đại tiểu tiện bình thường."},{"question":"Có sốt, sụt cân, đau về đêm không giảm khi đổi tư thế không?","response":"Không sốt, không sụt cân. Đau có đỡ khi đổi tư thế."},{"question":"Có chấn thương cổ hoặc tai nạn gần đây không?","response":"Không có chấn thương."},{"question":"Ăn uống, ngủ nghỉ ra sao?","response":"Ăn được, ngủ hơi khó vì đau khi nằm nghiêng bên phải."},{"question":"Tiền sử bệnh nội khoa và thuốc đang dùng?","response":"Tăng huyết áp nhẹ, đang uống một viên thuốc hạ áp mỗi ngày. Không đái tháo đường."}],"examination":[{"group":"V","item":"Thần sắc, dáng đi","finding":"Tỉnh táo, sắc mặt bình thường, dáng đi bình thường. Đầu hơi nghiêng sang trái, vai phải hơi nhô."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói rõ, hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch phù khẩn."},{"group":"T","item":"Sờ vùng cổ vai","finding":"Cơ thang, cơ nâng vai bên phải co cứng, ấn đau, sờ thấy lạnh hơn bên trái."},{"group":"K","item":"Tầm vận động cột sống cổ","finding":"Hạn chế ngửa và xoay phải, khi ngửa và nghiêng phải thì đau lan xuống tay (nghiệm pháp Spurling dương tính)."},{"group":"K","item":"Thần kinh chi trên","finding":"Giảm cảm giác nhẹ ngón cái và ngón trỏ phải, cơ lực 5/5, phản xạ gân cơ nhị đầu bên phải giảm nhẹ. Dấu Hoffmann âm tính hai bên."},{"group":"K","item":"Thần kinh chi dưới","finding":"Cơ lực chi dưới 5/5, phản xạ gân gối bình thường, không có dấu Babinski."}],"investigations":[{"name":"X-quang cột sống cổ thẳng, nghiêng, chếch 3/4","duration_minutes":15,"result":"Mất đường cong sinh lý, hẹp khe C5-C6, gai xương bờ trước thân đốt C5-C6, hẹp lỗ liên hợp C5-C6 bên phải."},{"name":"MRI cột sống cổ","duration_minutes":45,"result":"Thoái hóa đĩa đệm C5-C6, phồng đĩa đệm lệch cạnh phải chèn ép nhẹ rễ C6 phải. Tủy sống không bị chèn ép, không có tín hiệu bất thường trong tủy."},{"name":"Điện cơ và dẫn truyền thần kinh chi trên","duration_minutes":30,"result":"Gợi ý tổn thương rễ C6 phải mức độ nhẹ."},{"name":"Công thức máu, tốc độ máu lắng","duration_minutes":20,"result":"Bình thường."},{"name":"Chụp mạch máu não (DSA)","duration_minutes":60,"result":"Không có chỉ định ở ca này, thủ thuật xâm lấn."}],"choices":{"diagnosis":{"ydx":["Viêm quanh khớp vai","Hội chứng ống cổ tay","Ung thư di căn cột sống cổ","Hội chứng cổ vai cánh tay do thoái hóa cột sống cổ (chèn ép rễ C6)","Bệnh lý tủy cổ do thoái hóa"],"bd":["Trúng phong","Hạng cường do ngoại cảm","Ngũ thập kiên","Cảnh tý (kiên tý)","Thống phong"],"bc":["Biểu – Thực – Hàn","Biểu – Thực – Nhiệt","Lý – Hư – Hàn","Lý – Hư – Nhiệt","Lý – Thực – Nhiệt"],"the":["Khí huyết hư","Đàm thấp trở lạc","Khí trệ huyết ứ","Can thận hư","Phong hàn thấp tý"],"phap":["Kiện tỳ hóa đàm","Bổ can thận, cường cân cốt","Khu phong tán hàn trừ thấp, thông kinh hoạt lạc","Hoạt huyết hóa ứ, hành khí chỉ thống","Thanh nhiệt lợi thấp"],"phuong":["Độc hoạt tang ký sinh thang","Quyên tý thang","Bạch hổ gia quế chi thang","Cát căn thang","Thân thống trục ứ thang"],"huyet":["Quan nguyên","Thái khê","Phong trì","Hợp cốc","Kiên tỉnh","Thừa sơn","Dũng tuyền","Khúc trì","Đại chùy"]},"actions":["Nắn bẻ cột sống cổ mạnh, xoay đột ngột","Chiếu đèn hồng ngoại hoặc chườm ấm vùng cổ gáy","Châm Phong trì, Kiên tỉnh (Đởm), Đại chùy (Đốc mạch), Khúc trì, Hợp cốc (Đại trường), kèm giác hơi hoặc cứu vùng cổ gáy","Sàng lọc dấu hiệu chèn ép tủy cổ (Hoffmann, Babinski, rối loạn cơ tròn, đi vụng về)","Cho thuốc thanh nhiệt hàn lương mạnh (Hoàng liên, Thạch cao)","Hướng dẫn tư thế làm việc, chỉnh độ cao màn hình, nghỉ giải lao mỗi 45 phút","Kéo giãn cột sống cổ cường độ cao kèm xoay bẻ mạnh","Dặn quay lại ngay nếu yếu tay chân tăng, đi loạng choạng, bí tiểu"]}}'::jsonb,
  '15e6449e9c00a2ac08f1296c0abed13ba687530207e532bf821c3872fbc52d11'
)
