values (
  'canh-vai-tay-thoai-hoa-csc',
  '{"schema_version":"1.0.0","case_id":"canh-vai-tay-thoai-hoa-csc","server_only":true,"title_reveal":null,"resources_after_submission":[{"schema_version":"1.0.0","resource_id":"legacy-canh-vai-tay-thoai-hoa-csc-1","resource_type":"other","source":"North American Spine Society, Evidence-Based Clinical Guidelines for Multidisciplinary Spine Care: Diagnosis and Treatment of Cervical Radiculopathy from Degenerative Disorders, 2010.","title":"North American Spine Society, Evidence-Based Clinical Guidelines for Multidisciplinary Spine Care: Diagnosis and Treatment of Cervical Radiculopathy from Degenerative Disorders, 2010.","organization":null,"year_version":null,"citation":"North American Spine Society, Evidence-Based Clinical Guidelines for Multidisciplinary Spine Care: Diagnosis and Treatment of Cervical Radiculopathy from Degenerative Disorders, 2010.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]},{"schema_version":"1.0.0","resource_id":"legacy-byt-5013-2020-a40685e8c8a1","resource_type":"regulation","source":"https://luatvietnam.vn/y-te/quyet-dinh-5013-qd-byt-huong-dan-chan-doan-va-dieu-tri-benh-theo-y-hoc-co-truyen-194863-d1.html","title":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","organization":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[1,3,4,5,6,7],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Hội chứng cổ vai cánh tay do thoái hóa cột sống cổ (chèn ép rễ C6)","credit":"full"},{"text":"Bệnh lý tủy cổ do thoái hóa","credit":"none"},{"text":"Hội chứng ống cổ tay","credit":"none"},{"text":"Viêm quanh khớp vai","credit":"none"},{"text":"Ung thư di căn cột sống cổ","credit":"none"}],"bd":[{"text":"Cảnh tý (kiên tý)","credit":"full"},{"text":"Ngũ thập kiên","credit":"none"},{"text":"Trúng phong","credit":"none"},{"text":"Hạng cường do ngoại cảm","credit":"none"},{"text":"Thống phong","credit":"none"}],"bc":[{"text":"Biểu – Thực – Hàn","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Phong hàn thấp tý","credit":"full"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Can thận hư","credit":"none"},{"text":"Đàm thấp trở lạc","credit":"none"},{"text":"Khí huyết hư","credit":"none"}],"phap":[{"text":"Khu phong tán hàn trừ thấp, thông kinh hoạt lạc","credit":"full"},{"text":"Bổ can thận, cường cân cốt","credit":"none"},{"text":"Hoạt huyết hóa ứ, hành khí chỉ thống","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Kiện tỳ hóa đàm","credit":"none"}],"phuong":[{"text":"Cát căn thang","credit":"full"},{"text":"Quyên tý thang","credit":"full"},{"text":"Độc hoạt tang ký sinh thang","credit":"none"},{"text":"Thân thống trục ứ thang","credit":"none"},{"text":"Bạch hổ gia quế chi thang","credit":"none"}],"huyet":[{"text":"Phong trì","credit":"full"},{"text":"Kiên tỉnh","credit":"full"},{"text":"Đại chùy","credit":"full"},{"text":"Khúc trì","credit":"full"},{"text":"Hợp cốc","credit":"full"},{"text":"Dũng tuyền","credit":"none"},{"text":"Thái khê","credit":"none"},{"text":"Quan nguyên","credit":"none"},{"text":"Thừa sơn","credit":"none"}]},"action_options":[{"text":"Châm Phong trì, Kiên tỉnh (Đởm), Đại chùy (Đốc mạch), Khúc trì, Hợp cốc (Đại trường), kèm giác hơi hoặc cứu vùng cổ gáy","time_minutes":25,"grade":"recommended","rationale":"Khu phong tán hàn, thông kinh lạc vùng cổ vai tay."},{"text":"Sàng lọc dấu hiệu chèn ép tủy cổ (Hoffmann, Babinski, rối loạn cơ tròn, đi vụng về)","time_minutes":3,"grade":"recommended","rationale":"Phát hiện bệnh lý tủy cần chuyển phẫu thuật thần kinh."},{"text":"Hướng dẫn tư thế làm việc, chỉnh độ cao màn hình, nghỉ giải lao mỗi 45 phút","time_minutes":3,"grade":"recommended","rationale":"Giảm tải cho cột sống cổ, ngừa tái phát."},{"text":"Chiếu đèn hồng ngoại hoặc chườm ấm vùng cổ gáy","time_minutes":10,"grade":"recommended","rationale":"Hợp với thể phong hàn thấp."},{"text":"Dặn quay lại ngay nếu yếu tay chân tăng, đi loạng choạng, bí tiểu","time_minutes":2,"grade":"recommended","rationale":"Dấu hiệu chèn ép tủy tiến triển."},{"text":"Kéo giãn cột sống cổ cường độ cao kèm xoay bẻ mạnh","time_minutes":10,"grade":"waste","rationale":"Không cần thiết, tăng nguy cơ tổn thương."},{"text":"Nắn bẻ cột sống cổ mạnh, xoay đột ngột","time_minutes":5,"grade":"harmful","rationale":"Có thể gây tổn thương rễ, tủy hoặc động mạch đốt sống."},{"text":"Cho thuốc thanh nhiệt hàn lương mạnh (Hoàng liên, Thạch cao)","time_minutes":2,"grade":"harmful","rationale":"Thể phong hàn thấp, thuốc hàn làm tà khí ngưng trệ nặng hơn."}],"teaching_explanation":"Đau cổ lan tay theo dải C6, tê ngón cái ngón trỏ, nghiệm pháp Spurling dương tính gợi ý chèn ép rễ C6. Sợ lạnh, rêu trắng mỏng, mạch phù khẩn cho ra thể phong hàn thấp tý. Luôn tìm dấu hiệu bệnh lý tủy cổ (Hoffmann, rối loạn cơ tròn, đi vụng về) và dấu hiệu ác tính (sụt cân, đau đêm) trước khi châm cứu."}'::jsonb,
