values (
  'thoai-hoa-khop-goi-han-that',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"thoai-hoa-khop-goi-han-that","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau hai gối khi lên xuống cầu thang","setting":"chamcuu","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":63,"sex":"nữ","patient_label":"Bà Nguyễn Thị Tâm"},"presentation":{"intro":"Bà về hưu, đến vì đau hai gối khoảng 1 năm, nặng dần, đau khi lên xuống cầu thang và đi bộ xa, trời lạnh đau nhiều hơn.","place":"Phòng châm cứu","clock":"14:10","night":false},"vitals":{"hr":74,"sbp":125,"dbp":78,"rr":18,"temperature_c":36.7,"spo2":98},"history":[{"question":"Đau gối như thế nào, bên nào nhiều hơn?","response":"Đau âm ỉ hai gối, gối phải nhiều hơn, đau khi đứng lên ngồi xuống, lên xuống cầu thang. Nghỉ thì đỡ."},{"question":"Buổi sáng có cứng khớp không, bao lâu?","response":"Cứng gối khi mới ngủ dậy, khoảng 10 đến 15 phút là đi lại được."},{"question":"Gối có sưng, nóng, đỏ không? Có sốt không?","response":"Không sưng nóng đỏ, không sốt. Thỉnh thoảng gối hơi tràn dịch nhẹ sau khi đi nhiều."},{"question":"Trời lạnh, chườm nóng ảnh hưởng thế nào?","response":"Trời lạnh, trời mưa đau tăng. Chườm ấm thì đỡ."},{"question":"Có đau lưng, mỏi gối, ù tai, tiểu đêm không?","response":"Hay đau mỏi lưng, gối mỏi yếu, tiểu đêm 2 đến 3 lần, tai ù nhẹ."},{"question":"Có đau nhiều khớp nhỏ ở bàn tay, sưng đối xứng không?","response":"Không, các khớp bàn tay bình thường."},{"question":"Cân nặng, nghề nghiệp trước đây?","response":"Thừa cân, BMI khoảng 27. Trước đây là nhân viên bán hàng đứng nhiều."},{"question":"Đã dùng thuốc giảm đau chưa?","response":"Thỉnh thoảng uống thuốc giảm đau kháng viêm mua ngoài, đỡ chút rồi lại đau."},{"question":"Ăn ngủ ra sao?","response":"Ăn được, ngủ tạm, đôi lúc đau khi trở mình."}],"examination":[{"group":"V","item":"Dáng đi, hình dạng khớp gối","finding":"Dáng đi hơi khập khiễng, hai gối hơi vẹo trong, không sưng đỏ."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói bình thường, hơi thở không hôi."},{"group":"T","item":"Mạch","finding":"Mạch trầm tế nhược, hai bộ xích yếu."},{"group":"T","item":"Sờ gối","finding":"Da gối không nóng, sờ hơi lạnh, có lạo xạo khi cử động, ấn đau khe khớp trong."},{"group":"K","item":"Khám khớp gối","finding":"Tầm vận động gập 120 độ, duỗi đủ, có tiếng lục cục. Nghiệm pháp bập bềnh xương bánh chè dương tính nhẹ ở gối phải."},{"group":"K","item":"Thần kinh chi dưới","finding":"Cơ lực 5/5, cảm giác và phản xạ bình thường, không có dấu thần kinh khu trú."},{"group":"K","item":"Khám khớp háng cùng bên","finding":"Tầm vận động khớp háng bình thường, không đau."}],"investigations":[{"name":"X-quang khớp gối thẳng và nghiêng khi đứng","duration_minutes":15,"result":"Hẹp khe khớp đùi chày trong, gai xương bờ khớp, xơ cứng xương dưới sụn, Kellgren-Lawrence độ 2 đến 3."},{"name":"Tốc độ máu lắng, CRP","duration_minutes":20,"result":"Bình thường."},{"name":"Acid uric máu","duration_minutes":15,"result":"Bình thường."},{"name":"Yếu tố dạng thấp (RF), anti-CCP","duration_minutes":30,"result":"Âm tính."},{"name":"MRI khớp gối","duration_minutes":45,"result":"Không có chỉ định để chẩn đoán thoái hóa khớp thông thường nếu đã có X-quang điển hình."}],"choices":{"diagnosis":{"ydx":["Viêm khớp dạng thấp","Gút mạn","Hoại tử vô khuẩn chỏm xương đùi","Viêm khớp gối nhiễm khuẩn","Thoái hóa khớp gối nguyên phát"],"bd":["Hạc tất phong (tý chứng vùng gối)","Lịch tiết phong","Yêu thống","Thống phong","Nuy chứng"],"bc":["Biểu – Thực – Nhiệt","Lý – Thực – Nhiệt","Biểu – Hư – Hàn","Lý – Hư – Nhiệt","Lý – Hư kiêm Thực – Hàn"],"the":["Thấp nhiệt tý","Khí trệ huyết ứ","Đàm thấp trở lạc","Tỳ vị hư","Can thận hư kèm phong hàn thấp"],"phap":["Giải biểu tán hàn","Bổ can thận, khu phong tán hàn trừ thấp, thông kinh hoạt lạc","Thanh nhiệt lợi thấp, thông lạc","Kiện tỳ ích khí","Hoạt huyết hóa ứ, hành khí"],"phuong":["Tứ quân tử thang","Ngân kiều tán","Bạch hổ gia quế chi thang","Thân thống trục ứ thang","Độc hoạt tang ký sinh thang"],"huyet":["Huyết hải","Thái xung","Phong trì","Thận du","Nội quan","Hợp cốc","Độc tỵ","Nội tất nhãn","Dương lăng tuyền"]},"actions":["Tiêm corticoid nội khớp lặp lại liên tục mỗi tuần","Sàng lọc dấu hiệu viêm khớp cấp: sưng nóng đỏ, sốt, đau dữ dội khi nghỉ","Châm Độc tỵ, Dương lăng tuyền, Huyết hải, Nội tất nhãn, Thận du, kèm cứu ngải quanh gối","Chườm ấm hoặc chiếu đèn hồng ngoại vùng gối","Dặn thận trọng với thuốc kháng viêm giảm đau, nên dùng khi cần và theo hướng dẫn thầy thuốc","Châm sâu, lưu kim lâu ngay vào gối đang sưng nóng đỏ nghi viêm nhiễm","Hướng dẫn giảm cân, tập mạnh cơ tứ đầu đùi, tránh ngồi xổm, leo cầu thang nhiều","Chụp MRI khớp gối thường quy"]}}'::jsonb,
  'a8e756356671d235fa20f28f1916e1e88c0301dfb4de8041885d57c1201b7bef'
)
