zation":null,"year_version":null,"citation":"Bộ Y tế, Hướng dẫn chẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5],"examination_essential_indices":[0,1,3,4,5],"investigation_roles":[{"index":0,"role":"essential"},{"index":1,"role":"neutral"},{"index":2,"role":"neutral"},{"index":3,"role":"neutral"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Thoái hóa khớp gối nguyên phát","credit":"full"},{"text":"Viêm khớp dạng thấp","credit":"none"},{"text":"Gút mạn","credit":"none"},{"text":"Viêm khớp gối nhiễm khuẩn","credit":"none"},{"text":"Hoại tử vô khuẩn chỏm xương đùi","credit":"none"}],"bd":[{"text":"Hạc tất phong (tý chứng vùng gối)","credit":"full"},{"text":"Thống phong","credit":"none"},{"text":"Yêu thống","credit":"none"},{"text":"Lịch tiết phong","credit":"none"},{"text":"Nuy chứng","credit":"none"}],"bc":[{"text":"Lý – Hư kiêm Thực – Hàn","credit":"full"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Hàn","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Can thận hư kèm phong hàn thấp","credit":"full"},{"text":"Thấp nhiệt tý","credit":"none"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Đàm thấp trở lạc","credit":"none"},{"text":"Tỳ vị hư","credit":"none"}],"phap":[{"text":"Bổ can thận, khu phong tán hàn trừ thấp, thông kinh hoạt lạc","credit":"full"},{"text":"Thanh nhiệt lợi thấp, thông lạc","credit":"none"},{"text":"Hoạt huyết hóa ứ, hành khí","credit":"none"},{"text":"Kiện tỳ ích khí","credit":"none"},{"text":"Giải biểu tán hàn","credit":"none"}],"phuong":[{"text":"Độc hoạt tang ký sinh thang","credit":"full"},{"text":"Bạch hổ gia quế chi thang","credit":"none"},{"text":"Thân thống trục ứ thang","credit":"none"},{"text":"Tứ quân tử thang","credit":"none"},{"text":"Ngân kiều tán","credit":"none"}],"huyet":[{"text":"Độc tỵ","credit":"full"},{"text":"Nội tất nhãn","credit":"full"},{"text":"Huyết hải","credit":"full"},{"text":"Dương lăng tuyền","credit":"full"},{"text":"Thận du","credit":"full"},{"text":"Hợp cốc","credit":"none"},{"text":"Phong trì","credit":"none"},{"text":"Nội quan","credit":"none"},{"text":"Thái xung","credit":"none"}]},"action_options":[{"text":"Châm Độc tỵ, Dương lăng tuyền, Huyết hải, Nội tất nhãn, Thận du, kèm cứu ngải quanh gối","time_minutes":25,"grade":"recommended","rationale":"Bổ can thận, tán hàn thông lạc."},{"text":"Sàng lọc dấu hiệu viêm khớp cấp: sưng nóng đỏ, sốt, đau dữ dội khi nghỉ","time_minutes":3,"grade":"recommended","rationale":"Loại trừ viêm khớp nhiễm khuẩn, gút, viêm khớp dạng thấp."},{"text":"Hướng dẫn giảm cân, tập mạnh cơ tứ đầu đùi, tránh ngồi xổm, leo cầu thang nhiều","time_minutes":4,"grade":"recommended","rationale":"Giảm tải khớp gối."},{"text":"Chườm ấm hoặc chiếu đèn hồng ngoại vùng gối","time_minutes":10,"grade":"recommended","rationale":"Hợp thể hàn thấp."},{"text":"Dặn thận trọng với thuốc kháng viêm giảm đau, nên dùng khi cần và theo hướng dẫn thầy thuốc","time_minutes":2,"grade":"recommended","rationale":"Tránh tác dụng phụ trên dạ dày, thận."},{"text":"Chụp MRI khớp gối thường quy","time_minutes":45,"grade":"waste","rationale":"Không cần khi X-quang đã điển hình."},{"text":"Châm sâu, lưu kim lâu ngay vào gối đang sưng nóng đỏ nghi viêm nhiễm","time_minutes":5,"grade":"harmful","rationale":"Nguy cơ đưa vi khuẩn vào khớp."},{"text":"Tiêm corticoid nội khớp lặp lại liên tục mỗi tuần","time_minutes":5,"grade":"harmful","rationale":"Làm tổn thương sụn, tăng nguy cơ nhiễm khuẩn."}],"teaching_explanation":"Đau cơ giới tăng khi vận động, cứng khớp buổi sáng dưới 30 phút, X-quang hẹp khe khớp và gai xương là thoái hóa khớp gối. Thể can thận hư (đau mỏi lưng gối, tiểu đêm, mạch trầm tế) kèm phong hàn thấp (đau tăng khi lạnh). Cần phân biệt với viêm khớp nhiễm khuẩn, gút, viêm khớp dạng thấp."}'::jsonb,
