insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'toa-cot-phong-thoat-vi-dia-dem',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"toa-cot-phong-thoat-vi-dia-dem","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau thắt lưng lan chân phải, yếu bàn chân","setting":"chamcuu","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":42,"sex":"nam","patient_label":"Anh Lê Quốc Bảo"},"presentation":{"intro":"Anh làm tài xế đường dài, đến vì đau thắt lưng lan xuống chân phải 5 tuần, mấy ngày nay thấy tê mu bàn chân và hơi khó nhấc mũi chân.","place":"Phòng châm cứu","clock":"10:20","night":false},"vitals":{"hr":80,"sbp":128,"dbp":82,"rr":18,"temperature_c":36.8,"spo2":98},"history":[{"question":"Đau bắt đầu thế nào, lan đi đâu?","response":"Đau thắt lưng sau khi khuân đồ nặng 5 tuần trước, sau đó đau lan mông, mặt ngoài đùi, ngoài cẳng chân tới mu bàn chân phải."},{"question":"Đau như thế nào, tăng khi nào?","response":"Đau như dao đâm, cố định, tăng khi ho, hắt hơi, ngồi lâu, cúi người. Đêm đau nhiều hơn, phải nằm co chân."},{"question":"Có yếu chân, vấp ngón chân khi đi không?","response":"Mấy ngày nay hay vấp mũi chân phải, nhấc ngón cái lên khó hơn bên trái."},{"question":"Có tê vùng sinh dục, hậu môn, bí tiểu hoặc tiểu không tự chủ không?","response":"Không tê vùng đáy chậu. Tiểu tiện, đại tiện bình thường. Chức năng sinh lý chưa thay đổi."},{"question":"Có yếu hoặc tê cả hai chân không?","response":"Chỉ chân phải, chân trái bình thường."},{"question":"Có sốt, sụt cân, tiền sử ung thư, tiêm chích hoặc nhiễm trùng gần đây không?","response":"Không sốt, không sụt cân, không tiền sử ung thư, không có nhiễm trùng gần đây."},{"question":"Chườm nóng, nghỉ ngơi có đỡ không?","response":"Chườm nóng đỡ, trời lạnh đau tăng. Nằm nghỉ đỡ nhưng đêm vẫn đau."},{"question":"Ăn uống, ngủ nghỉ thế nào?","response":"Ngủ kém vì đau, ăn bình thường, hay táo bón nhẹ."},{"question":"Đã dùng thuốc nào, đã chụp phim chưa?","response":"Uống thuốc giảm đau và giãn cơ 1 tuần, đỡ ít. Chưa chụp phim."}],"examination":[{"group":"V","item":"Thần sắc, tư thế, dáng đi","finding":"Sắc mặt hơi tối, tư thế nghiêng người sang trái khi đứng, dáng đi thận trọng, chân phải bước nhẹ, hơi vấp mũi chân."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi tím tối, có điểm ứ huyết hai bên rìa, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Nói rõ, thở không hôi, hay thở dài vì đau."},{"group":"T","item":"Mạch","finding":"Mạch huyền sáp."},{"group":"T","item":"Sờ vùng thắt lưng","finding":"Co cứng cơ cạnh sống L4-L5 phải, ấn đau điểm cạnh sống L4-L5 và dọc đường đi thần kinh tọa, sờ hơi lạnh."},{"group":"K","item":"Dấu Lasègue và Valleix","finding":"Lasègue dương tính phải ở 40 độ, điểm Valleix đau."},{"group":"K","item":"Cơ lực và cảm giác chi dưới phải","finding":"Gập mu bàn chân và duỗi ngón cái phải 4/5, giảm cảm giác mu bàn chân và mặt ngoài cẳng chân phải. Phản xạ gân gót bình thường."},{"group":"K","item":"Cảm giác vùng yên ngựa, trương lực cơ vòng hậu môn","finding":"Cảm giác vùng đáy chậu bình thường, trương lực cơ vòng hậu môn bình thường."}],"investigations":[{"name":"MRI cột sống thắt lưng","duration_minutes":45,"result":"Thoát vị đĩa đệm L4-L5 lệch cạnh phải, chèn ép rễ L5 phải. Ống sống không hẹp nặng, không chèn ép chùm đuôi ngựa, không thấy khối u hay viêm đĩa đệm."},{"name":"X-quang cột sống thắt lưng thẳng nghiêng","duration_minutes":15,"result":"Hẹp khe đĩa đệm L4-L5, gai xương nhẹ."},{"name":"Công thức máu, CRP, tốc độ máu lắng","duration_minutes":20,"result":"Bình thường."},{"name":"Điện cơ chi dưới phải","duration_minutes":30,"result":"Tổn thương rễ L5 phải mức độ nhẹ đến vừa."},{"name":"PET-CT toàn thân","duration_minutes":120,"result":"Không có chỉ định ở ca này khi chưa có dấu hiệu nghi ngờ ác tính."}],"choices":{"diagnosis":{"ydx":["Viêm khớp cùng chậu","Hội chứng đuôi ngựa","Đau thần kinh tọa do thoát vị đĩa đệm L4-L5 chèn ép rễ L5","Hội chứng cơ lê","Hẹp ống sống do ung thư di căn"],"bd":["Tọa cốt phong","Hạc tất phong","Chứng nuy","Yêu thống do thận hư","Thống phong"],"bc":["Lý – Hư – Nhiệt","Biểu – Thực – Hàn","Lý – Thực – Không hàn không nhiệt rõ","Lý – Hư – Hàn","Lý – Thực – Nhiệt"],"the":["Khí huyết hư","Thấp nhiệt","Phong hàn thấp tý","Can thận hư","Khí trệ huyết ứ"],"phap":["Hoạt huyết hóa ứ, hành khí chỉ thống, thông kinh lạc","Bổ can thận, cường yêu tất","Khu phong tán hàn","Bổ khí dưỡng huyết","Thanh nhiệt lợi thấp"],"phuong":["Thân thống trục ứ thang","Độc hoạt tang ký sinh thang","Bát vị hoàn","Quy tỳ thang","Bát chính tán"],"huyet":["Ủy trung","Khúc trì","Dương lăng tuyền","Đại trường du","Nội quan","Hoàn khiêu","Phong trì","Huyền chung","Hợp cốc"]},"actions":["Chụp PET-CT toàn thân","Cho tập cúi gập mạnh, ép cột sống thắt lưng tối đa","Dặn quay lại ngay nếu tê vùng đáy chậu, bí tiểu, yếu hai chân tăng","Nắn bẻ, bấm huyệt mạnh cột sống thắt lưng khi chưa loại trừ hội chứng đuôi ngựa","Hỏi và khám đầy đủ dấu hiệu hội chứng đuôi ngựa (tê vùng yên ngựa, bí tiểu, yếu hai chân, trương lực cơ vòng)","Châm Đại trường du, Hoàn khiêu (Đởm), Dương lăng tuyền (Đởm), Huyền chung (Đởm), Ủy trung (Bàng quang)","Hẹn tái khám sau 3 đến 5 ngày, chuyển khoa phẫu thuật thần kinh nếu yếu cơ tiến triển hoặc không cải thiện sau 6 đến 8 tuần","Hướng dẫn tư thế nằm nghỉ, tránh khuân vác, cúi gập, ngồi lái lâu"]}}'::jsonb,
  '875628d330e39dd64ea1d1fb667cbbe9196e06c208a34d740813b7f9a99f49a7'
)
