values (
  'hoi-chung-ong-co-tay-huyet-hu',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"hoi-chung-ong-co-tay-huyet-hu","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Tê bàn tay về đêm, hay giật mình thức giấc","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":38,"sex":"nữ","patient_label":"Chị Phạm Thị Lan"},"presentation":{"intro":"Chị là nhân viên đóng gói, đến vì tê và đau bàn tay phải 3 tháng, tê nhiều về đêm làm chị thức giấc phải vẩy tay.","place":"Phòng châm cứu","clock":"15:30","night":false},"vitals":{"hr":72,"sbp":105,"dbp":68,"rr":17,"temperature_c":36.5,"spo2":99},"history":[{"question":"Tê ở những ngón nào?","response":"Tê ngón cái, ngón trỏ, ngón giữa và nửa ngón nhẫn phía ngón cái bên tay phải. Ngón út không tê."},{"question":"Khi nào tê nhiều nhất?","response":"Tê nhiều về đêm và sáng sớm, thức giấc phải vẩy tay mới đỡ. Khi cầm điện thoại, cầm xe máy lâu cũng tê."},{"question":"Có yếu tay, cầm nắm rơi đồ không?","response":"Dạo này cầm chai nước, kéo cắt hay tuột tay."},{"question":"Có đau cổ, đau lan từ cổ xuống tay không?","response":"Không đau cổ, đau chỉ ở cổ tay và bàn tay."},{"question":"Tay có lạnh, sợ lạnh không?","response":"Tay chân hay lạnh, ngâm nước lạnh thì tê tăng. Chườm ấm thì đỡ."},{"question":"Có bệnh nền như đái tháo đường, suy giáp, viêm khớp dạng thấp, mang thai không?","response":"Không đái tháo đường, không bệnh tuyến giáp, không mang thai. Không đau sưng nhiều khớp."},{"question":"Nghề nghiệp, công việc lặp lại cổ tay?","response":"Đóng gói hàng, thao tác lặp lại cổ tay 8 giờ mỗi ngày."},{"question":"Ăn ngủ, kinh nguyệt?","response":"Hay hồi hộp, ngủ kém, hoa mắt khi đứng lên. Kinh nguyệt ít, màu nhạt."},{"question":"Sắc mặt, cảm giác mệt mỏi?","response":"Mệt mỏi, da xanh, hay chóng mặt nhẹ."}],"examination":[{"group":"V","item":"Thần sắc, hình thái bàn tay","finding":"Sắc mặt nhợt, môi nhạt. Bàn tay không sưng, ô mô cái chưa teo rõ."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói nhỏ, hơi thở bình thường."},{"group":"T","item":"Mạch","finding":"Mạch tế, trầm."},{"group":"T","item":"Sờ tay","finding":"Bàn tay, đầu ngón lạnh, ẩm nhẹ."},{"group":"K","item":"Nghiệm pháp Tinel và Phalen","finding":"Tinel dương tính, Phalen dương tính sau 30 giây gập cổ tay."},{"group":"K","item":"Cảm giác và cơ lực bàn tay","finding":"Giảm cảm giác ngón 1, 2, 3 và nửa ngón 4 mặt gan tay, lực dạng ngón cái 4/5, chưa teo ô mô cái."},{"group":"K","item":"Khám cột sống cổ, thần kinh chi trên","finding":"Spurling âm tính, phản xạ gân cơ chi trên bình thường."}],"investigations":[{"name":"Điện cơ và dẫn truyền thần kinh giữa","duration_minutes":30,"result":"Giảm tốc độ dẫn truyền cảm giác và tăng thời gian tiềm vận động thần kinh giữa qua cổ tay phải, mức độ nhẹ đến vừa."},{"name":"Siêu âm cổ tay","duration_minutes":15,"result":"Thần kinh giữa phù nề, tăng diện cắt ngang trước ống cổ tay."},{"name":"Đường huyết đói, TSH","duration_minutes":20,"result":"Bình thường."},{"name":"Công thức máu, ferritin","duration_minutes":20,"result":"Hb 10,8 g/dL, thiếu máu nhẹ thiếu sắt."},{"name":"MRI não","duration_minutes":45,"result":"Không có chỉ định ở ca này."}],"choices":{"diagnosis":{"ydx":["Hội chứng lối thoát lồng ngực","Bệnh đa dây thần kinh do đái tháo đường","Viêm khớp dạng thấp","Thoát vị đĩa đệm cổ C6","Hội chứng ống cổ tay (thần kinh giữa) phải"],"bd":["Huyễn vựng","Cảnh tý","Uyển tý (chứng tý vùng cổ tay)","Trúng phong","Kiên tý"],"bc":["Biểu – Hư – Nhiệt","Lý – Hư – Nhiệt","Lý – Hư – Hàn","Lý – Thực – Nhiệt","Biểu – Thực – Hàn"],"the":["Huyết hư hàn ngưng","Đàm thấp trở lạc","Khí trệ huyết ứ","Can dương thượng cang","Thấp nhiệt"],"phap":["Bình can tiềm dương","Thanh nhiệt lợi thấp","Hoạt huyết hóa ứ mạnh","Kiện tỳ hóa đàm","Ôn kinh tán hàn, dưỡng huyết thông mạch"],"phuong":["Quyên tý thang","Đương quy tứ nghịch thang","Bạch hổ thang","Thiên ma câu đằng ẩm","Ngân kiều tán"],"huyet":["Đại lăng","Tam âm giao","Nội quan","Ngoại quan","Dũng tuyền","Hợp cốc","Yêu dương quan","Phong trì","Thái xung"]},"actions":["Đánh giá mức độ: teo cơ ô mô cái, mất cảm giác nặng, điện cơ tổn thương nặng thì hội chẩn phẫu thuật giải ép","Cho thuốc thanh nhiệt hàn lương mạnh và châm tả mạnh","Hướng dẫn bổ sung sắt, ăn uống bồi dưỡng khí huyết","Tiêm corticoid vào ống cổ tay không chẩn đoán xác định và không theo dõi","Sàng lọc nguyên nhân: đái tháo đường, suy giáp, viêm khớp dạng thấp, thiếu máu, thai kỳ","Châm Đại lăng, Nội quan (Tâm bào), Ngoại quan (Tam tiêu), Hợp cốc (Đại trường), Tam âm giao (Tỳ)","Hướng dẫn nẹp cổ tay tư thế trung gian khi ngủ, nghỉ giải lao khi thao tác lặp lại","Chụp MRI não"]}}'::jsonb,
  '3655565477d678ec0d2f692ffffe32c49d8780618e22f3efd61c3fb554ef2498'
)
