do đái tháo đường","credit":"none"},{"text":"Hội chứng lối thoát lồng ngực","credit":"none"},{"text":"Viêm khớp dạng thấp","credit":"none"}],"bd":[{"text":"Uyển tý (chứng tý vùng cổ tay)","credit":"full"},{"text":"Cảnh tý","credit":"none"},{"text":"Trúng phong","credit":"none"},{"text":"Kiên tý","credit":"none"},{"text":"Huyễn vựng","credit":"none"}],"bc":[{"text":"Lý – Hư – Hàn","credit":"full"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"},{"text":"Biểu – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Huyết hư hàn ngưng","credit":"full"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Can dương thượng cang","credit":"none"},{"text":"Thấp nhiệt","credit":"none"},{"text":"Đàm thấp trở lạc","credit":"none"}],"phap":[{"text":"Ôn kinh tán hàn, dưỡng huyết thông mạch","credit":"full"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Bình can tiềm dương","credit":"none"},{"text":"Hoạt huyết hóa ứ mạnh","credit":"none"},{"text":"Kiện tỳ hóa đàm","credit":"none"}],"phuong":[{"text":"Đương quy tứ nghịch thang","credit":"full"},{"text":"Quyên tý thang","credit":"none"},{"text":"Thiên ma câu đằng ẩm","credit":"none"},{"text":"Bạch hổ thang","credit":"none"},{"text":"Ngân kiều tán","credit":"none"}],"huyet":[{"text":"Đại lăng","credit":"full"},{"text":"Nội quan","credit":"full"},{"text":"Ngoại quan","credit":"full"},{"text":"Hợp cốc","credit":"full"},{"text":"Tam âm giao","credit":"full"},{"text":"Dũng tuyền","credit":"none"},{"text":"Thái xung","credit":"none"},{"text":"Phong trì","credit":"none"},{"text":"Yêu dương quan","credit":"none"}]},"action_options":[{"text":"Châm Đại lăng, Nội quan (Tâm bào), Ngoại quan (Tam tiêu), Hợp cốc (Đại trường), Tam âm giao (Tỳ)","time_minutes":25,"grade":"recommended","rationale":"Ôn kinh, dưỡng huyết, thông kinh lạc vùng ống cổ tay."},{"text":"Sàng lọc nguyên nhân: đái tháo đường, suy giáp, viêm khớp dạng thấp, thiếu máu, thai kỳ","time_minutes":4,"grade":"recommended","rationale":"Điều trị nguyên nhân kèm theo."},{"text":"Đánh giá mức độ: teo cơ ô mô cái, mất cảm giác nặng, điện cơ tổn thương nặng thì hội chẩn phẫu thuật giải ép","time_minutes":3,"grade":"recommended","rationale":"Chỉ định ngoại khoa khi nặng hoặc điều trị nội khoa thất bại."},{"text":"Hướng dẫn nẹp cổ tay tư thế trung gian khi ngủ, nghỉ giải lao khi thao tác lặp lại","time_minutes":3,"grade":"recommended","rationale":"Giảm áp lực trong ống cổ tay."},{"text":"Hướng dẫn bổ sung sắt, ăn uống bồi dưỡng khí huyết","time_minutes":3,"grade":"recommended","rationale":"Thiếu máu nhẹ kèm theo, cần xử trí theo bác sĩ."},{"text":"Chụp MRI não","time_minutes":45,"grade":"waste","rationale":"Không có chỉ định."},{"text":"Cho thuốc thanh nhiệt hàn lương mạnh và châm tả mạnh","time_minutes":3,"grade":"harmful","rationale":"Thể huyết hư hàn ngưng, thuốc hàn làm huyết ngưng nặng hơn."},{"text":"Tiêm corticoid vào ống cổ tay không chẩn đoán xác định và không theo dõi","time_minutes":5,"grade":"harmful","rationale":"Nguy cơ tổn thương thần kinh giữa, chỉ làm khi có chỉ định chuyên khoa."}],"teaching_explanation":"Tê ngón 1, 2, 3 và nửa ngón 4, nặng về đêm, Tinel và Phalen dương tính là điển hình của hội chứng ống cổ tay. Ngón út không tê và Spurling âm tính giúp loại trừ chèn ép rễ cổ. Thể huyết hư hàn ngưng: mặt nhợt, tay lạnh, lưỡi nhạt, mạch tế trầm. Cần tìm bệnh nền (đái tháo đường, suy giáp, thiếu máu, thai kỳ) và dấu hiệu nặng (teo ô mô cái) cần ngoại khoa."}'::jsonb,
