insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'viem-quanh-khop-vai-dong-cung',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"viem-quanh-khop-vai-dong-cung","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau vai trái nhiều về đêm, không giơ tay chải đầu được","setting":"chamcuu","level":"Dễ","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":55,"sex":"nữ","patient_label":"Bà Hoàng Thị Thu"},"presentation":{"intro":"Bà đến vì đau vai trái 3 tháng, tăng dần, đau nhiều về đêm, giờ không giơ tay lên chải đầu hay cài áo ngực phía sau được.","place":"Phòng châm cứu","clock":"09:30","night":false},"vitals":{"hr":76,"sbp":128,"dbp":78,"rr":18,"temperature_c":36.6,"spo2":98},"history":[{"question":"Đau vai bắt đầu thế nào, có chấn thương không?","response":"Đau dần dần, không té ngã, không chấn thương rõ. Đau vai trái, lan nhẹ xuống mặt ngoài cánh tay."},{"question":"Đau tăng khi nào?","response":"Đau tăng khi giơ tay, vắt tay ra sau lưng, nằm đè lên vai trái. Đêm đau thức giấc."},{"question":"Hạn chế vận động thế nào?","response":"Giơ tay chỉ lên ngang vai, không gãi được lưng, không cài áo ngực. Tay còn cầm nắm bình thường."},{"question":"Có đau ngực, khó thở, vã mồ hôi, đau lan hàm khi gắng sức không?","response":"Không đau ngực, không khó thở, không vã mồ hôi."},{"question":"Có sốt, ho kéo dài, ho ra máu, sụt cân, sụp mi không?","response":"Không sốt, không ho ra máu, không sụt cân, mắt bình thường. Không hút thuốc."},{"question":"Trời lạnh, chườm ấm ảnh hưởng ra sao?","response":"Trời lạnh, ngủ quạt thổi vào vai thì đau tăng. Chườm ấm thì đỡ."},{"question":"Bệnh nền?","response":"Đái tháo đường típ 2, đang uống thuốc đều, chưa biến chứng."},{"question":"Ăn, ngủ, đại tiểu tiện?","response":"Ngủ kém vì đau, ăn bình thường, đại tiểu tiện bình thường."},{"question":"Đã dùng thuốc gì?","response":"Uống thuốc giảm đau 2 tuần, đỡ ít."}],"examination":[{"group":"V","item":"Thần sắc, tư thế vai","finding":"Tinh thần tỉnh táo, vai trái hơi nhô, tay trái khép sát thân."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi nhạt, rêu trắng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói rõ, hơi thở bình thường."},{"group":"T","item":"Mạch","finding":"Mạch phù khẩn."},{"group":"T","item":"Sờ khớp vai","finding":"Sờ vùng vai trái lạnh hơn bên phải, ấn đau rãnh nhị đầu và vùng trước khớp vai."},{"group":"K","item":"Tầm vận động chủ động và thụ động khớp vai","finding":"Dạng chủ động 80 độ, thụ động 85 độ, xoay ngoài chủ động và thụ động 20 độ, xoay trong tới mông. Hạn chế đồng đều cả hai."},{"group":"K","item":"Khám tim phổi, mạch, huyết áp hai tay","finding":"Nhịp đều, phổi trong, mạch quay hai tay đều, không dấu hiệu bệnh tim phổi."},{"group":"K","item":"Khám thần kinh chi trên và cột sống cổ","finding":"Cơ lực 5/5, cảm giác bình thường, Spurling âm tính."}],"investigations":[{"name":"X-quang khớp vai thẳng và nghiêng","duration_minutes":15,"result":"Không có tổn thương xương, loãng xương nhẹ vùng đầu xương cánh tay."},{"name":"Siêu âm khớp vai","duration_minutes":15,"result":"Dày bao khớp, tràn dịch nhẹ bao hoạt dịch, gân chóp xoay không đứt hoàn toàn."},{"name":"Đường huyết đói và HbA1c","duration_minutes":20,"result":"Đường huyết đói 7,4 mmol/L, HbA1c 7,2 phần trăm."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp xoang, không có thay đổi thiếu máu cục bộ."},{"name":"CT ngực có cản quang","duration_minutes":40,"result":"Không có chỉ định, không có dấu hiệu nghi ngờ u đỉnh phổi."}],"choices":{"diagnosis":{"ydx":["Rách chóp xoay hoàn toàn","Viêm quanh khớp vai thể đông cứng (viêm bao khớp dính)","Đau vai do bệnh tim thiếu máu cục bộ","Viêm khớp vai nhiễm khuẩn","Hội chứng cổ vai cánh tay do chèn ép rễ"],"bd":["Hung tý","Cảnh tý","Kiên ngưng (Ngũ thập kiên)","Hạng cường","Thống phong"],"bc":["Lý – Thực – Nhiệt","Biểu – Thực – Nhiệt","Lý – Hư – Nhiệt","Lý – Hư – Hàn","Biểu – Thực – Hàn"],"the":["Can thận hư","Phong hàn thấp tý","Thấp nhiệt tý","Khí trệ huyết ứ","Đàm thấp trở lạc"],"phap":["Khu phong tán hàn trừ thấp, thông kinh hoạt lạc","Kiện tỳ hóa đàm","Hoạt huyết hóa ứ","Thanh nhiệt lợi thấp","Bổ can thận"],"phuong":["Bình vị tán","Thân thống trục ứ thang","Lục vị địa hoàng hoàn","Quyên tý thang","Bạch hổ gia quế chi thang"],"huyet":["Kiên liêu","Tý nhu","Thái khê","Kiên ngung","Điều khẩu","Dũng tuyền","Thiên khu","Kiên trinh","Quan nguyên"]},"actions":["Châm Kiên ngung, Tý nhu (Đại trường), Kiên liêu (Tam tiêu), Kiên trinh (Tiểu trường), Điều khẩu (Vị), kèm cứu hoặc đèn hồng ngoại","Dặn kiểm soát đường huyết tốt","Châm sâu, kích thích mạnh khi chưa loại trừ đau vai do bệnh tim","Chụp CT ngực có cản quang","Chườm ấm vùng vai trước khi tập","Bẻ, kéo mạnh khớp vai dưới gây mê hoặc không gây mê tại phòng châm","Loại trừ đau vai do bệnh tim (ECG, đau ngực gắng sức), u đỉnh phổi, rách chóp xoay hoàn toàn, nhiễm khuẩn","Hướng dẫn tập vận động khớp vai từ từ (con lắc, leo tường) trong ngưỡng đau"]}}'::jsonb,
  '78c34c70aca617fa1ddfa8ca82f670ccfa0bb207480036898321e58846ba0303'
)
