bao khớp dính)","credit":"full"},{"text":"Rách chóp xoay hoàn toàn","credit":"none"},{"text":"Hội chứng cổ vai cánh tay do chèn ép rễ","credit":"none"},{"text":"Đau vai do bệnh tim thiếu máu cục bộ","credit":"none"},{"text":"Viêm khớp vai nhiễm khuẩn","credit":"none"}],"bd":[{"text":"Kiên ngưng (Ngũ thập kiên)","credit":"full"},{"text":"Cảnh tý","credit":"none"},{"text":"Hạng cường","credit":"none"},{"text":"Thống phong","credit":"none"},{"text":"Hung tý","credit":"none"}],"bc":[{"text":"Biểu – Thực – Hàn","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Lý – Thực – Nhiệt","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Phong hàn thấp tý","credit":"full"},{"text":"Khí trệ huyết ứ","credit":"none"},{"text":"Can thận hư","credit":"none"},{"text":"Thấp nhiệt tý","credit":"none"},{"text":"Đàm thấp trở lạc","credit":"none"}],"phap":[{"text":"Khu phong tán hàn trừ thấp, thông kinh hoạt lạc","credit":"full"},{"text":"Bổ can thận","credit":"none"},{"text":"Thanh nhiệt lợi thấp","credit":"none"},{"text":"Hoạt huyết hóa ứ","credit":"none"},{"text":"Kiện tỳ hóa đàm","credit":"none"}],"phuong":[{"text":"Quyên tý thang","credit":"full"},{"text":"Bạch hổ gia quế chi thang","credit":"none"},{"text":"Thân thống trục ứ thang","credit":"none"},{"text":"Lục vị địa hoàng hoàn","credit":"none"},{"text":"Bình vị tán","credit":"none"}],"huyet":[{"text":"Kiên ngung","credit":"full"},{"text":"Kiên liêu","credit":"full"},{"text":"Kiên trinh","credit":"full"},{"text":"Tý nhu","credit":"full"},{"text":"Điều khẩu","credit":"full"},{"text":"Dũng tuyền","credit":"none"},{"text":"Thái khê","credit":"none"},{"text":"Quan nguyên","credit":"none"},{"text":"Thiên khu","credit":"none"}]},"action_options":[{"text":"Châm Kiên ngung, Tý nhu (Đại trường), Kiên liêu (Tam tiêu), Kiên trinh (Tiểu trường), Điều khẩu (Vị), kèm cứu hoặc đèn hồng ngoại","time_minutes":25,"grade":"recommended","rationale":"Khu hàn trừ thấp, thông kinh lạc vùng vai."},{"text":"Loại trừ đau vai do bệnh tim (ECG, đau ngực gắng sức), u đỉnh phổi, rách chóp xoay hoàn toàn, nhiễm khuẩn","time_minutes":5,"grade":"recommended","rationale":"Đau vai có thể là triệu chứng của bệnh nội tạng."},{"text":"Hướng dẫn tập vận động khớp vai từ từ (con lắc, leo tường) trong ngưỡng đau","time_minutes":5,"grade":"recommended","rationale":"Phục hồi tầm vận động, tránh dính khớp."},{"text":"Dặn kiểm soát đường huyết tốt","time_minutes":2,"grade":"recommended","rationale":"Đái tháo đường là yếu tố nguy cơ."},{"text":"Chườm ấm vùng vai trước khi tập","time_minutes":10,"grade":"recommended","rationale":"Hợp thể hàn thấp."},{"text":"Chụp CT ngực có cản quang","time_minutes":40,"grade":"waste","rationale":"Không cần thiết."},{"text":"Bẻ, kéo mạnh khớp vai dưới gây mê hoặc không gây mê tại phòng châm","time_minutes":5,"grade":"harmful","rationale":"Nguy cơ gãy xương, rách cơ và chóp xoay, nhất là khi loãng xương."},{"text":"Châm sâu, kích thích mạnh khi chưa loại trừ đau vai do bệnh tim","time_minutes":3,"grade":"harmful","rationale":"Bỏ sót cơn đau thắt ngực, nhồi máu cơ tim."}],"teaching_explanation":"Hạn chế đồng đều tầm vận động cả chủ động và thụ động, đau đêm, tuổi 40 đến 60, đái tháo đường là điển hình viêm bao khớp dính, khác rách chóp xoay (chủ động hạn chế nhiều hơn thụ động). Thể phong hàn thấp tý: sợ lạnh, mạch phù khẩn. Luôn loại trừ đau vai do tim, phổi, cổ trước khi điều trị."}'::jsonb,
  '0dcea893fc47b6a03b92d9f133e9c9cb546bc40b0245613e70a1aaa7c655502d'
)
