insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'dau-nua-dau-can-duong-thuong-cang',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"dau-nua-dau-can-duong-thuong-cang","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Đau nửa đầu từng cơn kèm buồn nôn, sợ ánh sáng","setting":"chamcuu","level":"Trung bình","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":34,"sex":"nữ","patient_label":"Chị Vũ Thị Hồng"},"presentation":{"intro":"Chị là nhân viên văn phòng, đến vì các cơn đau nửa đầu tái phát khoảng 1 năm nay, mấy tháng gần đây cơn dày hơn khi áp lực công việc.","place":"Phòng châm cứu","clock":"16:00","night":false},"vitals":{"hr":80,"sbp":118,"dbp":76,"rr":17,"temperature_c":36.7,"spo2":99},"history":[{"question":"Đau đầu như thế nào, vị trí nào?","response":"Đau nhói, giật theo nhịp mạch ở thái dương và hốc mắt một bên, thường bên trái, đôi khi đổi bên."},{"question":"Mỗi cơn kéo dài bao lâu, bao nhiêu cơn mỗi tháng?","response":"Mỗi cơn 6 đến 12 giờ, khoảng 3 đến 4 cơn mỗi tháng. Giữa các cơn hoàn toàn bình thường."},{"question":"Có buồn nôn, sợ ánh sáng, sợ tiếng động, có báo trước không?","response":"Buồn nôn, sợ ánh sáng, sợ tiếng ồn. Cơn thường kèm mờ mắt thoáng qua, thấy chớp sáng khoảng 20 phút trước đau."},{"question":"Có yếu liệt, nói khó, lú lẫn, co giật không?","response":"Không, hết chớp sáng thì nhìn rõ lại, không yếu liệt, không nói khó."},{"question":"Đau đầu bất thường: dữ dội đột ngột, sốt cứng gáy, đau tăng khi ho hoặc nằm, mới xuất hiện sau 50 tuổi không?","response":"Đau không dữ dội đột ngột, không sốt, không cứng gáy, không đau tăng khi ho. Đau bắt đầu từ năm 33 tuổi."},{"question":"Yếu tố khởi phát?","response":"Hay bùng phát khi tức giận, căng thẳng, thiếu ngủ, ăn đồ cay nóng, trước kỳ kinh."},{"question":"Tính tình, miệng, giấc ngủ?","response":"Hay cáu gắt, miệng đắng, họng khô, ngủ nông, hay mơ."},{"question":"Đại tiểu tiện, kinh nguyệt?","response":"Táo bón, nước tiểu vàng. Kinh nguyệt đều, hay đau đầu trước kỳ."},{"question":"Thuốc đang dùng, có dùng thuốc tránh thai không?","response":"Không dùng thuốc tránh thai. Uống ibuprofen khi đau, đỡ một phần."},{"question":"Tiền sử gia đình?","response":"Mẹ hay bị đau nửa đầu."}],"examination":[{"group":"V","item":"Thần sắc","finding":"Sắc mặt hơi đỏ, mắt đỏ nhẹ, vẻ mặt bực bội."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi đỏ, bờ lưỡi đỏ, rêu vàng mỏng."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói to, hơi thở hơi nặng mùi."},{"group":"T","item":"Mạch","finding":"Mạch huyền sác."},{"group":"T","item":"Sờ vùng đầu cổ","finding":"Cơ thái dương, cơ chẩm trái co cứng, ấn đau điểm Phong trì và Thái dương."},{"group":"K","item":"Khám thần kinh sọ não","finding":"Đồng tử đều phản xạ tốt, thị trường bình thường, vận nhãn bình thường, cơ lực và cảm giác bình thường, không dấu hiệu thần kinh khu trú."},{"group":"K","item":"Dấu màng não, soi đáy mắt","finding":"Không cứng gáy, Kernig và Brudzinski âm tính. Đáy mắt: gai thị rõ bờ, không phù gai."},{"group":"K","item":"Huyết áp, khám tim mạch","finding":"Huyết áp 118/76 mmHg, tim phổi bình thường."}],"investigations":[{"name":"Công thức máu, tốc độ máu lắng, CRP","duration_minutes":20,"result":"Bình thường."},{"name":"Soi đáy mắt","duration_minutes":10,"result":"Không phù gai thị."},{"name":"Đo huyết áp 24 giờ","duration_minutes":30,"result":"Huyết áp trung bình bình thường."},{"name":"CT sọ não không cản quang","duration_minutes":20,"result":"Không có tổn thương. Không cần chụp thường quy ở đau nửa đầu điển hình, không dấu cảnh báo."},{"name":"Chụp mạch máu não (MRA, DSA)","duration_minutes":60,"result":"Không có chỉ định ở ca này."}],"choices":{"diagnosis":{"ydx":["Đau đầu căng thẳng","Đau đầu từng cụm","Đau nửa đầu (migraine) có tiền triệu thị giác","Viêm màng não","Xuất huyết dưới nhện"],"bd":["Thiên đầu thống","Huyễn vựng","Chân đầu thống","Đầu phong thống do ngoại cảm","Trúng phong"],"bc":["Lý – Thực – Nhiệt","Lý – Hư – Hàn","Biểu – Thực – Nhiệt","Lý – Hư – Nhiệt","Biểu – Thực – Hàn"],"the":["Phong hàn thượng phạm","Đàm thấp thượng nhiễu","Khí huyết hư","Can uất khí trệ","Can dương thượng cang"],"phap":["Bổ khí dưỡng huyết","Sơ phong tán hàn","Sơ can giải uất","Hóa đàm trừ thấp","Bình can tiềm dương, tức phong chỉ thống"],"phuong":["Xuyên khung trà điều tán","Bán hạ bạch truật thiên ma thang","Thiên ma câu đằng ẩm","Bổ trung ích khí thang","Quy tỳ thang"],"huyet":["Hợp cốc","Khí hải","Thái xung","Túc tam lý","Phong trì","Suất cốc","Quan nguyên","Thái dương","Thận du"]},"actions":["Châm Phong trì, Suất cốc (Đởm), Thái dương (ngoài kinh), Thái xung (Can), Hợp cốc (Đại trường)","Sàng lọc dấu hiệu cảnh báo đau đầu thứ phát: đột ngột dữ dội, sốt cứng gáy, dấu thần kinh khu trú, phù gai thị, khởi phát sau 50 tuổi","Cho thuốc ôn bổ cay nóng (Phụ tử, Quế chi liều cao)","Dặn dùng thuốc cắt cơn đúng chỉ định, tránh lạm dụng giảm đau hằng ngày","Dặn đến cấp cứu ngay nếu đau dữ dội đột ngột, yếu liệt, nói khó, sốt cứng gáy, co giật","Chụp CT sọ não thường quy","Châm sâu, kích thích mạnh vùng cổ gáy khi chưa loại trừ nguyên nhân thực thể","Hướng dẫn ghi nhật ký đau đầu, tránh yếu tố khởi phát (thiếu ngủ, rượu, thực phẩm cay nóng)"]}}'::jsonb,
  'ffc1548227c2471d3589a6182f67595d9a473a2ee4f2bd16d9a1ddd5e75ea3b3'
)
