ẩn đoán và điều trị bệnh theo y học cổ truyền, kết hợp y học cổ truyền với y học hiện đại, Quyết định 5013/QĐ-BYT, 2020.","checked_date":null,"reviewer":null,"review_status":"CHUA_DUYET","license":null,"provenance_tags":["legacy_unverified"]}],"after_submission_notes":[],"history_essential_indices":[0,1,2,3,4,5,6],"examination_essential_indices":[1,3,5,6],"investigation_roles":[{"index":0,"role":"neutral"},{"index":1,"role":"essential"},{"index":2,"role":"neutral"},{"index":3,"role":"waste"},{"index":4,"role":"waste"}],"diagnosis_options":{"ydx":[{"text":"Đau nửa đầu (migraine) có tiền triệu thị giác","credit":"full"},{"text":"Đau đầu căng thẳng","credit":"none"},{"text":"Đau đầu từng cụm","credit":"none"},{"text":"Xuất huyết dưới nhện","credit":"none"},{"text":"Viêm màng não","credit":"none"}],"bd":[{"text":"Thiên đầu thống","credit":"full"},{"text":"Huyễn vựng","credit":"none"},{"text":"Trúng phong","credit":"none"},{"text":"Chân đầu thống","credit":"none"},{"text":"Đầu phong thống do ngoại cảm","credit":"none"}],"bc":[{"text":"Lý – Thực – Nhiệt","credit":"full"},{"text":"Lý – Hư – Hàn","credit":"none"},{"text":"Biểu – Thực – Hàn","credit":"none"},{"text":"Biểu – Thực – Nhiệt","credit":"none"},{"text":"Lý – Hư – Nhiệt","credit":"none"}],"the":[{"text":"Can dương thượng cang","credit":"full"},{"text":"Can uất khí trệ","credit":"none"},{"text":"Đàm thấp thượng nhiễu","credit":"none"},{"text":"Khí huyết hư","credit":"none"},{"text":"Phong hàn thượng phạm","credit":"none"}],"phap":[{"text":"Bình can tiềm dương, tức phong chỉ thống","credit":"full"},{"text":"Sơ can giải uất","credit":"none"},{"text":"Hóa đàm trừ thấp","credit":"none"},{"text":"Bổ khí dưỡng huyết","credit":"none"},{"text":"Sơ phong tán hàn","credit":"none"}],"phuong":[{"text":"Thiên ma câu đằng ẩm","credit":"full"},{"text":"Xuyên khung trà điều tán","credit":"none"},{"text":"Bán hạ bạch truật thiên ma thang","credit":"none"},{"text":"Bổ trung ích khí thang","credit":"none"},{"text":"Quy tỳ thang","credit":"none"}],"huyet":[{"text":"Phong trì","credit":"full"},{"text":"Thái dương","credit":"full"},{"text":"Suất cốc","credit":"full"},{"text":"Thái xung","credit":"full"},{"text":"Hợp cốc","credit":"full"},{"text":"Túc tam lý","credit":"none"},{"text":"Quan nguyên","credit":"none"},{"text":"Thận du","credit":"none"},{"text":"Khí hải","credit":"none"}]},"action_options":[{"text":"Châm Phong trì, Suất cốc (Đởm), Thái dương (ngoài kinh), Thái xung (Can), Hợp cốc (Đại trường)","time_minutes":25,"grade":"recommended","rationale":"Bình can tiềm dương, thông lạc chỉ thống."},{"text":"Sàng lọc dấu hiệu cảnh báo đau đầu thứ phát: đột ngột dữ dội, sốt cứng gáy, dấu thần kinh khu trú, phù gai thị, khởi phát sau 50 tuổi","time_minutes":5,"grade":"recommended","rationale":"Loại trừ xuất huyết dưới nhện, viêm màng não, u não trước khi điều trị châm cứu."},{"text":"Hướng dẫn ghi nhật ký đau đầu, tránh yếu tố khởi phát (thiếu ngủ, rượu, thực phẩm cay nóng)","time_minutes":4,"grade":"recommended","rationale":"Dự phòng cơn."},{"text":"Dặn dùng thuốc cắt cơn đúng chỉ định, tránh lạm dụng giảm đau hằng ngày","time_minutes":3,"grade":"recommended","rationale":"Tránh đau đầu do lạm dụng thuốc."},{"text":"Dặn đến cấp cứu ngay nếu đau dữ dội đột ngột, yếu liệt, nói khó, sốt cứng gáy, co giật","time_minutes":2,"grade":"recommended","rationale":"Dấu hiệu nguy hiểm."},{"text":"Chụp CT sọ não thường quy","time_minutes":20,"grade":"waste","rationale":"Không có dấu cảnh báo."},{"text":"Cho thuốc ôn bổ cay nóng (Phụ tử, Quế chi liều cao)","time_minutes":2,"grade":"harmful","rationale":"Can dương thượng cang, thuốc nhiệt làm dương cang thêm."},{"text":"Châm sâu, kích thích mạnh vùng cổ gáy khi chưa loại trừ nguyên nhân thực thể","time_minutes":4,"grade":"harmful","rationale":"Nguy cơ biến chứng, bỏ sót đau đầu thứ phát."}],"teaching_explanation":"Đau nửa đầu giật theo mạch, kèm buồn nôn, sợ ánh sáng, có tiền triệu thị giác và giữa cơn bình thường là migraine điển hình, thường không cần chẩn đoán hình ảnh. Thể can dương thượng cang: cáu gắt, miệng đắng, lưỡi đỏ rêu vàng mỏng, mạch huyền sác. Phải hỏi dấu hiệu cảnh báo (đau đột ngột dữ dội, sốt cứng gáy, dấu thần kinh khu trú, khởi phát sau 50 tuổi)."}'::jsonb,
  'c11eb4a4c53fe5e0454b40c89aafe49ceff93245d64684dc01dfff988609ccac'
)
on conflict (case_id) do update set
  answer_key = excluded.answer_key,
  content_sha256 = excluded.content_sha256;

insert into can_lam_sang_private.case_bundles
  (case_id, schema_version, data_origin, review_status, public_bundle, content_sha256)
values (
  'di-chung-tai-bien-khi-hu-huyet-u',
  '1.0.0',
  'synthetic',
  'CHUA_DUYET',
  '{"schema_version":"1.0.0","case_id":"di-chung-tai-bien-khi-hu-huyet-u","data_origin":"synthetic","review_status":"CHUA_DUYET","title":"Liệt nửa người phải sau nhồi máu não 6 tuần","setting":"chamcuu","level":"Khó","track":"yhct","mode":"dongtay","specialty":null,"demographics":{"age":67,"sex":"nam","patient_label":"Ông Đặng Văn Hòa"},"presentation":{"intro":"Ông được xuất viện sau nhồi máu não 6 tuần trước. Ông được người nhà đưa đến để châm cứu phục hồi vì yếu liệt nửa người phải, đi lại khó.","place":"Phòng châm cứu","clock":"08:15","night":false},"vitals":{"hr":78,"sbp":150,"dbp":90,"rr":18,"temperature_c":36.6,"spo2":97},"history":[{"question":"Đợt đột quỵ xảy ra khi nào, điều trị thế nào?","response":"Cách đây 6 tuần, đột ngột yếu tay chân phải, nói khó, nhập viện, chẩn đoán nhồi máu não, được điều trị nội khoa, ra viện sau 10 ngày."},{"question":"Hiện nay yếu liệt ra sao?","response":"Tay phải yếu nhiều, nhấc lên ngang vai khó, nắm tay yếu. Chân phải kéo lê khi đi, phải chống gậy."},{"question":"Có đau đầu dữ dội, yếu nặng thêm đột ngột, nói khó hơn, nhìn đôi không?","response":"Không có đợt nặng thêm nào từ khi ra viện. Nói đã rõ hơn, hơi chậm."},{"question":"Có sặc khi ăn uống không?","response":"Thỉnh thoảng sặc khi uống nước loãng."},{"question":"Đang dùng thuốc gì, có tuân thủ không?","response":"Uống thuốc chống kết tập tiểu cầu, statin và thuốc hạ áp theo toa bác sĩ, uống đều."},{"question":"Tiền sử bệnh?","response":"Tăng huyết áp 10 năm, rối loạn mỡ máu. Không đái tháo đường, không rung nhĩ biết trước."},{"question":"Người có sợ lạnh, tay chân lạnh, mệt mỏi, khó thở khi gắng sức không?","response":"Mệt mỏi, hay đoản hơi, tay chân phải lạnh, sợ lạnh, ra mồ hôi tự nhiên."},{"question":"Tinh thần, giấc ngủ?","response":"Hay buồn, chán nản, ngủ kém."},{"question":"Ăn uống, đại tiểu tiện?","response":"Ăn kém, táo bón, tiểu bình thường."},{"question":"Có đau, sưng chân phải không?","response":"Chân phải hơi phù nhẹ ở cổ chân, không đau."}],"examination":[{"group":"V","item":"Thần sắc, tư thế, dáng đi","finding":"Tinh thần tỉnh nhưng mệt, sắc mặt nhợt. Miệng hơi méo nhẹ sang trái, đi chống gậy, bước chân phải lê, tay phải gập co nhẹ."},{"group":"V","item":"Lưỡi","finding":"Chất lưỡi tím nhạt, có điểm ứ huyết, bệu, rêu trắng mỏng. Lưỡi lệch nhẹ sang phải."},{"group":"M","item":"Giọng nói, hơi thở","finding":"Tiếng nói yếu, hơi chậm, phát âm hơi nhão. Hơi thở ngắn."},{"group":"T","item":"Mạch","finding":"Mạch tế sáp, trầm nhược."},{"group":"T","item":"Sờ chi bên liệt","finding":"Tay chân phải lạnh hơn bên trái, cổ chân phải phù nhẹ không đau."},{"group":"K","item":"Cơ lực chi bên liệt","finding":"Cơ lực tay phải 3/5, chân phải 3+/5. Trương lực tăng nhẹ kiểu co cứng ở tay, phản xạ gân xương tăng bên phải, Babinski dương tính phải."},{"group":"K","item":"Huyết áp và tim mạch","finding":"Huyết áp 150/90 mmHg, nhịp tim đều 78 lần mỗi phút, không âm thổi."},{"group":"K","item":"Khám khớp vai bên liệt, nuốt","finding":"Khớp vai phải hơi trễ, không đau khi vận động nhẹ. Nghiệm pháp nuốt nước: sặc nhẹ."}],"investigations":[{"name":"CT hoặc MRI sọ não","duration_minutes":30,"result":"Ổ nhồi máu cũ vùng nhân bèo hạch nền và bao trong trái, không có chảy máu hay ổ nhồi máu mới."},{"name":"Điện tâm đồ","duration_minutes":5,"result":"Nhịp xoang, không rung nhĩ."},{"name":"Siêu âm Doppler động mạch cảnh và đốt sống","duration_minutes":20,"result":"Mảng xơ vữa động mạch cảnh trong hai bên, hẹp dưới 50 phần trăm."},{"name":"Lipid máu, đường huyết, chức năng thận","duration_minutes":30,"result":"LDL-C 3,2 mmol/L, đường huyết bình thường, chức năng thận bình thường."},{"name":"Chọc dò dịch não tủy","duration_minutes":30,"result":"Không có chỉ định ở ca này."}],"choices":{"diagnosis":{"ydx":["Tái phát đột quỵ cấp","Hội chứng tủy cổ","Bệnh lý rễ thần kinh","Xuất huyết não","Di chứng liệt nửa người phải sau nhồi máu não, giai đoạn phục hồi"],"bd":["Huyễn vựng","Hạc tất phong","Chứng nuy","Bán thân bất toại (di chứng trúng phong)","Cảnh tý"],"bc":["Lý – Hư kiêm Thực – Không hàn không nhiệt rõ","Biểu – Thực – Hàn","Biểu – Hư – Nhiệt","Lý – Thực – Nhiệt","Lý – Hư – Nhiệt"],"the":["Khí hư huyết ứ","Can dương thượng cang","Phong đàm trở lạc","Can thận âm hư","Thấp nhiệt"],"phap":["Hóa đàm khai khiếu","Tư bổ can thận âm","Thanh nhiệt giải độc","Bình can tiềm dương","Bổ khí, hoạt huyết, thông kinh hoạt lạc"],"phuong":["Thiên ma câu đằng ẩm","Địa hoàng ẩm tử","Độc hoạt tang ký sinh thang","Bổ dương hoàn ngũ thang","Trấn can tức phong thang"],"huyet":["Khúc trì","Kiên ngung","Hợp cốc","Nhân trung","Thiên khu","Túc tam lý","Dương lăng tuyền","Thập tuyên","Hoàn khiêu","Thần môn"]},"actions":["Châm Kiên ngung, Khúc trì, Hợp cốc (Đại trường), Hoàn khiêu, Dương lăng tuyền (Đởm), Túc tam lý (Vị) bên liệt, kèm điện châm cường độ nhẹ","Ngừng thuốc chống kết tập tiểu cầu và hạ áp để thay bằng thuốc YHCT hoạt huyết mạnh","Kéo giật mạnh khớp vai bên liệt khi tập thụ động","Phối hợp phục hồi chức năng: vận động trị liệu, ngôn ngữ trị liệu, đánh giá nuốt","Hỏi và đo đạc dấu hiệu đột quỵ tái phát hoặc nặng thêm (đột ngột yếu thêm, đau đầu dữ dội, nói khó, nhìn đôi)","Hướng dẫn tư thế đặt khớp vai bên liệt, chống đỡ vai, đánh giá phòng ngừa huyết khối tĩnh mạch sâu","Dặn tiếp tục thuốc chống kết tập tiểu cầu, statin, hạ áp theo toa, kiểm soát huyết áp, tái khám chuyên khoa thần kinh","Kiểm tra huyết áp trước khi châm, nếu từ 180/110 mmHg trở lên thì hoãn châm và xử trí tăng huyết áp","Chọc dò dịch não tủy","Châm kích thích mạnh, điện châm cường độ cao khi huyết áp chưa kiểm soát"]}}'::jsonb,
  '7c2e1ada50d122f1035c7b47ced925a808710b35fb86d5db2b6ff206f1cbabe7'
)
